INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C1','kor',5,1,'u2',1,'시간 표현의 뜻 — 시간 표현은 「지난 봄」 · 「다음 달」처럼 언제인지 알려 주는 말과 「다녀왔어」 · 「갈 거야」처럼 때를 드러내는 말끝을 함께 이르며, 곳이나 사람을 가리키는 말은 시간 표현이 아니다',ARRAY['6국04-05 문법']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C2','kor',5,1,'u2',1,'때가 다르면 말끝이 달라진다 — 이미 지난 일은 「다녀왔어」, 앞으로 할 일은 「갈 거야」처럼 같은 일이라도 언제의 일인지에 따라 말끝이 달라진다',ARRAY['6국04-05 문법']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C3','kor',5,1,'u2',1,'체험을 기록하면 좋은 점 — 겪은 일은 시간이 지나면 흐려지지만 글로 남기면 오래 간직하고 다른 사람에게 전할 수 있다',ARRAY['6국03-03 쓰기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C4','kor',5,1,'u2',1,'기행문의 뜻 — 기행문은 여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글이며, 다닌 곳과 시각만 적은 일정표나 쓴 돈의 목록은 기행문이 아니다',ARRAY['6국03-03 쓰기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C5','kor',5,1,'u2',1,'체험을 떠올리는 세 물음 — 체험을 글로 쓰려면 언제 있었던 일인지, 그때 무엇을 보았는지, 무엇을 느꼈는지를 함께 떠올리며, 이 단원은 시간 표현을 활용해 글 쓰기와 기행문 쓰기의 두 갈래로 배운다',ARRAY['6국03-03 쓰기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C6','kor',5,1,'u2',2,'과거를 나타내는 말끝 — 이미 지나간 일은 「내밀었다」 · 「갔다」처럼 말끝에 -았- / -었-을 넣어 나타낸다',ARRAY['6국04-05 문법']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C7','kor',5,1,'u2',2,'현재를 나타내는 말끝 — 지금 일어나고 있는 일은 「떨어진다」 · 「먹는다」처럼 말끝에 -는- / -ㄴ-을 넣어 나타낸다',ARRAY['6국04-05 문법']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C8','kor',5,1,'u2',2,'미래를 나타내는 말끝 — 앞으로 일어날 일은 「내밀 것이다」 · 「가겠다」처럼 -(으)ㄹ 것이나 -겠-으로 나타낸다',ARRAY['6국04-05 문법']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C9','kor',5,1,'u2',2,'말끝을 나누어 보기 — 「배웠다」를 「배우-」 · 「-었-」 · 「-다」로 나누어 보면 때를 알려 주는 부분이 「-었-」임을 알 수 있다',ARRAY['6국04-05 문법']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C10','kor',5,1,'u2',2,'-는- / -ㄴ-이 늘 지금만은 아니다 — -는- / -ㄴ-은 되풀이되는 일(염소는 풀을 먹는다) · 가까운 앞일(내일 서울에 간다) · 지난 일을 생생하게 말할 때에도 쓰이며, 「하늘이 참 푸르다」처럼 이 말끝이 없어도 지금을 나타낼 수 있다',ARRAY['6국04-05 문법']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C11','kor',5,1,'u2',2,'때를 나타내는 낱말 — 말끝 말고도 아까(조금 전에) · 지금 · 이제(바로 이때) · 이따 · 이따가(조금 지난 뒤에) · 곧(오래지 않아)처럼 때를 알려 주는 낱말이 있다',ARRAY['6국04-05 문법']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C12','kor',5,1,'u2',2,'때를 나타내는 말과 말끝은 대개 어울린다 — 「아까 우유를 마셨다」처럼 때를 나타내는 말과 말끝이 어울려야 읽는 사람이 헷갈리지 않으며, 「아까 우유를 마실 것이다」는 어색하다',ARRAY['6국04-05 문법']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C13','kor',5,1,'u2',2,'어긋나 보여도 틀린 말이 아닌 때 — 「드디어 내일 소풍 간다」 · 「지금 숙제 다 했어」처럼 겉보기에 어긋나 보여도 말끝은 때 말고도 여러 일을 하므로 틀린 말이 아니며, 소리 내어 읽어 보고 어색하지 않으면 고치지 않아도 된다',ARRAY['6국04-05 문법']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C14','kor',5,1,'u2',2,'두루 쓰이는 때의 말 — 「올해」는 지금 지나가고 있는 해라서 과거 · 현재 · 미래에 모두 쓰이고, 「이듬해」는 어떤 해의 바로 다음 해라서 과거와 미래 양쪽에 쓰인다',ARRAY['6국04-05 문법']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C15','kor',5,1,'u2',3,'날짜를 가리키는 우리말 — 오늘을 가운데에 두고 그끄저께(사흘 전) · 그저께(이틀 전) · 어제 · 오늘 · 내일 · 모레(이틀 뒤) · 글피(사흘 뒤)로 날짜를 가리킨다',ARRAY['6국04-05 문법']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C16','kor',5,1,'u2',3,'날수를 세는 우리말 — 날의 개수는 하루 · 이틀 · 사흘 · 나흘 · 닷새 · 엿새 · 이레 · 여드레 · 아흐레 · 열흘로 센다',ARRAY['6국04-05 문법']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C17','kor',5,1,'u2',3,'날짜 말과 날수 말 가르기 — 날짜를 가리키는 말은 「어느 날인지」를, 날수를 세는 말은 「며칠 동안인지」를 나타내므로 둘을 섞어 쓰면 뜻이 어긋난다',ARRAY['6국04-05 문법']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C18','kor',5,1,'u2',3,'사흘은 삼 일 — 사흘은 삼 일이고 사 일은 나흘이며, 「사」라는 소리 때문에 사흘을 사 일로 잘못 아는 경우가 많다',ARRAY['6국04-05 문법']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C19','kor',5,1,'u2',3,'본디부터 있던 우리말 — 이틀 · 사흘 · 나흘은 숫자에서 온 말이 아니라 본디부터 있던 우리말이므로 「2틀」 · 「3흘」처럼 숫자를 섞어 쓰면 틀린 표기가 된다',ARRAY['6국04-05 문법']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C20','kor',5,1,'u2',3,'금방 · 금세 — 「금방」과 「금세」는 앞뒤 문장에 따라 조금 전(비가 금방 그쳤다) · 곧(금방 그칠 거야) · 아주 빠르게(소문이 금세 퍼졌다)처럼 가리키는 때가 달라진다',ARRAY['6국04-05 문법']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C21','kor',5,1,'u2',3,'날짜 말과 날수 말로 계획 말하기 — 「모레부터 나흘 동안」처럼 언제 시작하는지는 날짜 말로, 며칠 동안인지는 날수 말로 구별해 함께 쓰면 계획이 또렷해진다',ARRAY['6국04-05 문법']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C22','kor',5,1,'u2',4,'체험 글의 시간 표현과 흐름 — 있었던 일을 쓴 글에서 말끝을 보고 과거 · 현재 · 미래 표현을 찾아 나누면 「예전 → 요즘 → 다음 달」처럼 글이 시간의 차례를 따라감을 알 수 있다',ARRAY['6국04-05 문법']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C23','kor',5,1,'u2',4,'때를 바꾸어 고쳐 쓰기 — 문장의 때를 바꿀 때에는 말끝과 함께 「아까 → 지금 → 이따」처럼 때를 나타내는 말도 알맞게 바꾼다',ARRAY['6국04-05 문법']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C24','kor',5,1,'u2',4,'체험 글 계획의 네 항목 — 있었던 일을 쓰기 전에 누구와 언제 어떤 활동을 했는지 · 그 활동을 한 까닭 · 보고 들은 것이나 새롭게 안 것 · 생각하거나 느낀 점을 정리한다',ARRAY['6국03-03 쓰기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C25','kor',5,1,'u2',4,'체험 글의 처음 · 가운데 · 끝 — 처음에는 일을 겪은 상황이나 까닭을, 가운데에는 있었던 일을 시간의 흐름에 따라 보고 들은 것과 느낀 점을, 끝에는 전체적인 느낌과 다짐을 쓴다',ARRAY['6국03-03 쓰기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C26','kor',5,1,'u2',4,'있었던 일이 드러나는 제목 — 제목은 「토요일」처럼 막연하게 붙이지 않고 「손끝으로 고친 책들」처럼 있었던 일이 잘 드러나게 붙인다',ARRAY['6국03-03 쓰기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C27','kor',5,1,'u2',4,'기준에 따라 고쳐 쓰기 — 쓴 글은 제목 · 처음 · 가운데 · 끝의 내용 · 있었던 일의 소개 · 생각이나 느낌 · 시간 표현의 쓰임을 기준으로 스스로 확인하며 고쳐 쓴다',ARRAY['6국04-05 문법']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C28','kor',5,1,'u2',4,'글을 나누고 말해 주기 — 고쳐 쓴 글을 친구들 앞에서 읽으면 듣는 사람은 시간의 흐름을 잘 따라올 수 있는지, 느낀 점이 드러나는지를 살펴 말해 준다',ARRAY['6국03-03 쓰기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C29','kor',5,1,'u2',7,'여정 — 여정은 여행하며 다닌 곳으로, 「먼저 동문으로 들어갔다」처럼 어디로 갔는지, 어디에서 어디로 옮겼는지가 드러나며 여정을 따라가면 글 전체의 흐름이 보인다',ARRAY['6국03-03 쓰기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C30','kor',5,1,'u2',7,'견문 — 견문은 여행하며 보고 들은 것으로, 눈으로 본 모습뿐 아니라 안내판에서 읽은 것과 다른 사람에게 들은 설명도 견문이다',ARRAY['6국03-03 쓰기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C31','kor',5,1,'u2',7,'감상 — 감상은 여행하며 생각하거나 느낀 것으로, 「~것 같았다」 · 「~는 생각이 들었다」처럼 마음속에서 일어난 것이 드러난다',ARRAY['6국03-03 쓰기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C32','kor',5,1,'u2',7,'견문과 감상을 가르는 물음 — 그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있으면 견문, 같은 것을 보아도 사람마다 다를 수 있으면 감상이다',ARRAY['6국03-03 쓰기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C33','kor',5,1,'u2',7,'한 문단 안에서 어우러지는 세 가지 — 좋은 기행문은 「대장간에 이르렀다(여정) → 쇠를 두드리고 계셨다(견문) → 조금 알 것 같았다(감상)」처럼 셋을 따로 떼지 않고 자연스럽게 잇는다',ARRAY['6국03-03 쓰기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C34','kor',5,1,'u2',7,'일정표와 일기와 기행문 — 여정만 있으면 일정표가 되고 감상만 있으면 일기에 가까워지며, 여정 · 견문 · 감상이 함께 있어야 기행문이다',ARRAY['6국03-03 쓰기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C35','kor',5,1,'u2',7,'가까운 곳도 기행문의 글감 — 먼 곳이나 이름난 곳에 다녀온 여행뿐 아니라 우리 동네 골목 · 현장 체험 학습 · 명절에 간 친척 집 · 가까운 시장이나 박물관도 다닌 곳과 보고 느낀 것이 있으면 기행문의 글감이다',ARRAY['6국03-03 쓰기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C36','kor',5,1,'u2',7,'기행문의 두 몫과 여러 형식 — 기행문은 그때의 느낌을 오래 새겨 두는 몫과 가 보지 않은 사람에게 그곳의 정보를 전하는 몫을 함께 지니며, 글과 사진뿐 아니라 그림 · 엽서 · 편지 · 동영상으로도 남길 수 있다',ARRAY['6국03-03 쓰기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C37','kor',5,1,'u2',9,'기행문의 처음 — 처음에는 여행지 이름 · 함께 간 사람 · 교통편 · 떠난 까닭과 기대 · 출발할 때의 날씨와 기분을 쓴다',ARRAY['6국03-03 쓰기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C38','kor',5,1,'u2',9,'기행문의 가운데 — 가운데에는 공간의 이동이나 시간의 흐름에 따라 다닌 곳마다 견문과 감상을 함께 쓴다',ARRAY['6국03-03 쓰기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C39','kor',5,1,'u2',9,'기행문의 끝 — 끝에는 여행하고 난 뒤의 전체적인 느낌 · 배운 것이나 더 알고 싶은 것 · 앞으로의 계획이나 각오를 쓴다',ARRAY['6국03-03 쓰기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C40','kor',5,1,'u2',9,'기행문의 제목 — 기행문의 제목은 여행지와 느낌이 함께 드러나게 붙인다',ARRAY['6국03-03 쓰기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C41','kor',5,1,'u2',9,'개요 짜기 — 기행문을 쓰기 전에 여행 사진이나 일기를 보며 기억에 남는 장면을 떠올리고, 쓸 여행 경험 하나를 골라 처음 · 가운데 · 끝에 들어갈 내용을 개요로 정리하며, 가운데는 다닌 곳별로 견문과 감상을 나란히 적는다',ARRAY['6국03-03 쓰기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C42','kor',5,1,'u2',9,'쓰기 과정 점검하기 — 계획하기 · 글쓰기 · 수정하기 가운데 아쉬웠던 단계를 짚어 보완할 점과 수정할 방법을 적어 두면 다음 글이 나아진다(여정 · 견문 · 감상을 한 문단씩 따로 썼다면 다닌 곳마다 어우러지게 다시 묶는다)',ARRAY['6국03-03 쓰기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C43','kor',5,1,'u2',12,'안내장에 들어갈 내용 — 여행지 안내장에는 그곳에 가려는 사람이 궁금해할 갈 만한 곳 · 먹을거리 · 즐길 거리 · 문화유산을 담는다',ARRAY['6국03-03 쓰기']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C44','kor',5,1,'u2',12,'안내장의 형태와 쓰임 — 관광 지도는 다닌 곳의 위치와 차례를, 그림엽서는 한 장면과 짧은 글로 인상을, 소책자는 여러 쪽에 자세한 설명을, 광고지는 한 면에 눈에 띄게 정리한 내용을 전한다',ARRAY['6국03-03 쓰기']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C45','kor',5,1,'u2',12,'공공 누리집 자료를 쓰는 태도 — 공공 누리집의 사진과 설명 자료는 쓸 수 있는 범위가 정해져 있으므로 이용 조건을 확인하고 출처를 밝혀 쓴다',ARRAY['6국03-03 쓰기']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C46','kor',5,1,'u2',12,'안내장에도 감상을 담는다 — 정보만 있으면 안내판이 되고 글쓴이의 느낌이 있어야 가 보고 싶어지므로, 안내장의 항목마다 내가 느낀 한 문장을 넣는다',ARRAY['6국03-03 쓰기']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C47','kor',5,1,'u2',12,'실천 활동은 반에서 함께 정한다 — 배운 것을 실천하는 활동은 안내장 하나로 정해져 있지 않고, 시간 여행으로 이야기 꾸미기 · 최고의 여행지 소개하기처럼 반에서 함께 정할 수 있다',ARRAY['6국03-03 쓰기']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C48','kor',5,1,'u2',12,'안내장 발표와 듣기 — 발표할 때에는 왜 이곳을 골랐는지부터 말하고, 듣는 사람은 가 보고 싶어졌는지와 어느 문구에서 그런 마음이 들었는지를 말해 준다',ARRAY['6국03-03 쓰기']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C49','kor',5,1,'u2',12,'두 소단원은 이어져 있다 — 기행문은 시간과 공간을 따라 움직이는 글이라 시간 표현이 흔들리면 다닌 길도 흐트러지므로, 시간 표현이 기행문의 뼈대를 세운다',ARRAY['6국03-03 쓰기']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C50','kor',5,1,'u2',12,'「이」로 끝나는 낱말 — 깨끗이 · 틈틈이 · 곰곰이 · 일일이 · 샅샅이 · 가까이처럼 「이」로 끝나는 낱말은 소리만으로 가리기 어려우므로 눈으로 익혀 둔다 (기초 다지기)',ARRAY['기초 다지기(이·히)']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K5-1-u2-C51','kor',5,1,'u2',12,'「히」로 끝나는 낱말 — 다행히 · 조용히 · 특별히 · 도저히 · 분명히 · 솔직히처럼 「히」로 끝나는 낱말을 문장 속에서 바르게 쓴다 (기초 다지기)',ARRAY['기초 다지기(이·히)']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X01','kor',5,'u2',ARRAY['K5-1-u2-C1']::text[],'「산책로」 · 「숲길」처럼 곳을 가리키는 말까지 시간 표현으로 고른다','언제인지 알려 주나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X02','kor',5,'u2',ARRAY['K5-1-u2-C2']::text[],'말끝이 달라진 까닭을 간 곳이나 말한 사람이 달라서라고 여긴다','지난 일 · 앞으로 할 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X03','kor',5,'u2',ARRAY['K5-1-u2-C3']::text[],'겪은 일은 적어 두지 않아도 오래 또렷하게 기억된다고 여긴다','기억은 흐려져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X04','kor',5,'u2',ARRAY['K5-1-u2-C4']::text[],'다닌 곳과 시각만 적은 일정표나 쓴 돈의 목록도 기행문이라고 여긴다','보고 느낀 것이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X05','kor',5,'u2',ARRAY['K5-1-u2-C6','K5-1-u2-C7','K5-1-u2-C8']::text[],'과거 · 현재 · 미래를 나타내는 말끝을 서로 바꾸어 안다','-었- · -ㄴ- · -ㄹ 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X06','kor',5,'u2',ARRAY['K5-1-u2-C9']::text[],'말끝에서 때를 알려 주는 부분을 낱말의 뿌리나 「-다」로 잘못 짚는다','나누어 보세요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X07','kor',5,'u2',ARRAY['K5-1-u2-C10']::text[],'-는- / -ㄴ-은 언제나 바로 지금 일어나는 일만 뜻한다고 여긴다','되풀이 · 가까운 앞일도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X08','kor',5,'u2',ARRAY['K5-1-u2-C10']::text[],'-는- / -ㄴ-이 붙지 않으면 지금을 나타내는 문장이 아니라고 여긴다','「하늘이 참 푸르다」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X09','kor',5,'u2',ARRAY['K5-1-u2-C11']::text[],'「아까」와 「이따」처럼 때를 나타내는 낱말의 앞뒤를 거꾸로 안다','조금 전 · 조금 뒤') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X10','kor',5,'u2',ARRAY['K5-1-u2-C12']::text[],'「아까 … 마실 것이다」처럼 때를 나타내는 말과 말끝이 어색하게 어울려도 그대로 둔다','소리 내어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X11','kor',5,'u2',ARRAY['K5-1-u2-C13']::text[],'「드디어 내일 소풍 간다」처럼 겉보기에 어긋나 보이는 문장을 모두 틀렸다고 여겨 고친다','어색하지 않으면 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X12','kor',5,'u2',ARRAY['K5-1-u2-C14']::text[],'「올해」나 「이듬해」를 한 가지 때에만 쓰는 말로 여긴다','두루 쓰여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X13','kor',5,'u2',ARRAY['K5-1-u2-C15']::text[],'그저께 · 모레 · 글피가 오늘에서 며칠 앞뒤인지 헷갈린다','오늘을 가운데에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X14','kor',5,'u2',ARRAY['K5-1-u2-C16']::text[],'닷새 · 엿새 · 이레처럼 날수를 세는 말의 차례를 헷갈린다','하루부터 차례로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X15','kor',5,'u2',ARRAY['K5-1-u2-C17']::text[],'「모레 동안」 · 「이틀에 간다」처럼 날짜 말과 날수 말을 섞어 쓴다','어느 날 · 며칠 동안') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X16','kor',5,'u2',ARRAY['K5-1-u2-C18']::text[],'「사」라는 소리 때문에 사흘을 사 일로 안다','사흘은 삼 일') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X17','kor',5,'u2',ARRAY['K5-1-u2-C19']::text[],'이틀 · 사흘을 「2틀」 · 「3흘」처럼 숫자를 섞어 쓴다','본디부터 있던 우리말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X18','kor',5,'u2',ARRAY['K5-1-u2-C20']::text[],'「금방」 · 「금세」가 늘 한 가지 때만 가리킨다고 여긴다','앞뒤 문장을 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X19','kor',5,'u2',ARRAY['K5-1-u2-C21']::text[],'계획을 말할 때 언제 시작하는지와 며칠 동안인지를 구별하지 않아 흐릿하게 말한다','날짜 말 + 날수 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X20','kor',5,'u2',ARRAY['K5-1-u2-C22']::text[],'글에서 시간 표현을 찾을 때 말끝을 보지 않아 「예전 → 요즘 → 다음 달」의 흐름을 놓친다','말끝이 때를 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X21','kor',5,'u2',ARRAY['K5-1-u2-C23']::text[],'때를 바꿀 때 말끝만 바꾸고 「아까」 같은 때를 나타내는 말은 그대로 두어 어색하게 만든다','때의 말도 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X22','kor',5,'u2',ARRAY['K5-1-u2-C24']::text[],'계획의 네 항목 가운데 활동을 한 까닭이나 느낀 점을 빠뜨린다','네 항목과 맞추어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X23','kor',5,'u2',ARRAY['K5-1-u2-C25']::text[],'다짐을 처음에 쓰거나 일을 겪은 까닭을 끝에 쓰는 것처럼 처음 · 가운데 · 끝의 내용을 뒤섞는다','상황 → 있었던 일 → 느낌과 다짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X24','kor',5,'u2',ARRAY['K5-1-u2-C25']::text[],'가운데 부분을 시간의 흐름과 상관없이 생각나는 대로 늘어놓는다','시간의 흐름에 따라') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X25','kor',5,'u2',ARRAY['K5-1-u2-C26']::text[],'「토요일」 · 「나의 하루」처럼 있었던 일이 드러나지 않는 제목을 붙인다','무슨 일이었나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X26','kor',5,'u2',ARRAY['K5-1-u2-C27']::text[],'고쳐 쓰기를 맞춤법만 살피는 일로 여겨 짜임 · 느낌 · 시간 표현은 확인하지 않는다','기준이 여럿이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X27','kor',5,'u2',ARRAY['K5-1-u2-C28']::text[],'친구의 글을 듣고 흐름이나 느낌이 아니라 글의 길이나 글씨만 말해 준다','흐름과 느낌을 살펴요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X28','kor',5,'u2',ARRAY['K5-1-u2-C29']::text[],'다닌 곳을 밝힌 문장과 보거나 느낀 것을 쓴 문장을 헷갈린다','어디로 갔나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X29','kor',5,'u2',ARRAY['K5-1-u2-C30']::text[],'안내판에서 읽거나 다른 사람에게 들은 설명은 견문이 아니라고 여긴다','들은 것도 견문') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X30','kor',5,'u2',ARRAY['K5-1-u2-C31']::text[],'마음속에서 일어난 생각을 보고 들은 사실로 여긴다','마음이 드러났나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X31','kor',5,'u2',ARRAY['K5-1-u2-C32']::text[],'견문과 감상을 문장의 길이나 꾸미는 말이 많고 적음으로 가른다','누구나 똑같이 확인할 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X32','kor',5,'u2',ARRAY['K5-1-u2-C33','K5-1-u2-C42']::text[],'여정 · 견문 · 감상을 한 문단씩 따로 떼어 써야 한다고 여긴다','다닌 곳마다 어우러지게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X33','kor',5,'u2',ARRAY['K5-1-u2-C34']::text[],'다닌 곳만 늘어놓거나 느낌만 써도 기행문이 된다고 여긴다','셋이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X34','kor',5,'u2',ARRAY['K5-1-u2-C35']::text[],'멀리 떠난 이름난 여행만 기행문의 글감이 된다고 여긴다','가까운 곳도 글감') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X35','kor',5,'u2',ARRAY['K5-1-u2-C36']::text[],'기행문은 느낌만 담는 글이고 글로만 남길 수 있다고 여긴다','두 몫 · 여러 형식') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X36','kor',5,'u2',ARRAY['K5-1-u2-C37']::text[],'떠난 까닭 · 기대 · 출발할 때의 날씨를 처음에 쓰지 않거나 끝으로 미룬다','떠나기 전과 막 도착했을 때') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X37','kor',5,'u2',ARRAY['K5-1-u2-C38']::text[],'가운데 부분에서 다닌 차례를 뒤섞거나 다닌 곳만 쓰고 견문과 감상을 빠뜨린다','다닌 곳마다 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X38','kor',5,'u2',ARRAY['K5-1-u2-C39']::text[],'끝부분에 새로 다닌 곳을 이어 쓰고 전체적인 느낌이나 앞으로의 계획은 빠뜨린다','돌아본 느낌과 계획') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X39','kor',5,'u2',ARRAY['K5-1-u2-C40']::text[],'제목에 여행지만 쓰거나 느낌만 써서 어떤 여행인지 짐작하기 어렵게 한다','여행지 + 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X40','kor',5,'u2',ARRAY['K5-1-u2-C41']::text[],'개요 없이 바로 쓰거나 여러 여행을 한 글에 섞어 쓴다','경험 하나 · 개요 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X41','kor',5,'u2',ARRAY['K5-1-u2-C42']::text[],'다 쓰면 끝이라고 여겨 쓰기 과정의 어느 단계가 아쉬웠는지 돌아보지 않는다','계획 · 쓰기 · 수정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X42','kor',5,'u2',ARRAY['K5-1-u2-C43']::text[],'안내장에 우리 집 주소나 내 시험 점수처럼 여행지와 관계없는 내용을 넣는다','가려는 사람이 궁금한 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X43','kor',5,'u2',ARRAY['K5-1-u2-C44']::text[],'전할 내용의 양과 방식에 맞지 않는 안내장 형태를 고른다','지도 · 엽서 · 소책자 · 광고지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X44','kor',5,'u2',ARRAY['K5-1-u2-C45']::text[],'누리집에 공개된 자료는 이용 조건을 보지 않고 출처 없이 가져다 써도 된다고 여긴다','조건 확인 · 출처 밝히기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X45','kor',5,'u2',ARRAY['K5-1-u2-C46']::text[],'안내장에는 관람 시간 같은 사실 정보만 넣고 감상은 넣지 않아도 된다고 여긴다','느낌이 마음을 옮겨요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X46','kor',5,'u2',ARRAY['K5-1-u2-C47']::text[],'배운 것을 실천하는 활동은 안내장 만들기 하나뿐이라고 여긴다','반에서 함께 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X47','kor',5,'u2',ARRAY['K5-1-u2-C48']::text[],'발표할 때 고른 까닭은 빼고 정보만 읽거나, 듣고 나서 어느 문구가 좋았는지 짚지 않는다','까닭부터 · 문구 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X48','kor',5,'u2',ARRAY['K5-1-u2-C49']::text[],'시간 표현 공부와 기행문 쓰기를 서로 관계없는 따로 떨어진 공부로 여긴다','시간 표현이 뼈대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X49','kor',5,'u2',ARRAY['K5-1-u2-C50']::text[],'「깨끗이」 · 「틈틈이」 · 「곰곰이」를 「히」로 잘못 쓴다','「이」로 끝나는 무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K5-1-u2-X50','kor',5,'u2',ARRAY['K5-1-u2-C51']::text[],'「조용히」 · 「솔직히」 · 「분명히」를 「이」로 잘못 쓴다','「히」로 끝나는 무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#1','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C1',1,'mc','auto','해든이의 말에서 언제인지 알려 주는 말은 어느 것인가요?',ARRAY['K5-1-u2-X01']::text[],false,'{"seq":1,"concept":"K5-1-u2-C1","difficulty":1,"kind":"mc","stem":"해든이의 말에서 언제인지 알려 주는 말은 어느 것인가요?","options":[{"t":"지난 봄에","correct":true},{"t":"강가","mis":"K5-1-u2-X01"},{"t":"산책로에","mis":"K5-1-u2-X01"},{"t":"나는","mis":"K5-1-u2-X01"}],"explanation":["곳을 가리키는 말이에요.","사람을 가리키는 말이에요.","「지난 봄에」가 때를 알려 줘요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#2','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C2',1,'mc','auto','해든이와 나린이의 말끝이 서로 다른 까닭은 무엇인가요?',ARRAY['K5-1-u2-X02']::text[],false,'{"seq":2,"concept":"K5-1-u2-C2","difficulty":1,"kind":"mc","stem":"해든이와 나린이의 말끝이 서로 다른 까닭은 무엇인가요?","options":[{"t":"해든이는 이미 다녀온 일을, 나린이는 앞으로 할 일을 말했기 때문이다","correct":true},{"t":"두 사람이 간 곳이 다르기 때문이다","mis":"K5-1-u2-X02"},{"t":"두 사람의 목소리가 다르기 때문이다","mis":"K5-1-u2-X02"},{"t":"나린이가 더 멀리 가기 때문이다","mis":"K5-1-u2-X02"}],"explanation":["곳은 말끝을 바꾸지 않아요.","말한 사람과도 관계없어요.","지난 일과 앞으로 할 일이라 말끝이 달라요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#3','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C3',1,'ox','auto','해든이가 산책로에서 본 것을 적어 두었다면 윤슬이에게 알려 줄 수 있었을 거예요.',ARRAY['K5-1-u2-X03']::text[],false,'{"seq":3,"concept":"K5-1-u2-C3","difficulty":1,"kind":"ox","stem":"해든이가 산책로에서 본 것을 적어 두었다면 윤슬이에게 알려 줄 수 있었을 거예요.","answer":"O","reason_options":[{"t":"글로 남기면 겪은 일을 오래 간직하고 다른 사람에게 전할 수 있기 때문에","correct":true},{"t":"겪은 일은 적지 않아도 늘 또렷이 기억나기 때문에","mis":"K5-1-u2-X03"}],"mis":"K5-1-u2-X03","explanation":["해든이는 기억이 잘 안 난다고 했어요.","기억은 시간이 지나면 흐려져요.","기록은 오래 남고 나눌 수 있어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#4','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C4',1,'mc','auto','기행문의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":4,"concept":"K5-1-u2-C4","difficulty":1,"kind":"mc","stem":"기행문의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글","correct":true},{"t":"여행에서 출발한 시각과 도착한 시각만 적은 글","mis":"K5-1-u2-X04"},{"t":"여행에 쓴 돈을 차례대로 적은 글","mis":"K5-1-u2-X04"},{"t":"가 보고 싶은 곳의 이름만 모은 글","mis":"K5-1-u2-X04"}],"explanation":["시각만 적으면 일정표예요.","돈을 적으면 목록이에요.","보고 듣고 느낀 것이 함께 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#5','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C1',2,'mc','auto','다음 가운데 시간 표현이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u2-X01']::text[],false,'{"seq":5,"concept":"K5-1-u2-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 시간 표현이 아닌 것은 어느 것인가요?","options":[{"t":"숲길","correct":true},{"t":"다음 달","mis":"K5-1-u2-X01"},{"t":"다녀왔어","mis":"K5-1-u2-X01"},{"t":"갈 거야","mis":"K5-1-u2-X01"}],"explanation":["「다음 달」은 언제인지 알려 줘요.","말끝도 때를 알려 줘요.","「숲길」은 곳을 가리키는 말이에요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#6','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C2',2,'blank','auto','빈칸에 알맞은 말을 고르세요. 「나는 어제 강가를 (　　).」',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":6,"concept":"K5-1-u2-C2","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말을 고르세요. 「나는 어제 강가를 (　　).」","options":[{"t":"걸었다","correct":true},{"t":"걷는다","mis":"K5-1-u2-X05"},{"t":"걸을 것이다","mis":"K5-1-u2-X05"},{"t":"걷겠다","mis":"K5-1-u2-X05"}],"explanation":["「어제」는 지난 때예요.","앞으로 할 일의 말끝은 어울리지 않아요.","지난 일이라 「걸었다」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#7','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C4',2,'mc','auto','다음 가운데 기행문에 가장 가까운 것은 어느 것인가요?',ARRAY['K5-1-u2-X04','K5-1-u2-X01']::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":2,"kind":"mc","stem":"다음 가운데 기행문에 가장 가까운 것은 어느 것인가요?","options":[{"t":"「강가 산책로를 따라 걸었다. 물새가 줄지어 날았는데, 마음까지 시원해지는 것 같았다.」","correct":true},{"t":"「아홉 시 출발, 열 시 도착, 열두 시 점심」","mis":"K5-1-u2-X04"},{"t":"「버스비, 간식값, 입장료」","mis":"K5-1-u2-X04"},{"t":"「다음 주에 가고 싶은 곳: 숲길, 강가」","mis":"K5-1-u2-X01"}],"explanation":["시각만 있는 일정표예요.","쓴 돈의 목록이에요.","다닌 곳 · 본 것 · 느낀 것이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#8','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C5',2,'mc','auto','이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":8,"concept":"K5-1-u2-C5","difficulty":2,"kind":"mc","stem":"이 단원에서 배우는 두 갈래로 알맞게 짝지은 것은 어느 것인가요?","options":[{"t":"시간 표현을 활용해 글 쓰기 · 기행문 쓰기","correct":true},{"t":"시간 표현을 활용해 글 쓰기 · 토론하기","mis":"K5-1-u2-X04"},{"t":"일정표 만들기 · 기행문 쓰기","mis":"K5-1-u2-X04"},{"t":"여행 비용 계산하기 · 일기 쓰기","mis":"K5-1-u2-X04"}],"explanation":["토론은 이 단원이 아니에요.","일정표는 기행문과 달라요.","시간 표현과 기행문을 배워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#9','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C3',2,'ox','auto','기억에 남는 체험을 떠올릴 때 언제 있었던 일인지, 무엇을 보고 느꼈는지도 함께 떠올리면 좋아요.',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":9,"concept":"K5-1-u2-C3","difficulty":2,"kind":"ox","stem":"기억에 남는 체험을 떠올릴 때 언제 있었던 일인지, 무엇을 보고 느꼈는지도 함께 떠올리면 좋아요.","answer":"O","reason_options":[{"t":"때와 본 것과 느낀 것이 있어야 체험을 글로 생생하게 쓸 수 있기 때문에","correct":true},{"t":"체험은 다닌 곳의 이름만 떠올리면 충분하기 때문에","mis":"K5-1-u2-X04"}],"mis":"K5-1-u2-X04","explanation":["세 가지 물음을 떠올려요.","곳의 이름만으로는 부족해요.","언제 · 무엇을 보고 · 무엇을 느꼈는지."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_basic#10','kor',5,1,'u2','L01','g5_1_kor_u2_L01_basic','lesson_basic','K5-1-u2-C5',3,'match','auto','같은 일을 때에 맞게 쓴 문장과 그 때를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C5","difficulty":3,"kind":"match","stem":"같은 일을 때에 맞게 쓴 문장과 그 때를 이으세요.","pairs":[{"l":"나는 어제 강가를 걸었다.","r":"과거"},{"l":"나는 지금 강가를 걷는다.","r":"현재"},{"l":"나는 내일 강가를 걸을 것이다.","r":"미래"}],"mis":"K5-1-u2-X05","explanation":["「어제」는 지난 때예요.","「지금」은 바로 이때예요.","말끝이 때를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#1','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C1',2,'mc','auto','윤슬이의 첫 말에서 지난 일과 앞으로의 일을 모두 물은 부분은 어느 것인가요?',ARRAY['K5-1-u2-X01','K5-1-u2-X02','K5-1-u2-X06']::text[],false,'{"seq":1,"concept":"K5-1-u2-C1","difficulty":2,"kind":"mc","stem":"윤슬이의 첫 말에서 지난 일과 앞으로의 일을 모두 물은 부분은 어느 것인가요?","options":[{"t":"「다녀왔거나 갈 계획」","correct":true},{"t":"「걷기 좋은 곳」","mis":"K5-1-u2-X01"},{"t":"「너희 요즘」","mis":"K5-1-u2-X02"},{"t":"「있어?」","mis":"K5-1-u2-X06"}],"explanation":["곳을 가리키는 말이에요.","「요즘」만으로는 지난 일과 앞일이 갈리지 않아요.","다녀왔거나 · 갈 계획이 두 때를 물어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#2','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',2,'ox','auto','다닌 곳의 차례만 빠짐없이 적으면 기행문이라고 할 수 있어요.',ARRAY['K5-1-u2-X04']::text[],false,'{"seq":2,"concept":"K5-1-u2-C4","difficulty":2,"kind":"ox","stem":"다닌 곳의 차례만 빠짐없이 적으면 기행문이라고 할 수 있어요.","answer":"X","reason_options":[{"t":"무엇을 보았는지와 무엇을 느꼈는지가 함께 담겨야 기행문이 되기 때문에","correct":true},{"t":"기행문은 다닌 곳의 차례가 가장 중요하기 때문에","mis":"K5-1-u2-X04"}],"mis":"K5-1-u2-X04","explanation":["차례만 있으면 일정표예요.","보고 느낀 것이 빠졌어요.","보고 들은 것 · 느낀 것이 함께 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#3','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C3',3,'mc','auto','해든이의 말 「적어 둘 걸 그랬어.」에 담긴 마음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X03','K5-1-u2-X02']::text[],false,'{"seq":3,"concept":"K5-1-u2-C3","difficulty":3,"kind":"mc","stem":"해든이의 말 「적어 둘 걸 그랬어.」에 담긴 마음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기록해 두지 않아 본 것을 나누지 못해 아쉬운 마음","correct":true},{"t":"산책로에 다시는 가고 싶지 않은 마음","mis":"K5-1-u2-X03"},{"t":"윤슬이가 묻는 것이 귀찮은 마음","mis":"K5-1-u2-X03"},{"t":"산책로가 너무 멀어서 힘들었던 마음","mis":"K5-1-u2-X02"}],"explanation":["그런 단서는 없어요.","귀찮아하는 말이 아니에요.","기억이 흐려져 아쉬워해요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#4','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C2',3,'mc','auto','「다음 달에 숲길을 걸으러 갈 거야.」를 지난 일로 바꾸어 말한 것은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X21','K5-1-u2-X05']::text[],false,'{"seq":4,"concept":"K5-1-u2-C2","difficulty":3,"kind":"mc","stem":"「다음 달에 숲길을 걸으러 갈 거야.」를 지난 일로 바꾸어 말한 것은 어느 것인가요?","options":[{"t":"「지난달에 숲길을 걸으러 갔어.」","correct":true},{"t":"「지난달에 숲길을 걸으러 갈 거야.」","mis":"K5-1-u2-X10"},{"t":"「다음 달에 숲길을 걸으러 갔어.」","mis":"K5-1-u2-X21"},{"t":"「지금 숲길을 걸으러 간다.」","mis":"K5-1-u2-X05"}],"explanation":["말끝이 그대로예요.","때의 말이 그대로예요.","때의 말과 말끝을 함께 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#5','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',3,'error','auto','기행문에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X04','K5-1-u2-X30','K5-1-u2-X33']::text[],false,'{"seq":5,"concept":"K5-1-u2-C4","difficulty":3,"kind":"error","stem":"기행문에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여행에 쓴 돈만 꼼꼼히 적어도 기행문이야.」","correct":true,"mis_target":"K5-1-u2-X04"},{"t":"「무엇을 보았는지가 담겨야 해.」","mis":"K5-1-u2-X30"},{"t":"「무엇을 느꼈는지도 함께 담겨야 해.」","mis":"K5-1-u2-X33"}],"explanation":["본 것은 꼭 담겨요.","느낀 것도 담겨요.","돈의 목록은 기행문이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#6','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C5',3,'mc','auto','체험을 떠올려 말하기를 가장 잘한 친구는 누구인가요?',ARRAY['K5-1-u2-X03','K5-1-u2-X02']::text[],false,'{"seq":6,"concept":"K5-1-u2-C5","difficulty":3,"kind":"mc","stem":"체험을 떠올려 말하기를 가장 잘한 친구는 누구인가요?","options":[{"t":"「지난 토요일에 시장에 갔어. 생선 가게 아저씨의 목소리가 커서 깜짝 놀랐고 신이 났어.」","correct":true},{"t":"「시장에 갔어.」","mis":"K5-1-u2-X03"},{"t":"「시장이 좋아.」","mis":"K5-1-u2-X03"},{"t":"「다음에 시장에 갈 거야. 생선이 많대.」","mis":"K5-1-u2-X02"}],"explanation":["언제 · 본 것 · 느낀 것이 빠졌어요.","겪은 일이 드러나지 않아요.","때 · 본 것 · 느낀 것이 모두 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#7','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',3,'sa','auto','여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":3,"kind":"sa","stem":"여행하며 보고, 듣고, 느끼고, 생각한 것을 쓴 글을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["기행문"],"explanation":["여행 글이에요.","일정표와 달라요.","「기행문」이에요."],"mis":"K5-1-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#8','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C3',4,'essay','teacher','해든이가 산책로에 다녀온 날 무엇을 기록해 두었으면 좋았을지 두 가지 쓰고, 그 기록이 윤슬이에게 어떻게 도움이 되었을지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C3","difficulty":4,"kind":"essay","stem":"해든이가 산책로에 다녀온 날 무엇을 기록해 두었으면 좋았을지 두 가지 쓰고, 그 기록이 윤슬이에게 어떻게 도움이 되었을지 쓰세요.","answer_guide":{"answer":"예: 언제 갔는지와 산책로에서 본 것(강물 위를 나는 새, 길가의 꽃), 그때 느낀 마음(바람이 시원해 기분이 좋았다)을 적어 두었으면 좋았다. 그랬다면 산책로에 가 보려는 윤슬이에게 무엇을 볼 수 있는지 알려 주어 윤슬이가 더 즐겁게 다녀올 수 있었을 것이다.","scoring_points":["기록할 내용을 두 가지 썼는가","본 것과 느낀 것이 들어 있는가","기록이 다른 사람에게 주는 도움을 썼는가"]},"explanation":["해든이는 기억이 안 난다고 했어요.","본 것 · 느낀 것을 떠올려요.","나눌 수 있다는 점과 이어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"해든아, 나도 그 산책로 가 보려고. 거기서 뭘 봤어?"},{"who":"해든","text":"음……. 기억이 잘 안 나. 적어 둘 걸 그랬어."},{"who":"윤슬","text":"아, 나도 궁금했는데 아쉽다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#9','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C1',4,'essay','teacher','해든이와 나린이의 말에서 시간 표현을 모두 찾아 쓰고, 어떤 표현이 지난 일과 앞으로의 일을 알려 주는지 나누어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C1","difficulty":4,"kind":"essay","stem":"해든이와 나린이의 말에서 시간 표현을 모두 찾아 쓰고, 어떤 표현이 지난 일과 앞으로의 일을 알려 주는지 나누어 쓰세요.","answer_guide":{"answer":"예: 해든이의 말 — 「지난 봄에」와 「다녀왔어」가 지난 일을 알려 준다. 나린이의 말 — 「다음 달에」와 「갈 거야」가 앞으로의 일을 알려 준다. 「산책로」 · 「숲길」은 곳을 가리키는 말이라 시간 표현이 아니다.","scoring_points":["네 가지 시간 표현을 찾았는가","지난 일과 앞으로의 일로 나누었는가","때의 낱말과 말끝을 함께 찾았는가"]},"explanation":["언제인지 알려 주는 말을 찾아요.","말끝도 살펴요.","두 때로 나누어요."],"asset":{"type":"speech","turns":[{"who":"윤슬","text":"너희 요즘 걷기 좋은 곳 다녀왔거나 갈 계획 있어?"},{"who":"해든","text":"나는 지난 봄에 강가 산책로에 다녀왔어."},{"who":"나린","text":"나는 다음 달에 숲길을 걸으러 갈 거야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L01_challenge#10','kor',5,1,'u2','L01','g5_1_kor_u2_L01_challenge','lesson_challenge','K5-1-u2-C4',4,'essay','teacher','「동문 → 골목 → 대장간 → 남문」처럼 다닌 곳만 적힌 글을 기행문으로 바꾸려면 무엇을 더 써야 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C4","difficulty":4,"kind":"essay","stem":"「동문 → 골목 → 대장간 → 남문」처럼 다닌 곳만 적힌 글을 기행문으로 바꾸려면 무엇을 더 써야 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 다닌 곳마다 무엇을 보고 들었는지와 그때 무엇을 느끼고 생각했는지를 더 써야 한다. 다닌 곳만 있으면 일정표일 뿐이고, 보고 듣고 느낀 것이 함께 담겨야 비로소 기행문이 되기 때문이다.","scoring_points":["보고 들은 것을 더해야 한다고 썼는가","느끼고 생각한 것을 더해야 한다고 썼는가","일정표와 기행문의 차이로 까닭을 썼는가"]},"explanation":["지금은 일정표예요.","무엇이 빠졌는지 떠올려요.","본 것 · 느낀 것을 더해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#1','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C6',1,'mc','auto','「학교 앞 은행나무의 한 해」에서 이미 지나간 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":1,"concept":"K5-1-u2-C6","difficulty":1,"kind":"mc","stem":"「학교 앞 은행나무의 한 해」에서 이미 지나간 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"「이 나무는 아주 작은 연둣빛 잎을 내밀었다.」","correct":true},{"t":"「잎이 우수수 떨어진다.」","mis":"K5-1-u2-X05"},{"t":"「다시 작은 잎을 내밀 것이다.」","mis":"K5-1-u2-X05"},{"t":"「가지만 앙상하게 남을 것이다.」","mis":"K5-1-u2-X05"}],"explanation":["지금 일어나는 일이에요.","앞으로 일어날 일이에요.","-었-이 들어 있어 지난 일이에요."],"asset":{"type":"passage","lines":["학교 정문 옆에는 커다란 은행나무가 서 있다.","지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.","여름 내내 잎은 넓고 진해졌고, 한낮에는 넉넉한 그늘을 만들어 주었다.","지금은 시월이다. 나무는 온통 노랗게 물들어 있다.","바람이 불 때마다 잎이 우수수 떨어진다.","다음 달이면 가지만 앙상하게 남을 것이다.","그리고 내년 봄에는 다시 작은 잎을 내밀 것이다."],"title":"「학교 앞 은행나무의 한 해」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#2','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C7',1,'mc','auto','「바람이 불 때마다 잎이 우수수 떨어진다.」는 언제의 일인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X20']::text[],false,'{"seq":2,"concept":"K5-1-u2-C7","difficulty":1,"kind":"mc","stem":"「바람이 불 때마다 잎이 우수수 떨어진다.」는 언제의 일인가요?","options":[{"t":"지금 일어나고 있는 일","correct":true},{"t":"이미 지나간 일","mis":"K5-1-u2-X05"},{"t":"앞으로 일어날 일","mis":"K5-1-u2-X05"},{"t":"언제인지 알 수 없는 일","mis":"K5-1-u2-X20"}],"explanation":["-었-이 없어요.","-ㄹ 것이 없어요.","-ㄴ-이 지금을 나타내요."],"asset":{"type":"passage","lines":["학교 정문 옆에는 커다란 은행나무가 서 있다.","지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.","여름 내내 잎은 넓고 진해졌고, 한낮에는 넉넉한 그늘을 만들어 주었다.","지금은 시월이다. 나무는 온통 노랗게 물들어 있다.","바람이 불 때마다 잎이 우수수 떨어진다.","다음 달이면 가지만 앙상하게 남을 것이다.","그리고 내년 봄에는 다시 작은 잎을 내밀 것이다."],"title":"「학교 앞 은행나무의 한 해」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#3','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C8',1,'mc','auto','앞으로 일어날 일을 나타낼 때 쓰는 말끝은 어느 것인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X06']::text[],false,'{"seq":3,"concept":"K5-1-u2-C8","difficulty":1,"kind":"mc","stem":"앞으로 일어날 일을 나타낼 때 쓰는 말끝은 어느 것인가요?","options":[{"t":"-(으)ㄹ 것 · -겠-","correct":true},{"t":"-았- · -었-","mis":"K5-1-u2-X05"},{"t":"-는- · -ㄴ-","mis":"K5-1-u2-X05"},{"t":"-다 · -요","mis":"K5-1-u2-X06"}],"explanation":["지난 일의 말끝이에요.","지금의 말끝이에요.","앞으로의 일은 -(으)ㄹ 것 · -겠-이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#4','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C11',1,'mc','auto','「조금 지난 뒤에」를 뜻하는 말은 어느 것인가요?',ARRAY['K5-1-u2-X09']::text[],false,'{"seq":4,"concept":"K5-1-u2-C11","difficulty":1,"kind":"mc","stem":"「조금 지난 뒤에」를 뜻하는 말은 어느 것인가요?","options":[{"t":"이따가","correct":true},{"t":"아까","mis":"K5-1-u2-X09"},{"t":"어제","mis":"K5-1-u2-X09"},{"t":"지금","mis":"K5-1-u2-X09"}],"explanation":["「아까」는 조금 전이에요.","「어제」는 지난 날이에요.","「이따가」는 조금 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#5','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C6',2,'match','auto','문장과 나타내는 때를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u2-C6","difficulty":2,"kind":"match","stem":"문장과 나타내는 때를 이으세요.","pairs":[{"l":"동생은 어제 자전거를 탔다.","r":"과거"},{"l":"동생은 지금 자전거를 탄다.","r":"현재"},{"l":"동생은 내일 자전거를 탈 것이다.","r":"미래"}],"mis":"K5-1-u2-X05","explanation":["-았-이 있어요.","-ㄴ-이 있어요.","말끝만 보면 때를 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#6','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C9',2,'mc','auto','「배웠다」에서 과거를 나타내는 부분은 어느 것인가요?',ARRAY['K5-1-u2-X06']::text[],false,'{"seq":6,"concept":"K5-1-u2-C9","difficulty":2,"kind":"mc","stem":"「배웠다」에서 과거를 나타내는 부분은 어느 것인가요?","options":[{"t":"-었-","correct":true},{"t":"배우-","mis":"K5-1-u2-X06"},{"t":"-다","mis":"K5-1-u2-X06"},{"t":"배웠-","mis":"K5-1-u2-X06"}],"explanation":["낱말의 뿌리예요.","문장을 끝맺는 부분이에요.","「배우-」에 「-었-」이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#7','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C12',2,'blank','auto','빈칸에 가장 알맞은 말을 고르세요. 「우리는 (　　) 도서관에 가겠다.」',ARRAY['K5-1-u2-X10']::text[],false,'{"seq":7,"concept":"K5-1-u2-C12","difficulty":2,"kind":"blank","stem":"빈칸에 가장 알맞은 말을 고르세요. 「우리는 (　　) 도서관에 가겠다.」","options":[{"t":"이따가","correct":true},{"t":"아까","mis":"K5-1-u2-X10"},{"t":"그저께","mis":"K5-1-u2-X10"},{"t":"어제","mis":"K5-1-u2-X10"}],"explanation":["조금 전은 「가겠다」와 어색해요.","지난 날도 어색해요.","「-겠-」은 앞일이라 「이따가」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#8','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C12',2,'ox','auto','「나는 아까 우유를 마실 것이다.」는 자연스러운 문장이에요.',ARRAY['K5-1-u2-X09']::text[],false,'{"seq":8,"concept":"K5-1-u2-C12","difficulty":2,"kind":"ox","stem":"「나는 아까 우유를 마실 것이다.」는 자연스러운 문장이에요.","answer":"X","reason_options":[{"t":"「아까」는 조금 전인데 말끝은 앞일을 나타내어 어색하기 때문에","correct":true},{"t":"「아까」는 앞으로의 때를 가리키는 말이기 때문에","mis":"K5-1-u2-X09"}],"mis":"K5-1-u2-X09","explanation":["「아까」는 조금 전이에요.","말끝은 앞일이에요.","소리 내어 읽으면 어색해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#9','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C11',2,'mc','auto','앞으로의 때를 가리키는 말로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X09']::text[],false,'{"seq":9,"concept":"K5-1-u2-C11","difficulty":2,"kind":"mc","stem":"앞으로의 때를 가리키는 말로만 묶은 것은 어느 것인가요?","options":[{"t":"이따가 · 곧 · 내일","correct":true},{"t":"아까 · 곧 · 내일","mis":"K5-1-u2-X09"},{"t":"이따가 · 어제 · 내일","mis":"K5-1-u2-X09"},{"t":"아까 · 어제 · 그저께","mis":"K5-1-u2-X09"}],"explanation":["「아까」는 조금 전이에요.","「어제」는 지난 날이에요.","모두 말한 때보다 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_basic#10','kor',5,1,'u2','L02','g5_1_kor_u2_L02_basic','lesson_basic','K5-1-u2-C10',3,'mc','auto','「염소는 풀을 먹는다.」의 「먹는다」가 나타내는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X07','K5-1-u2-X05']::text[],false,'{"seq":10,"concept":"K5-1-u2-C10","difficulty":3,"kind":"mc","stem":"「염소는 풀을 먹는다.」의 「먹는다」가 나타내는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바로 지금만이 아니라 늘 되풀이되는 일","correct":true},{"t":"바로 이 순간에만 일어나는 일","mis":"K5-1-u2-X07"},{"t":"이미 끝난 일","mis":"K5-1-u2-X05"},{"t":"앞으로 한 번만 일어날 일","mis":"K5-1-u2-X05"}],"explanation":["-는-이 늘 지금만은 아니에요.","-었-이 없어요.","염소는 늘 풀을 먹어요 — 되풀이되는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#1','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C14',2,'mc','auto','「올해」가 들어간 다음 문장 가운데 지난 일을 나타낸 것은 어느 것인가요?',ARRAY['K5-1-u2-X12']::text[],false,'{"seq":1,"concept":"K5-1-u2-C14","difficulty":2,"kind":"mc","stem":"「올해」가 들어간 다음 문장 가운데 지난 일을 나타낸 것은 어느 것인가요?","options":[{"t":"「올해 봄에 심었다.」","correct":true},{"t":"「올해는 잘 자란다.」","mis":"K5-1-u2-X12"},{"t":"「올해 안에 거둘 것이다.」","mis":"K5-1-u2-X12"},{"t":"「올해는 날씨가 따뜻하다.」","mis":"K5-1-u2-X12"}],"explanation":["지금을 나타내요.","앞으로를 나타내요.","「올해」는 세 때에 모두 쓰여요. 말끝을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#2','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C13',2,'ox','auto','「지금 숙제 다 했어.」는 지금인데 지난 일처럼 말해서 틀린 문장이니 꼭 고쳐야 해요.',ARRAY['K5-1-u2-X11']::text[],false,'{"seq":2,"concept":"K5-1-u2-C13","difficulty":2,"kind":"ox","stem":"「지금 숙제 다 했어.」는 지금인데 지난 일처럼 말해서 틀린 문장이니 꼭 고쳐야 해요.","answer":"X","reason_options":[{"t":"말끝은 때 말고도 여러 일을 하고, 소리 내어 읽어 어색하지 않으면 고치지 않아도 되기 때문에","correct":true},{"t":"「지금」과 「했어」는 서로 어긋나는 짝이기 때문에","mis":"K5-1-u2-X11"}],"mis":"K5-1-u2-X11","explanation":["겉보기만으로 판단하지 않아요.","소리 내어 읽어 봐요.","어색하지 않으면 틀린 말이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#3','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C13',3,'mc','auto','다음 가운데 고치지 않아도 되는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X10']::text[],false,'{"seq":3,"concept":"K5-1-u2-C13","difficulty":3,"kind":"mc","stem":"다음 가운데 고치지 않아도 되는 문장은 어느 것인가요?","options":[{"t":"「드디어 내일 소풍 간다.」","correct":true},{"t":"「나는 아까 우유를 마실 것이다.」","mis":"K5-1-u2-X10"},{"t":"「그저께 비가 올 것이다.」","mis":"K5-1-u2-X10"},{"t":"「어제 나는 숙제를 하겠다.」","mis":"K5-1-u2-X10"}],"explanation":["「아까」와 앞일의 말끝은 어색해요.","지난 날과 앞일의 말끝은 어색해요.","앞일을 현재처럼 말해도 어색하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#4','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C10',3,'mc','auto','-는- / -ㄴ-이 붙지 않았는데도 지금을 나타내는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X08']::text[],false,'{"seq":4,"concept":"K5-1-u2-C10","difficulty":3,"kind":"mc","stem":"-는- / -ㄴ-이 붙지 않았는데도 지금을 나타내는 문장은 어느 것인가요?","options":[{"t":"「하늘이 참 푸르다.」","correct":true},{"t":"「하늘이 참 푸르렀다.」","mis":"K5-1-u2-X08"},{"t":"「하늘이 참 푸르겠다.」","mis":"K5-1-u2-X08"},{"t":"「하늘이 참 푸를 것이다.」","mis":"K5-1-u2-X08"}],"explanation":["-었-이 있어 지난 일이에요.","-겠-이 있어요.","말끝이 없어도 지금을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#5','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C6',3,'mc','auto','감나무 이야기에서 ㉮와 ㉯가 나타내는 때로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X12','K5-1-u2-X05']::text[],false,'{"seq":5,"concept":"K5-1-u2-C6","difficulty":3,"kind":"mc","stem":"감나무 이야기에서 ㉮와 ㉯가 나타내는 때로 알맞은 것은 어느 것인가요?","options":[{"t":"둘 다 이미 지나간 일이다","correct":true},{"t":"㉮는 지난 일, ㉯는 앞으로의 일이다","mis":"K5-1-u2-X12"},{"t":"둘 다 지금 일어나는 일이다","mis":"K5-1-u2-X05"},{"t":"㉮는 지금, ㉯는 지난 일이다","mis":"K5-1-u2-X05"}],"explanation":["「이듬해」는 여기서 작년이에요.","-았- · -었-이 보여요.","「심었다」 · 「맺혔다」 모두 지난 일이에요."],"asset":{"type":"passage","lines":["㉮ 재작년에 우리 가족은 마당에 감나무를 심었다.","㉯ 이듬해인 작년에 작은 열매가 몇 개 맺혔다.","㉰ 올해는 가지마다 감이 주렁주렁 달린다.","㉱ 내년에는 이웃과 나누어 먹을 것이다."],"title":"감나무 이야기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#6','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C10',3,'error','auto','-는- / -ㄴ-에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X07','K5-1-u2-X11','K5-1-u2-X08']::text[],false,'{"seq":6,"concept":"K5-1-u2-C10","difficulty":3,"kind":"error","stem":"-는- / -ㄴ-에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「-는-이 들어가면 반드시 바로 지금 일어나는 일이야.」","correct":true,"mis_target":"K5-1-u2-X07"},{"t":"「〈나 내일 서울에 간다〉처럼 가까운 앞일에도 써.」","mis":"K5-1-u2-X11"},{"t":"「지난 일을 생생하게 말할 때에도 써.」","mis":"K5-1-u2-X08"}],"explanation":["가까운 앞일에도 써요.","지난 일을 생생하게도 써요.","「반드시 지금」은 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#7','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C14',3,'mc','auto','「이듬해」를 바르게 설명한 것은 어느 것인가요?',ARRAY['K5-1-u2-X12']::text[],false,'{"seq":7,"concept":"K5-1-u2-C14","difficulty":3,"kind":"mc","stem":"「이듬해」를 바르게 설명한 것은 어느 것인가요?","options":[{"t":"어떤 해의 바로 다음 해라서 지난 일과 앞으로의 일에 모두 쓸 수 있다","correct":true},{"t":"지난해만 가리키는 말이다","mis":"K5-1-u2-X12"},{"t":"앞으로 올 해만 가리키는 말이다","mis":"K5-1-u2-X12"},{"t":"지금 지나가고 있는 해를 가리킨다","mis":"K5-1-u2-X12"}],"explanation":["지난 일에만 쓰지 않아요.","앞일에만 쓰지 않아요.","어떤 해의 바로 다음 해예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#8','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C13',4,'essay','teacher','친구가 「드디어 내일 소풍 간다.」를 「내일」과 「간다」가 어긋나니 고쳐야 한다고 했어요. 친구에게 해 줄 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C13","difficulty":4,"kind":"essay","stem":"친구가 「드디어 내일 소풍 간다.」를 「내일」과 「간다」가 어긋나니 고쳐야 한다고 했어요. 친구에게 해 줄 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 이 문장은 고치지 않아도 돼. 말끝은 때를 나타내는 일 말고도 여러 가지 일을 해서, 가까운 앞일을 「간다」처럼 말할 수 있어. 소리 내어 읽어 봐도 어색하지 않으니까 틀린 말이 아니야.","scoring_points":["고치지 않아도 된다고 판단했는가","말끝이 여러 일을 한다는 까닭을 썼는가","소리 내어 읽어 보는 기준을 썼는가"]},"explanation":["겉보기에 어긋나 보여요.","소리 내어 읽어 봐요.","어색하지 않으면 그대로 둬요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#9','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C8',4,'essay','teacher','「학교 앞 은행나무의 한 해」에서 과거 · 현재 · 미래를 나타낸 문장을 하나씩 찾아 쓰고, 각 문장의 말끝에서 때를 알려 주는 부분을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C8","difficulty":4,"kind":"essay","stem":"「학교 앞 은행나무의 한 해」에서 과거 · 현재 · 미래를 나타낸 문장을 하나씩 찾아 쓰고, 각 문장의 말끝에서 때를 알려 주는 부분을 쓰세요.","answer_guide":{"answer":"예: 과거 — 「지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.」의 「-었-」. 현재 — 「바람이 불 때마다 잎이 우수수 떨어진다.」의 「-ㄴ-」. 미래 — 「내년 봄에는 다시 작은 잎을 내밀 것이다.」의 「-ㄹ 것」.","scoring_points":["세 때의 문장을 하나씩 찾았는가","말끝에서 때를 알려 주는 부분을 짚었는가","문장과 때가 맞는가"]},"explanation":["말끝을 봐요.","-었- · -ㄴ- · -ㄹ 것을 찾아요.","하나씩 짝지어 써요."],"asset":{"type":"passage","lines":["학교 정문 옆에는 커다란 은행나무가 서 있다.","지난 사월, 이 나무는 아주 작은 연둣빛 잎을 내밀었다.","여름 내내 잎은 넓고 진해졌고, 한낮에는 넉넉한 그늘을 만들어 주었다.","지금은 시월이다. 나무는 온통 노랗게 물들어 있다.","바람이 불 때마다 잎이 우수수 떨어진다.","다음 달이면 가지만 앙상하게 남을 것이다.","그리고 내년 봄에는 다시 작은 잎을 내밀 것이다."],"title":"「학교 앞 은행나무의 한 해」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L02_challenge#10','kor',5,1,'u2','L02','g5_1_kor_u2_L02_challenge','lesson_challenge','K5-1-u2-C11',4,'essay','teacher','「아까 · 지금 · 이따」 가운데 두 낱말을 골라 각각 문장을 만들고, 말끝이 그 낱말과 어울리는지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C11","difficulty":4,"kind":"essay","stem":"「아까 · 지금 · 이따」 가운데 두 낱말을 골라 각각 문장을 만들고, 말끝이 그 낱말과 어울리는지 설명하세요.","answer_guide":{"answer":"예: 「나는 아까 공원에서 친구를 만났다.」 — 「아까」는 조금 전이라 지난 일의 말끝 「-았-」과 어울린다. 「나는 이따 숙제를 할 것이다.」 — 「이따」는 조금 뒤라 앞일의 말끝 「-ㄹ 것」과 어울린다.","scoring_points":["두 낱말로 문장을 만들었는가","말끝이 낱말과 어울리는가","어울리는 까닭을 설명했는가"]},"explanation":["낱말의 때를 먼저 떠올려요.","알맞은 말끝을 골라요.","어울리는지 소리 내어 확인해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#1','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C15',1,'mc','auto','오늘에서 이틀 뒤를 가리키는 말은 어느 것인가요?',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":1,"concept":"K5-1-u2-C15","difficulty":1,"kind":"mc","stem":"오늘에서 이틀 뒤를 가리키는 말은 어느 것인가요?","options":[{"t":"모레","correct":true},{"t":"내일","mis":"K5-1-u2-X13"},{"t":"글피","mis":"K5-1-u2-X13"},{"t":"그저께","mis":"K5-1-u2-X13"}],"explanation":["하루 뒤예요.","사흘 뒤예요.","내일 다음 날이 모레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#2','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C18',1,'mc','auto','사흘은 며칠인가요?',ARRAY['K5-1-u2-X16','K5-1-u2-X14']::text[],false,'{"seq":2,"concept":"K5-1-u2-C18","difficulty":1,"kind":"mc","stem":"사흘은 며칠인가요?","options":[{"t":"삼 일","correct":true},{"t":"사 일","mis":"K5-1-u2-X16"},{"t":"칠 일","mis":"K5-1-u2-X14"},{"t":"이 일","mis":"K5-1-u2-X14"}],"explanation":["「사」 소리에 속지 마세요.","이레가 칠 일이에요.","하루 · 이틀 · 사흘 — 삼 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#3','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C16',1,'mc','auto','날의 개수를 세는 말을 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K5-1-u2-X14']::text[],false,'{"seq":3,"concept":"K5-1-u2-C16","difficulty":1,"kind":"mc","stem":"날의 개수를 세는 말을 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"하루 · 이틀 · 사흘 · 나흘 · 닷새","correct":true},{"t":"하루 · 이틀 · 나흘 · 사흘 · 닷새","mis":"K5-1-u2-X14"},{"t":"하루 · 사흘 · 이틀 · 닷새 · 나흘","mis":"K5-1-u2-X14"},{"t":"이틀 · 하루 · 사흘 · 나흘 · 닷새","mis":"K5-1-u2-X14"}],"explanation":["사흘이 나흘보다 앞이에요.","차례가 뒤섞였어요.","하루부터 차례로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#4','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C15',1,'match','auto','날짜를 가리키는 말과 언제인지를 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K5-1-u2-C15","difficulty":1,"kind":"match","stem":"날짜를 가리키는 말과 언제인지를 이으세요.","pairs":[{"l":"그저께","r":"이틀 전"},{"l":"글피","r":"사흘 뒤"},{"l":"그끄저께","r":"사흘 전"}],"mis":"K5-1-u2-X13","explanation":["오늘을 가운데에 둬요.","앞뒤를 나누어 세요.","그저께 · 그끄저께는 전, 글피는 뒤예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#5','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C15',2,'blank','auto','빈칸에 알맞은 말을 고르세요. 「오늘부터 사흘 뒤인 (　　)에 현장 체험 학습을 간다.」',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":5,"concept":"K5-1-u2-C15","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말을 고르세요. 「오늘부터 사흘 뒤인 (　　)에 현장 체험 학습을 간다.」","options":[{"t":"글피","correct":true},{"t":"모레","mis":"K5-1-u2-X13"},{"t":"그저께","mis":"K5-1-u2-X13"},{"t":"내일","mis":"K5-1-u2-X13"}],"explanation":["모레는 이틀 뒤예요.","그저께는 지난 날이에요.","내일 · 모레 다음이 글피예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#6','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C17',2,'mc','auto','날수를 세는 말이 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u2-X15']::text[],false,'{"seq":6,"concept":"K5-1-u2-C17","difficulty":2,"kind":"mc","stem":"날수를 세는 말이 쓰인 문장은 어느 것인가요?","options":[{"t":"「줄넘기 연습이 하루 미뤄졌다.」","correct":true},{"t":"「모레 학예회가 열린다.」","mis":"K5-1-u2-X15"},{"t":"「그저께 화분에 물을 주었다.」","mis":"K5-1-u2-X15"},{"t":"「내일 줄넘기를 한다.」","mis":"K5-1-u2-X15"}],"explanation":["「모레」는 날짜를 가리켜요.","「그저께」도 날짜를 가리켜요.","「하루」는 며칠 동안인지를 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#7','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C19',2,'ox','auto','「이틀」을 「2틀」로 써도 뜻이 같으니 괜찮아요.',ARRAY['K5-1-u2-X17']::text[],false,'{"seq":7,"concept":"K5-1-u2-C19","difficulty":2,"kind":"ox","stem":"「이틀」을 「2틀」로 써도 뜻이 같으니 괜찮아요.","answer":"X","reason_options":[{"t":"이틀은 숫자에서 온 말이 아니라 본디부터 있던 우리말이기 때문에","correct":true},{"t":"「2틀」이 더 짧고 알아보기 쉽기 때문에","mis":"K5-1-u2-X17"}],"mis":"K5-1-u2-X17","explanation":["「틀」은 따로 떼어 쓰는 말이 아니에요.","숫자를 섞으면 틀린 표기예요.","본디부터 있던 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#8','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C16',2,'mc','auto','날수를 세는 말과 날수를 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u2-X14','K5-1-u2-X16']::text[],false,'{"seq":8,"concept":"K5-1-u2-C16","difficulty":2,"kind":"mc","stem":"날수를 세는 말과 날수를 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"열흘 — 십 일","correct":true},{"t":"나흘 — 오 일","mis":"K5-1-u2-X14"},{"t":"이레 — 육 일","mis":"K5-1-u2-X14"},{"t":"닷새 — 사 일","mis":"K5-1-u2-X16"}],"explanation":["나흘은 사 일이에요.","이레는 칠 일이에요.","열흘은 십 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#9','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C20',2,'mc','auto','「비가 금방 그칠 거야.」의 「금방」이 가리키는 때로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X18']::text[],false,'{"seq":9,"concept":"K5-1-u2-C20","difficulty":2,"kind":"mc","stem":"「비가 금방 그칠 거야.」의 「금방」이 가리키는 때로 알맞은 것은 어느 것인가요?","options":[{"t":"곧","correct":true},{"t":"조금 전","mis":"K5-1-u2-X18"},{"t":"어제","mis":"K5-1-u2-X18"},{"t":"아주 오래전","mis":"K5-1-u2-X18"}],"explanation":["「그쳤다」라면 조금 전이에요.","날짜 말이 아니에요.","「그칠 거야」와 함께 쓰여 곧이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_basic#10','kor',5,1,'u2','L03','g5_1_kor_u2_L03_basic','lesson_basic','K5-1-u2-C21',3,'mc','auto','날짜 말과 날수 말을 구별해 계획을 가장 또렷하게 말한 것은 어느 것인가요?',ARRAY['K5-1-u2-X15','K5-1-u2-X19']::text[],false,'{"seq":10,"concept":"K5-1-u2-C21","difficulty":3,"kind":"mc","stem":"날짜 말과 날수 말을 구별해 계획을 가장 또렷하게 말한 것은 어느 것인가요?","options":[{"t":"「모레부터 나흘 동안 매일 스무 쪽씩 책을 읽을 것이다.」","correct":true},{"t":"「모레 동안 책을 읽을 것이다.」","mis":"K5-1-u2-X15"},{"t":"「나흘에 책을 읽을 것이다.」","mis":"K5-1-u2-X15"},{"t":"「언젠가 책을 많이 읽을 것이다.」","mis":"K5-1-u2-X19"}],"explanation":["「모레」는 며칠 동안이 아니에요.","「나흘」은 어느 날이 아니에요.","시작하는 날과 며칠 동안을 함께 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#1','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C17',2,'mc','auto','날짜 말과 날수 말을 섞어 써서 뜻이 어긋난 문장은 어느 것인가요?',ARRAY['K5-1-u2-X13','K5-1-u2-X15','K5-1-u2-X19']::text[],false,'{"seq":1,"concept":"K5-1-u2-C17","difficulty":2,"kind":"mc","stem":"날짜 말과 날수 말을 섞어 써서 뜻이 어긋난 문장은 어느 것인가요?","options":[{"t":"「이틀에 할머니 댁에 간다.」","correct":true},{"t":"「모레 할머니 댁에 간다.」","mis":"K5-1-u2-X13"},{"t":"「이틀 동안 할머니 댁에 머문다.」","mis":"K5-1-u2-X15"},{"t":"「내일부터 사흘 동안 할머니 댁에 있는다.」","mis":"K5-1-u2-X19"}],"explanation":["「모레」는 날짜를 바르게 가리켜요.","「이틀 동안」은 바르게 썼어요.","「이틀」은 어느 날이 아니라 며칠 동안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#2','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C18',2,'sa','auto','사 일을 세는 우리말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"K5-1-u2-C18","difficulty":2,"kind":"sa","stem":"사 일을 세는 우리말을 두 글자로 쓰세요.","answer":["나흘"],"explanation":["사흘은 삼 일이에요.","사흘 다음이에요.","사 일은 「나흘」이에요."],"mis":"K5-1-u2-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#3','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C15',3,'mc','auto','오늘이 수요일이라면 그저께는 무슨 요일인가요?',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":3,"kind":"mc","stem":"오늘이 수요일이라면 그저께는 무슨 요일인가요?","options":[{"t":"월요일","correct":true},{"t":"화요일","mis":"K5-1-u2-X13"},{"t":"일요일","mis":"K5-1-u2-X13"},{"t":"금요일","mis":"K5-1-u2-X13"}],"explanation":["화요일은 어제예요.","일요일은 그끄저께예요.","그저께는 이틀 전 — 월요일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#4','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C17',3,'mc','auto','날짜와 날수 문장 ㉮~㉰에서 날수를 세는 말로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X15']::text[],false,'{"seq":4,"concept":"K5-1-u2-C17","difficulty":3,"kind":"mc","stem":"날짜와 날수 문장 ㉮~㉰에서 날수를 세는 말로만 묶은 것은 어느 것인가요?","options":[{"t":"이틀 · 하루 · 하루","correct":true},{"t":"모레 · 그저께 · 내일","mis":"K5-1-u2-X15"},{"t":"이틀 · 모레 · 어제","mis":"K5-1-u2-X15"},{"t":"하루 · 그저께 · 오늘","mis":"K5-1-u2-X15"}],"explanation":["모두 어느 날을 가리켜요.","날짜 말이 섞였어요.","며칠 동안을 세는 말만 골랐어요."],"asset":{"type":"passage","lines":["㉮ 오늘 받은 안내장을 보니 이틀 뒤인 모레 학예회가 열린다고 한다.","㉯ 그저께 화분에 물을 주었는데, 하루 만인 어제 벌써 싹이 올라왔다.","㉰ 오늘 하려던 줄넘기 연습이 하루 미뤄져 내일 하게 되었다."],"title":"날짜와 날수가 함께 쓰인 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#5','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C18',3,'ox','auto','「사흘 동안 비가 왔다」는 「사」 소리가 들어가니 사 일 동안 비가 왔다는 뜻이에요.',ARRAY['K5-1-u2-X16']::text[],false,'{"seq":5,"concept":"K5-1-u2-C18","difficulty":3,"kind":"ox","stem":"「사흘 동안 비가 왔다」는 「사」 소리가 들어가니 사 일 동안 비가 왔다는 뜻이에요.","answer":"X","reason_options":[{"t":"사흘은 삼 일이고, 사 일은 나흘이기 때문에","correct":true},{"t":"사흘과 나흘은 같은 날수이기 때문에","mis":"K5-1-u2-X16"}],"mis":"K5-1-u2-X16","explanation":["「사」 소리에 속지 마세요.","사흘과 나흘은 달라요.","사흘은 삼 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#6','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C20',3,'mc','auto','「금세」가 「아주 빠르게」라는 뜻으로 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u2-X18']::text[],false,'{"seq":6,"concept":"K5-1-u2-C20","difficulty":3,"kind":"mc","stem":"「금세」가 「아주 빠르게」라는 뜻으로 쓰인 문장은 어느 것인가요?","options":[{"t":"「소문이 금세 퍼졌다.」","correct":true},{"t":"「비가 금방 그쳤다.」","mis":"K5-1-u2-X18"},{"t":"「비가 금방 그칠 거야.」","mis":"K5-1-u2-X18"},{"t":"「나는 금방 왔어.」","mis":"K5-1-u2-X18"}],"explanation":["조금 전을 가리켜요.","곧을 가리켜요.","퍼지는 빠르기를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#7','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C19',3,'error','auto','날수를 세는 말에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X17','K5-1-u2-X14']::text[],false,'{"seq":7,"concept":"K5-1-u2-C19","difficulty":3,"kind":"error","stem":"날수를 세는 말에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「이틀은 숫자 이에서 온 말이라 〈2틀〉로 써도 돼.」","correct":true,"mis_target":"K5-1-u2-X17"},{"t":"「이레는 칠 일이야.」","mis":"K5-1-u2-X14"},{"t":"「열흘은 십 일이야.」","mis":"K5-1-u2-X14"}],"explanation":["이레는 칠 일이 맞아요.","열흘은 십 일이 맞아요.","이틀은 본디부터 있던 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#8','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C21',4,'essay','teacher','「내일부터 사흘 동안」처럼 날짜 말과 날수 말을 함께 넣어 이번 주 나의 계획을 한 문장으로 쓰고, 어느 말이 날짜이고 어느 말이 날수인지 밝히세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C21","difficulty":4,"kind":"essay","stem":"「내일부터 사흘 동안」처럼 날짜 말과 날수 말을 함께 넣어 이번 주 나의 계획을 한 문장으로 쓰고, 어느 말이 날짜이고 어느 말이 날수인지 밝히세요.","answer_guide":{"answer":"예: 「모레부터 닷새 동안 저녁마다 줄넘기를 백 번씩 할 것이다.」 — 「모레」는 시작하는 날을 가리키는 날짜 말이고, 「닷새」는 며칠 동안인지를 세는 날수 말이다.","scoring_points":["날짜 말과 날수 말을 함께 넣었는가","앞으로의 일에 맞는 말끝을 썼는가","두 말을 구별해 밝혔는가"]},"explanation":["시작하는 날을 정해요.","며칠 동안인지 정해요.","둘을 구별해 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#9','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C18',4,'essay','teacher','동생이 「사흘이면 사 일이지?」라고 물었어요. 동생에게 바르게 알려 주는 말을 쓰고, 하루부터 닷새까지 날수를 세는 말을 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C18","difficulty":4,"kind":"essay","stem":"동생이 「사흘이면 사 일이지?」라고 물었어요. 동생에게 바르게 알려 주는 말을 쓰고, 하루부터 닷새까지 날수를 세는 말을 차례대로 쓰세요.","answer_guide":{"answer":"예: 아니야, 사흘은 삼 일이야. 「사」라는 소리 때문에 헷갈리기 쉬운데, 사 일은 나흘이라고 해. 하루 · 이틀 · 사흘 · 나흘 · 닷새 차례로 세면 알 수 있어.","scoring_points":["사흘이 삼 일임을 알려 주었는가","헷갈리는 까닭을 짚었는가","하루부터 닷새까지 차례대로 썼는가"]},"explanation":["「사」 소리에 속지 마세요.","하루부터 차례로 세어요.","사 일은 나흘이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L03_challenge#10','kor',5,1,'u2','L03','g5_1_kor_u2_L03_challenge','lesson_challenge','K5-1-u2-C17',4,'essay','teacher','「날짜를 가리키는 말」과 「날수를 세는 말」이 어떻게 다른지 쓰고, 둘을 섞어 쓴 잘못된 문장을 하나 들어 바르게 고치세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C17","difficulty":4,"kind":"essay","stem":"「날짜를 가리키는 말」과 「날수를 세는 말」이 어떻게 다른지 쓰고, 둘을 섞어 쓴 잘못된 문장을 하나 들어 바르게 고치세요.","answer_guide":{"answer":"예: 날짜를 가리키는 말은 그저께 · 모레처럼 어느 날인지를 나타내고, 날수를 세는 말은 이틀 · 사흘처럼 며칠 동안인지를 나타낸다. 「모레 동안 캠프에 간다」는 섞어 쓴 문장이라 「모레부터 이틀 동안 캠프에 간다」로 고친다.","scoring_points":["두 말의 차이를 바르게 썼는가","섞어 쓴 문장을 예로 들었는가","바르게 고쳤는가"]},"explanation":["어느 날 · 며칠 동안.","섞으면 뜻이 어긋나요.","두 말을 제 몫에 넣어 고쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#1','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C22',1,'mc','auto','「손끝으로 고친 책들」에서 글쓴이가 처음에 애를 먹은 까닭은 무엇인가요?',ARRAY['K5-1-u2-X20']::text[],false,'{"seq":1,"concept":"K5-1-u2-C22","difficulty":1,"kind":"mc","stem":"「손끝으로 고친 책들」에서 글쓴이가 처음에 애를 먹은 까닭은 무엇인가요?","options":[{"t":"테이프가 자꾸 삐뚤어져서","correct":true},{"t":"고칠 책이 하나도 없어서","mis":"K5-1-u2-X20"},{"t":"언니가 도와주지 않아서","mis":"K5-1-u2-X20"},{"t":"도서관 문이 닫혀 있어서","mis":"K5-1-u2-X20"}],"explanation":["책이 상자 가득 쌓여 있었어요.","언니가 방법을 알려 주었어요.","「테이프가 자꾸 삐뚤어져서」라고 했어요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 언니와 함께 마을 도서관으로 갔다.","그날은 낡은 책을 고치는 봉사 활동이 있는 날이었다.","자료실 한쪽에는 표지가 떨어지거나 책장이 찢어진 책이 상자 가득 쌓여 있었다.","나는 찢어진 쪽을 이어 붙이는 일을 맡았다.","처음에는 테이프가 자꾸 삐뚤어져서 애를 먹었다.","언니가 종이를 먼저 맞춘 다음 테이프를 붙이라고 알려 주었다.","그대로 해 보니 훨씬 반듯해졌다."],"title":"「손끝으로 고친 책들」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#2','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C22',1,'mc','auto','「손끝으로 고친 책들」에서 지나간 일을 나타낸 표현은 어느 것인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X20']::text[],false,'{"seq":2,"concept":"K5-1-u2-C22","difficulty":1,"kind":"mc","stem":"「손끝으로 고친 책들」에서 지나간 일을 나타낸 표현은 어느 것인가요?","options":[{"t":"「도서관으로 갔다」","correct":true},{"t":"「조심해서 넘긴다」","mis":"K5-1-u2-X05"},{"t":"「참여할 것이다」","mis":"K5-1-u2-X05"},{"t":"「배워 보고 싶다」","mis":"K5-1-u2-X20"}],"explanation":["지금의 일이에요.","앞으로의 일이에요.","-았-이 들어 있어요."],"asset":{"type":"passage","lines":["지난 토요일, 나는 언니와 함께 마을 도서관으로 갔다.","그날은 낡은 책을 고치는 봉사 활동이 있는 날이었다.","자료실 한쪽에는 표지가 떨어지거나 책장이 찢어진 책이 상자 가득 쌓여 있었다.","나는 찢어진 쪽을 이어 붙이는 일을 맡았다.","처음에는 테이프가 자꾸 삐뚤어져서 애를 먹었다.","언니가 종이를 먼저 맞춘 다음 테이프를 붙이라고 알려 주었다.","그대로 해 보니 훨씬 반듯해졌다."],"title":"「손끝으로 고친 책들」 앞부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#3','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C24',1,'mc','auto','있었던 일을 쓰기 전에 정리하는 네 항목이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u2-X22']::text[],false,'{"seq":3,"concept":"K5-1-u2-C24","difficulty":1,"kind":"mc","stem":"있었던 일을 쓰기 전에 정리하는 네 항목이 아닌 것은 어느 것인가요?","options":[{"t":"함께 간 친구의 전화번호","correct":true},{"t":"누구와 언제 어떤 활동을 했는지","mis":"K5-1-u2-X22"},{"t":"그 활동을 한 까닭","mis":"K5-1-u2-X22"},{"t":"생각하거나 느낀 점","mis":"K5-1-u2-X22"}],"explanation":["네 항목에 들어가요.","네 항목에 들어가요.","전화번호는 글의 내용과 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#4','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C25',1,'mc','auto','있었던 일을 쓴 글의 끝부분에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X23']::text[],false,'{"seq":4,"concept":"K5-1-u2-C25","difficulty":1,"kind":"mc","stem":"있었던 일을 쓴 글의 끝부분에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"전체적인 느낌과 다짐","correct":true},{"t":"그 일을 겪게 된 까닭","mis":"K5-1-u2-X23"},{"t":"시간의 흐름에 따라 있었던 일","mis":"K5-1-u2-X23"},{"t":"보고 들은 것","mis":"K5-1-u2-X23"}],"explanation":["처음에 들어가요.","가운데에 들어가요.","끝에는 전체 느낌과 다짐이 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#5','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C22',2,'mc','auto','「손끝으로 고친 책들」 뒷부분은 어떤 차례로 시간이 흘러가나요?',ARRAY['K5-1-u2-X20']::text[],false,'{"seq":5,"concept":"K5-1-u2-C22","difficulty":2,"kind":"mc","stem":"「손끝으로 고친 책들」 뒷부분은 어떤 차례로 시간이 흘러가나요?","options":[{"t":"예전 → 요즘 → 다음 달","correct":true},{"t":"다음 달 → 요즘 → 예전","mis":"K5-1-u2-X20"},{"t":"요즘 → 예전 → 다음 달","mis":"K5-1-u2-X20"},{"t":"예전 → 다음 달 → 요즘","mis":"K5-1-u2-X20"}],"explanation":["거꾸로예요.","차례가 뒤섞였어요.","「예전에는 · 요즘 · 다음 달에도」를 따라가요."],"asset":{"type":"passage","lines":["두 시간쯤 지나자 상자에 남은 책이 절반으로 줄었다.","내 손을 거친 책이 다시 읽힌다는 것이 뿌듯했다.","예전에는 책이 낡으면 그냥 버리는 줄 알았다.","하지만 직접 해 보니 조금만 손보면 오래 쓸 수 있는 책이 많았다.","요즘 나는 책을 볼 때 모서리를 접지 않고 조심해서 넘긴다.","다음 달에도 봉사 활동에 참여할 것이다.","그때는 표지를 다시 씌우는 일까지 배워 보고 싶다."],"title":"「손끝으로 고친 책들」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#6','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C23',2,'match','auto','바꿀 방향에 맞게 바꾼 문장을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"K5-1-u2-C23","difficulty":2,"kind":"match","stem":"바꿀 방향에 맞게 바꾼 문장을 이으세요.","pairs":[{"l":"나는 아까 책을 읽었다 → 현재로","r":"나는 지금 책을 읽는다"},{"l":"나는 지금 글을 쓴다 → 미래로","r":"나는 이따 글을 쓸 것이다"},{"l":"우리는 내일 그림을 그릴 것이다 → 과거로","r":"우리는 어제 그림을 그렸다"}],"mis":"K5-1-u2-X21","explanation":["바꿀 때를 먼저 봐요.","때의 말도 함께 바꿔요.","말끝과 때의 말을 함께 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#7','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C24',2,'mc','auto','갯벌 체험 계획에서 빠진 항목은 어느 것인가요?',ARRAY['K5-1-u2-X22']::text[],false,'{"seq":7,"concept":"K5-1-u2-C24","difficulty":2,"kind":"mc","stem":"갯벌 체험 계획에서 빠진 항목은 어느 것인가요?","options":[{"t":"생각하거나 느낀 점","correct":true},{"t":"누구와 언제 했는지","mis":"K5-1-u2-X22"},{"t":"그 활동을 한 까닭","mis":"K5-1-u2-X22"},{"t":"보고 들은 것","mis":"K5-1-u2-X22"}],"explanation":["「지난 일요일에 가족과」가 있어요.","「보고 싶었다」가 까닭이에요.","그때 느낀 마음이 비어 있어요."],"asset":{"type":"passage","lines":["· 지난 일요일에 가족과 함께 갯벌 체험을 했다.","· 학교에서 배운 갯벌 생물을 직접 보고 싶었다.","· 조개와 게를 보았고, 갯벌이 물을 걸러 준다는 설명을 들었다."],"title":"갯벌 체험 글을 쓰려고 정리한 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#8','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C25',2,'ox','auto','있었던 일을 쓴 글의 가운데 부분은 시간의 흐름에 따라 쓰는 것이 좋아요.',ARRAY['K5-1-u2-X24']::text[],false,'{"seq":8,"concept":"K5-1-u2-C25","difficulty":2,"kind":"ox","stem":"있었던 일을 쓴 글의 가운데 부분은 시간의 흐름에 따라 쓰는 것이 좋아요.","answer":"O","reason_options":[{"t":"읽는 사람이 일이 일어난 차례를 따라가기 쉽기 때문에","correct":true},{"t":"가운데 부분은 생각나는 차례대로 쓰기 때문에","mis":"K5-1-u2-X24"}],"mis":"K5-1-u2-X24","explanation":["맞는 말이에요.","생각나는 대로 쓰면 헷갈려요.","시간의 흐름이 읽기를 도와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#9','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C26',2,'mc','auto','도서관 책 수리 봉사를 쓴 글의 제목으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X25']::text[],false,'{"seq":9,"concept":"K5-1-u2-C26","difficulty":2,"kind":"mc","stem":"도서관 책 수리 봉사를 쓴 글의 제목으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「손끝으로 고친 책들」","correct":true},{"t":"「토요일」","mis":"K5-1-u2-X25"},{"t":"「나의 하루」","mis":"K5-1-u2-X25"},{"t":"「도서관」","mis":"K5-1-u2-X25"}],"explanation":["무슨 일인지 드러나지 않아요.","너무 막연해요.","있었던 일이 잘 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_basic#10','kor',5,1,'u2','L04','g5_1_kor_u2_L04_basic','lesson_basic','K5-1-u2-C27',3,'mc','auto','쓴 글을 스스로 확인할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u2-X26']::text[],false,'{"seq":10,"concept":"K5-1-u2-C27","difficulty":3,"kind":"mc","stem":"쓴 글을 스스로 확인할 때 살필 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"글씨를 얼마나 예쁘게 썼는가","correct":true},{"t":"있었던 일이 드러나는 제목을 썼는가","mis":"K5-1-u2-X26"},{"t":"시간 표현을 올바르게 활용했는가","mis":"K5-1-u2-X26"},{"t":"생각하거나 느낀 점이 드러나는가","mis":"K5-1-u2-X26"}],"explanation":["제목도 확인해요.","시간 표현도 확인해요.","고쳐 쓰기의 기준은 글의 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#1','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C23',2,'mc','auto','「나는 아까 책을 읽었다.」를 지금의 일로 바꾼 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X21','K5-1-u2-X05']::text[],false,'{"seq":1,"concept":"K5-1-u2-C23","difficulty":2,"kind":"mc","stem":"「나는 아까 책을 읽었다.」를 지금의 일로 바꾼 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"「나는 지금 책을 읽는다.」","correct":true},{"t":"「나는 아까 책을 읽는다.」","mis":"K5-1-u2-X21"},{"t":"「나는 지금 책을 읽었다.」","mis":"K5-1-u2-X05"},{"t":"「나는 이따 책을 읽을 것이다.」","mis":"K5-1-u2-X05"}],"explanation":["「아까」가 그대로예요.","말끝이 그대로예요.","때의 말과 말끝을 함께 바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#2','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C28',2,'ox','auto','친구가 쓴 글을 듣고 「글이 길어서 좋았어.」라고만 말해 주면 충분해요.',ARRAY['K5-1-u2-X27']::text[],false,'{"seq":2,"concept":"K5-1-u2-C28","difficulty":2,"kind":"ox","stem":"친구가 쓴 글을 듣고 「글이 길어서 좋았어.」라고만 말해 주면 충분해요.","answer":"X","reason_options":[{"t":"시간의 흐름을 따라올 수 있었는지, 느낀 점이 드러났는지를 살펴 말해 주어야 하기 때문에","correct":true},{"t":"글은 길수록 잘 쓴 글이기 때문에","mis":"K5-1-u2-X27"}],"mis":"K5-1-u2-X27","explanation":["길이는 기준이 아니에요.","흐름과 느낌을 살펴요.","무엇이 좋았는지 짚어 말해 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#3','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C22',3,'mc','auto','「손끝으로 고친 책들」 뒷부분의 문장 가운데 현재를 나타낸 것은 어느 것인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X20']::text[],false,'{"seq":3,"concept":"K5-1-u2-C22","difficulty":3,"kind":"mc","stem":"「손끝으로 고친 책들」 뒷부분의 문장 가운데 현재를 나타낸 것은 어느 것인가요?","options":[{"t":"「요즘 나는 책을 볼 때 모서리를 접지 않고 조심해서 넘긴다.」","correct":true},{"t":"「예전에는 책이 낡으면 그냥 버리는 줄 알았다.」","mis":"K5-1-u2-X05"},{"t":"「다음 달에도 봉사 활동에 참여할 것이다.」","mis":"K5-1-u2-X05"},{"t":"「상자에 남은 책이 절반으로 줄었다.」","mis":"K5-1-u2-X20"}],"explanation":["지난 일이에요.","앞으로의 일이에요.","「요즘」과 「넘긴다」가 지금을 알려 줘요."],"asset":{"type":"passage","lines":["두 시간쯤 지나자 상자에 남은 책이 절반으로 줄었다.","내 손을 거친 책이 다시 읽힌다는 것이 뿌듯했다.","예전에는 책이 낡으면 그냥 버리는 줄 알았다.","하지만 직접 해 보니 조금만 손보면 오래 쓸 수 있는 책이 많았다.","요즘 나는 책을 볼 때 모서리를 접지 않고 조심해서 넘긴다.","다음 달에도 봉사 활동에 참여할 것이다.","그때는 표지를 다시 씌우는 일까지 배워 보고 싶다."],"title":"「손끝으로 고친 책들」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#4','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C25',3,'mc','auto','처음 · 가운데 · 끝에 들어갈 내용을 바르게 짝지은 것은 어느 것인가요?',ARRAY['K5-1-u2-X23','K5-1-u2-X24']::text[],false,'{"seq":4,"concept":"K5-1-u2-C25","difficulty":3,"kind":"mc","stem":"처음 · 가운데 · 끝에 들어갈 내용을 바르게 짝지은 것은 어느 것인가요?","options":[{"t":"처음 — 봉사 활동을 하게 된 까닭 · 가운데 — 책을 고치며 있었던 일 · 끝 — 다음 달의 다짐","correct":true},{"t":"처음 — 다음 달의 다짐 · 가운데 — 책을 고치며 있었던 일 · 끝 — 봉사 활동을 하게 된 까닭","mis":"K5-1-u2-X23"},{"t":"처음 — 책을 고치며 있었던 일 · 가운데 — 다음 달의 다짐 · 끝 — 봉사 활동을 하게 된 까닭","mis":"K5-1-u2-X23"},{"t":"처음 — 봉사 활동을 하게 된 까닭 · 가운데 — 다음 달의 다짐 · 끝 — 책을 고치며 있었던 일","mis":"K5-1-u2-X24"}],"explanation":["다짐은 끝에 와요.","까닭은 처음에 와요.","상황 → 있었던 일 → 다짐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#5','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C27',3,'error','auto','고쳐 쓰기에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X26','K5-1-u2-X23','K5-1-u2-X21']::text[],false,'{"seq":5,"concept":"K5-1-u2-C27","difficulty":3,"kind":"error","stem":"고쳐 쓰기에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「고쳐 쓰기는 맞춤법만 살피면 끝이야.」","correct":true,"mis_target":"K5-1-u2-X26"},{"t":"「처음 · 가운데 · 끝의 내용이 알맞은지도 살펴.」","mis":"K5-1-u2-X23"},{"t":"「시간 표현을 올바르게 썼는지도 봐.」","mis":"K5-1-u2-X21"}],"explanation":["짜임도 살펴요.","시간 표현도 살펴요.","고쳐 쓰기의 기준은 여럿이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#6','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C24',3,'mc','auto','「학교에서 배운 갯벌 생물을 직접 보고 싶었다.」는 계획의 네 항목 가운데 무엇에 해당하나요?',ARRAY['K5-1-u2-X22']::text[],false,'{"seq":6,"concept":"K5-1-u2-C24","difficulty":3,"kind":"mc","stem":"「학교에서 배운 갯벌 생물을 직접 보고 싶었다.」는 계획의 네 항목 가운데 무엇에 해당하나요?","options":[{"t":"그 활동을 한 까닭","correct":true},{"t":"누구와 언제 어떤 활동을 했는지","mis":"K5-1-u2-X22"},{"t":"보고 들은 것이나 새롭게 안 것","mis":"K5-1-u2-X22"},{"t":"생각하거나 느낀 점","mis":"K5-1-u2-X22"}],"explanation":["누구 · 언제가 드러나지 않아요.","본 것이 아니에요.","왜 갔는지를 밝혔어요."],"asset":{"type":"passage","lines":["· 지난 일요일에 가족과 함께 갯벌 체험을 했다.","· 학교에서 배운 갯벌 생물을 직접 보고 싶었다.","· 조개와 게를 보았고, 갯벌이 물을 걸러 준다는 설명을 들었다."],"title":"갯벌 체험 글을 쓰려고 정리한 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#7','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C26',3,'mc','auto','갯벌 체험 글의 제목으로 있었던 일이 가장 잘 드러나는 것은 어느 것인가요?',ARRAY['K5-1-u2-X25']::text[],false,'{"seq":7,"concept":"K5-1-u2-C26","difficulty":3,"kind":"mc","stem":"갯벌 체험 글의 제목으로 있었던 일이 가장 잘 드러나는 것은 어느 것인가요?","options":[{"t":"「갯벌에서 만난 작은 게」","correct":true},{"t":"「일요일」","mis":"K5-1-u2-X25"},{"t":"「즐거웠다」","mis":"K5-1-u2-X25"},{"t":"「우리 가족」","mis":"K5-1-u2-X25"}],"explanation":["때만 있어요.","느낌만 있어요.","무슨 일이 있었는지 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#8','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C24',4,'essay','teacher','갯벌 체험 계획에서 빠진 항목을 채워 쓰고, 그 항목이 빠지면 글이 어떻게 되는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C24","difficulty":4,"kind":"essay","stem":"갯벌 체험 계획에서 빠진 항목을 채워 쓰고, 그 항목이 빠지면 글이 어떻게 되는지 쓰세요.","answer_guide":{"answer":"예: 생각하거나 느낀 점 — 작은 게가 구멍 속으로 재빨리 숨는 것이 귀여웠고, 갯벌이 물을 깨끗하게 걸러 준다니 소중하게 지켜야겠다고 생각했다. 이 항목이 빠지면 있었던 일만 늘어놓은 글이 되어 글쓴이의 마음이 전해지지 않는다.","scoring_points":["빠진 항목을 알맞게 채웠는가","계획의 내용과 이어지는가","빠졌을 때의 문제를 썼는가"]},"explanation":["네 항목과 맞추어 봐요.","그때 든 마음을 채워요.","빠지면 어떻게 되는지 써요."],"asset":{"type":"passage","lines":["· 지난 일요일에 가족과 함께 갯벌 체험을 했다.","· 학교에서 배운 갯벌 생물을 직접 보고 싶었다.","· 조개와 게를 보았고, 갯벌이 물을 걸러 준다는 설명을 들었다."],"title":"갯벌 체험 글을 쓰려고 정리한 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#9','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C23',4,'essay','teacher','「나는 지금 강아지와 산책한다.」를 지난 일과 앞으로의 일로 각각 바꾸어 쓰고, 무엇을 함께 바꾸었는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C23","difficulty":4,"kind":"essay","stem":"「나는 지금 강아지와 산책한다.」를 지난 일과 앞으로의 일로 각각 바꾸어 쓰고, 무엇을 함께 바꾸었는지 쓰세요.","answer_guide":{"answer":"예: 지난 일 — 「나는 아까 강아지와 산책했다.」 앞으로의 일 — 「나는 이따 강아지와 산책할 것이다.」 말끝(-했- · -ㄹ 것)과 함께 때를 나타내는 말(지금 → 아까 · 이따)도 바꾸었다.","scoring_points":["지난 일로 바르게 바꾸었는가","앞으로의 일로 바르게 바꾸었는가","말끝과 때의 말을 함께 바꾼 점을 썼는가"]},"explanation":["말끝만 바꾸면 어색해요.","때의 말도 바꿔요.","둘을 함께 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L04_challenge#10','kor',5,1,'u2','L04','g5_1_kor_u2_L04_challenge','lesson_challenge','K5-1-u2-C25',4,'essay','teacher','최근에 겪은 일 하나를 골라 처음 · 가운데 · 끝에 들어갈 내용을 한 문장씩 쓰고, 시간 표현을 하나 이상 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C25","difficulty":4,"kind":"essay","stem":"최근에 겪은 일 하나를 골라 처음 · 가운데 · 끝에 들어갈 내용을 한 문장씩 쓰고, 시간 표현을 하나 이상 넣으세요.","answer_guide":{"answer":"예: 처음 — 지난 주말에 동생 생일이라 처음으로 미역국을 끓이게 되었다. 가운데 — 미역을 불리고 볶다가 물을 붓자 냄비 가득 미역이 불어나 깜짝 놀랐다. 끝 — 동생이 맛있다며 한 그릇을 다 비워 뿌듯했고, 다음에는 혼자서도 끓여 볼 것이다.","scoring_points":["처음에 상황이나 까닭을 썼는가","가운데에 있었던 일과 느낌을 썼는가","끝에 전체 느낌과 다짐을 쓰고 시간 표현을 넣었는가"]},"explanation":["겪은 일 하나를 골라요.","세 부분의 몫을 떠올려요.","시간 표현을 넣어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#1','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C29',1,'mc','auto','기행문에서 「여정」은 무엇인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X04']::text[],false,'{"seq":1,"concept":"K5-1-u2-C29","difficulty":1,"kind":"mc","stem":"기행문에서 「여정」은 무엇인가요?","options":[{"t":"여행하며 다닌 곳","correct":true},{"t":"여행하며 보고 들은 것","mis":"K5-1-u2-X28"},{"t":"여행하며 생각하거나 느낀 것","mis":"K5-1-u2-X28"},{"t":"여행에 쓴 돈","mis":"K5-1-u2-X04"}],"explanation":["견문이에요.","감상이에요.","여정은 다닌 곳이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#2','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C31',1,'mc','auto','기행문에서 「감상」은 무엇인가요?',ARRAY['K5-1-u2-X30']::text[],false,'{"seq":2,"concept":"K5-1-u2-C31","difficulty":1,"kind":"mc","stem":"기행문에서 「감상」은 무엇인가요?","options":[{"t":"여행하며 생각하거나 느낀 것","correct":true},{"t":"여행하며 다닌 곳","mis":"K5-1-u2-X30"},{"t":"여행하며 보고 들은 것","mis":"K5-1-u2-X30"},{"t":"여행을 떠난 날짜","mis":"K5-1-u2-X30"}],"explanation":["여정이에요.","견문이에요.","감상은 마음속에서 일어난 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#3','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C29',1,'mc','auto','「돌담을 따라 걸은 하루」에서 글쓴이가 이곳을 찾은 까닭은 무엇인가요?',ARRAY['K5-1-u2-X28']::text[],false,'{"seq":3,"concept":"K5-1-u2-C29","difficulty":1,"kind":"mc","stem":"「돌담을 따라 걸은 하루」에서 글쓴이가 이곳을 찾은 까닭은 무엇인가요?","options":[{"t":"사회 시간에 배운 옛 마을을 직접 보고 싶어서","correct":true},{"t":"유명한 음식을 먹고 싶어서","mis":"K5-1-u2-X28"},{"t":"축제가 열려서","mis":"K5-1-u2-X28"},{"t":"친척이 그곳에 살아서","mis":"K5-1-u2-X28"}],"explanation":["음식 이야기는 없어요.","축제 이야기는 없어요.","첫 문단에 까닭이 있어요."],"asset":{"type":"passage","lines":["오월의 첫 주말, 나는 가족과 함께 순천 낙안읍성으로 향했다.","사회 시간에 옛 마을의 모습을 배운 뒤부터 직접 보고 싶었기 때문이다.","버스에서 내리자 낮고 긴 성벽이 눈앞에 펼쳐졌다.","우리는 먼저 동문으로 들어가 성벽 위를 걸었다.","안내판을 보니 이 성은 흙으로 쌓았다가 나중에 돌로 다시 쌓은 것이라고 한다.","흙담과 돌담이 함께 남아 있는 곳은 드물다고 했다."],"title":"「돌담을 따라 걸은 하루」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#4','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C30',1,'mc','auto','다음 가운데 견문에 해당하는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30']::text[],false,'{"seq":4,"concept":"K5-1-u2-C30","difficulty":1,"kind":"mc","stem":"다음 가운데 견문에 해당하는 문장은 어느 것인가요?","options":[{"t":"「한 자루의 호미가 되기까지 수백 번을 두드려야 한다고 하셨다.」","correct":true},{"t":"「성벽을 내려와 마을 골목으로 들어섰다.」","mis":"K5-1-u2-X28"},{"t":"「조금 알 것 같았다.」","mis":"K5-1-u2-X30"},{"t":"「해 질 무렵 남문을 나서며 뒤를 돌아보았다.」","mis":"K5-1-u2-X28"}],"explanation":["다닌 곳이 드러나요.","마음이 드러나요.","들은 설명은 견문이에요."],"asset":{"type":"passage","lines":["성벽을 내려와 마을 골목으로 들어섰다.","돌담은 어른 허리쯤 오는 높이였고, 담 위로 붉은 넝쿨꽃이 흘러넘치고 있었다.","담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.","골목 끝 대장간에서는 어르신 한 분이 쇠를 두드리고 계셨다.","한 자루의 호미가 되기까지 수백 번을 두드려야 한다고 하셨다.","무언가를 오래 두드려 만든다는 것이 어떤 일인지 조금 알 것 같았다.","해 질 무렵 남문을 나서며 뒤를 돌아보았다.","크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다."],"title":"「돌담을 따라 걸은 하루」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#5','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C29',2,'match','auto','「돌담을 따라 걸은 하루」의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u2-C29","difficulty":2,"kind":"match","stem":"「돌담을 따라 걸은 하루」의 문장과 요소를 이으세요.","pairs":[{"l":"성벽을 내려와 마을 골목으로 들어섰다","r":"여정"},{"l":"호미 한 자루에 수백 번을 두드린다고 하셨다","r":"견문"},{"l":"마을이 서로 마음을 열고 있는 것 같았다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["어디로 갔나요?","무엇을 듣고 보았나요?","어떻게 느꼈나요?"],"asset":{"type":"passage","lines":["성벽을 내려와 마을 골목으로 들어섰다.","돌담은 어른 허리쯤 오는 높이였고, 담 위로 붉은 넝쿨꽃이 흘러넘치고 있었다.","담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.","골목 끝 대장간에서는 어르신 한 분이 쇠를 두드리고 계셨다.","한 자루의 호미가 되기까지 수백 번을 두드려야 한다고 하셨다.","무언가를 오래 두드려 만든다는 것이 어떤 일인지 조금 알 것 같았다.","해 질 무렵 남문을 나서며 뒤를 돌아보았다.","크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다."],"title":"「돌담을 따라 걸은 하루」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#6','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C32',2,'mc','auto','견문과 감상을 가르는 물음으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X31']::text[],false,'{"seq":6,"concept":"K5-1-u2-C32","difficulty":2,"kind":"mc","stem":"견문과 감상을 가르는 물음으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있는가","correct":true},{"t":"문장이 긴가, 짧은가","mis":"K5-1-u2-X31"},{"t":"꾸미는 말이 많은가","mis":"K5-1-u2-X31"},{"t":"글의 앞쪽에 있는가","mis":"K5-1-u2-X31"}],"explanation":["길이로 가르지 않아요.","꾸미는 말로 가르지 않아요.","누구나 확인할 수 있으면 견문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#7','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C30',2,'ox','auto','안내판을 보고 알게 된 「흙으로 쌓았다가 돌로 다시 쌓았다」는 내용은 견문이 아니에요.',ARRAY['K5-1-u2-X29']::text[],false,'{"seq":7,"concept":"K5-1-u2-C30","difficulty":2,"kind":"ox","stem":"안내판을 보고 알게 된 「흙으로 쌓았다가 돌로 다시 쌓았다」는 내용은 견문이 아니에요.","answer":"X","reason_options":[{"t":"안내판에서 읽거나 들은 것도 여행하며 보고 들은 것이므로 견문이기 때문에","correct":true},{"t":"내 눈으로 직접 본 모습만 견문이기 때문에","mis":"K5-1-u2-X29"}],"mis":"K5-1-u2-X29","explanation":["읽은 것도 본 것이에요.","들은 설명도 견문이에요.","보고 들은 것은 모두 견문이에요."],"asset":{"type":"passage","lines":["오월의 첫 주말, 나는 가족과 함께 순천 낙안읍성으로 향했다.","사회 시간에 옛 마을의 모습을 배운 뒤부터 직접 보고 싶었기 때문이다.","버스에서 내리자 낮고 긴 성벽이 눈앞에 펼쳐졌다.","우리는 먼저 동문으로 들어가 성벽 위를 걸었다.","안내판을 보니 이 성은 흙으로 쌓았다가 나중에 돌로 다시 쌓은 것이라고 한다.","흙담과 돌담이 함께 남아 있는 곳은 드물다고 했다."],"title":"「돌담을 따라 걸은 하루」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#8','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C34',2,'mc','auto','「동문 → 골목 → 대장간 → 남문」만 적힌 글은 무엇에 가까운가요?',ARRAY['K5-1-u2-X33']::text[],false,'{"seq":8,"concept":"K5-1-u2-C34","difficulty":2,"kind":"mc","stem":"「동문 → 골목 → 대장간 → 남문」만 적힌 글은 무엇에 가까운가요?","options":[{"t":"일정표","correct":true},{"t":"기행문","mis":"K5-1-u2-X33"},{"t":"일기","mis":"K5-1-u2-X33"},{"t":"안내판","mis":"K5-1-u2-X33"}],"explanation":["보고 느낀 것이 없어요.","느낌이 없어요.","여정만 있으면 일정표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#9','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C35',2,'mc','auto','기행문의 글감으로 쓸 수 없는 것은 어느 것인가요?',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":9,"concept":"K5-1-u2-C35","difficulty":2,"kind":"mc","stem":"기행문의 글감으로 쓸 수 없는 것은 어느 것인가요?","options":[{"t":"아직 가 보지 않은 곳을 상상한 일","correct":true},{"t":"명절에 다녀온 친척 집","mis":"K5-1-u2-X34"},{"t":"학교에서 다녀온 현장 체험 학습","mis":"K5-1-u2-X34"},{"t":"우리 동네 오래된 시장에 다녀온 날","mis":"K5-1-u2-X34"}],"explanation":["친척 집도 글감이에요.","체험 학습도 글감이에요.","다녀온 곳이 있어야 기행문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_basic#10','kor',5,1,'u2','L07','g5_1_kor_u2_L07_basic','lesson_basic','K5-1-u2-C32',3,'mc','auto','「성벽은 사람 키보다 조금 높았다.」가 견문인 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X31','K5-1-u2-X30','K5-1-u2-X28']::text[],false,'{"seq":10,"concept":"K5-1-u2-C32","difficulty":3,"kind":"mc","stem":"「성벽은 사람 키보다 조금 높았다.」가 견문인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그곳에 함께 있던 사람이라면 누구나 똑같이 확인할 수 있기 때문이다","correct":true},{"t":"문장이 짧기 때문이다","mis":"K5-1-u2-X31"},{"t":"글쓴이의 마음이 드러나기 때문이다","mis":"K5-1-u2-X30"},{"t":"다닌 곳의 이름이 나오기 때문이다","mis":"K5-1-u2-X28"}],"explanation":["길이로 가르지 않아요.","마음이 드러나면 감상이에요.","누구나 확인할 수 있는 사실이에요."],"asset":{"type":"passage","lines":["오월의 첫 주말, 나는 가족과 함께 순천 낙안읍성으로 향했다.","사회 시간에 옛 마을의 모습을 배운 뒤부터 직접 보고 싶었기 때문이다.","버스에서 내리자 낮고 긴 성벽이 눈앞에 펼쳐졌다.","우리는 먼저 동문으로 들어가 성벽 위를 걸었다.","안내판을 보니 이 성은 흙으로 쌓았다가 나중에 돌로 다시 쌓은 것이라고 한다.","흙담과 돌담이 함께 남아 있는 곳은 드물다고 했다."],"title":"「돌담을 따라 걸은 하루」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#1','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C31',2,'mc','auto','「돌담을 따라 걸은 하루」 ②에서 감상에 해당하는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X30','K5-1-u2-X28']::text[],false,'{"seq":1,"concept":"K5-1-u2-C31","difficulty":2,"kind":"mc","stem":"「돌담을 따라 걸은 하루」 ②에서 감상에 해당하는 문장은 어느 것인가요?","options":[{"t":"「크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다.」","correct":true},{"t":"「담 위로 붉은 넝쿨꽃이 흘러넘치고 있었다.」","mis":"K5-1-u2-X30"},{"t":"「골목 끝 대장간에서는 어르신 한 분이 쇠를 두드리고 계셨다.」","mis":"K5-1-u2-X30"},{"t":"「성벽을 내려와 마을 골목으로 들어섰다.」","mis":"K5-1-u2-X28"}],"explanation":["본 모습이에요.","본 모습이에요.","「생각이 들었다」가 마음을 드러내요."],"asset":{"type":"passage","lines":["성벽을 내려와 마을 골목으로 들어섰다.","돌담은 어른 허리쯤 오는 높이였고, 담 위로 붉은 넝쿨꽃이 흘러넘치고 있었다.","담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.","골목 끝 대장간에서는 어르신 한 분이 쇠를 두드리고 계셨다.","한 자루의 호미가 되기까지 수백 번을 두드려야 한다고 하셨다.","무언가를 오래 두드려 만든다는 것이 어떤 일인지 조금 알 것 같았다.","해 질 무렵 남문을 나서며 뒤를 돌아보았다.","크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다."],"title":"「돌담을 따라 걸은 하루」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#2','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C36',2,'ox','auto','기행문은 글쓴이의 느낌을 담을 뿐 가 보지 않은 사람에게 정보를 전하지는 않아요.',ARRAY['K5-1-u2-X35']::text[],false,'{"seq":2,"concept":"K5-1-u2-C36","difficulty":2,"kind":"ox","stem":"기행문은 글쓴이의 느낌을 담을 뿐 가 보지 않은 사람에게 정보를 전하지는 않아요.","answer":"X","reason_options":[{"t":"기행문은 느낌을 새겨 두는 몫과 가 보지 않은 사람에게 정보를 전하는 몫을 함께 지니기 때문에","correct":true},{"t":"정보는 안내판에만 담기기 때문에","mis":"K5-1-u2-X35"}],"mis":"K5-1-u2-X35","explanation":["두 가지 몫이 있어요.","알려 주는 몫도 있어요.","마음을 담고 정보도 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#3','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C33',3,'mc','auto','다음 세 문장이 이어진 차례로 알맞은 것은 어느 것인가요? 「골목 끝 대장간에 이르렀다. / 어르신이 쇠를 두드리고 계셨다. / 조금 알 것 같았다.」',ARRAY['K5-1-u2-X28','K5-1-u2-X30','K5-1-u2-X31']::text[],false,'{"seq":3,"concept":"K5-1-u2-C33","difficulty":3,"kind":"mc","stem":"다음 세 문장이 이어진 차례로 알맞은 것은 어느 것인가요? 「골목 끝 대장간에 이르렀다. / 어르신이 쇠를 두드리고 계셨다. / 조금 알 것 같았다.」","options":[{"t":"여정 → 견문 → 감상","correct":true},{"t":"견문 → 여정 → 감상","mis":"K5-1-u2-X28"},{"t":"감상 → 견문 → 여정","mis":"K5-1-u2-X30"},{"t":"여정 → 감상 → 견문","mis":"K5-1-u2-X31"}],"explanation":["첫 문장은 다닌 곳이에요.","마지막은 마음이에요.","다닌 곳 → 본 것 → 느낀 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#4','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C33',3,'error','auto','기행문을 쓰는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X32','K5-1-u2-X33','K5-1-u2-X28']::text[],false,'{"seq":4,"concept":"K5-1-u2-C33","difficulty":3,"kind":"error","stem":"기행문을 쓰는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여정 · 견문 · 감상은 반드시 한 문단씩 따로 떼어 써야 해.」","correct":true,"mis_target":"K5-1-u2-X32"},{"t":"「한 문단 안에서 셋이 자연스럽게 이어질 수 있어.」","mis":"K5-1-u2-X33"},{"t":"「다닌 곳을 따라가면 글 전체의 흐름이 보여.」","mis":"K5-1-u2-X28"}],"explanation":["한 문단에 섞여도 돼요.","여정이 흐름을 만들어요.","셋을 따로 떼지 않고 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#5','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C34',3,'mc','auto','「오늘은 정말 즐거웠다. 신나고 행복한 하루였다.」만 쓴 글은 무엇에 가까운가요?',ARRAY['K5-1-u2-X33','K5-1-u2-X45']::text[],false,'{"seq":5,"concept":"K5-1-u2-C34","difficulty":3,"kind":"mc","stem":"「오늘은 정말 즐거웠다. 신나고 행복한 하루였다.」만 쓴 글은 무엇에 가까운가요?","options":[{"t":"일기","correct":true},{"t":"기행문","mis":"K5-1-u2-X33"},{"t":"일정표","mis":"K5-1-u2-X33"},{"t":"안내장","mis":"K5-1-u2-X45"}],"explanation":["여정과 견문이 없어요.","다닌 곳이 없어요.","감상만 있으면 일기에 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#6','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C36',3,'mc','auto','기행문을 남길 수 있는 형식에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X35','K5-1-u2-X33']::text[],false,'{"seq":6,"concept":"K5-1-u2-C36","difficulty":3,"kind":"mc","stem":"기행문을 남길 수 있는 형식에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"글과 사진뿐 아니라 그림 · 엽서 · 편지 · 동영상으로도 남길 수 있다","correct":true},{"t":"반드시 원고지에 글로만 써야 한다","mis":"K5-1-u2-X35"},{"t":"사진만 붙이면 기행문이 된다","mis":"K5-1-u2-X33"},{"t":"여행지에 직접 가서만 쓸 수 있다","mis":"K5-1-u2-X35"}],"explanation":["형식은 여러 가지예요.","보고 느낀 것이 있어야 해요.","여러 형식으로 남길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#7','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C35',3,'mc','auto','여행을 한 번도 멀리 가 보지 못해 기행문 글감이 없다는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":7,"concept":"K5-1-u2-C35","difficulty":3,"kind":"mc","stem":"여행을 한 번도 멀리 가 보지 못해 기행문 글감이 없다는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「명절에 간 친척 집이나 우리 동네 박물관에 다녀온 것도 글감이 돼.」","correct":true},{"t":"「멀리 다녀온 다음에 쓰면 돼.」","mis":"K5-1-u2-X34"},{"t":"「유명한 곳을 상상해서 써.」","mis":"K5-1-u2-X34"},{"t":"「기행문은 안 써도 돼.」","mis":"K5-1-u2-X34"}],"explanation":["멀리 가야 하는 것이 아니에요.","상상한 곳은 다닌 곳이 아니에요.","가까운 곳도 글감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#8','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C32',4,'essay','teacher','「담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.」가 견문인지 감상인지 판단하고, 그렇게 판단한 까닭을 구별 기준과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C32","difficulty":4,"kind":"essay","stem":"「담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.」가 견문인지 감상인지 판단하고, 그렇게 판단한 까닭을 구별 기준과 함께 쓰세요.","answer_guide":{"answer":"예: 감상이다. 같은 낮은 담을 보아도 「마음을 열고 있다」고 느끼는 것은 사람마다 다를 수 있기 때문이다. 그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있는 「돌담이 어른 허리쯤 오는 높이였다」는 견문이다.","scoring_points":["감상이라고 바르게 판단했는가","사람마다 다를 수 있다는 기준을 썼는가","견문과 견주어 설명했는가"]},"explanation":["마음속에서 일어난 것인가요?","누구나 똑같이 확인할 수 있나요?","기준으로 까닭을 써요."],"asset":{"type":"passage","lines":["성벽을 내려와 마을 골목으로 들어섰다.","돌담은 어른 허리쯤 오는 높이였고, 담 위로 붉은 넝쿨꽃이 흘러넘치고 있었다.","담이 낮아서인지 마을 전체가 서로 마음을 열고 있는 것처럼 느껴졌다.","골목 끝 대장간에서는 어르신 한 분이 쇠를 두드리고 계셨다.","한 자루의 호미가 되기까지 수백 번을 두드려야 한다고 하셨다.","무언가를 오래 두드려 만든다는 것이 어떤 일인지 조금 알 것 같았다.","해 질 무렵 남문을 나서며 뒤를 돌아보았다.","크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다."],"title":"「돌담을 따라 걸은 하루」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#9','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C34',4,'essay','teacher','일정표 「동문 → 골목 → 대장간 → 남문」을 기행문의 한 문단으로 바꾸어 쓰세요. 다닌 곳 하나를 골라 견문과 감상을 넣으세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C34","difficulty":4,"kind":"essay","stem":"일정표 「동문 → 골목 → 대장간 → 남문」을 기행문의 한 문단으로 바꾸어 쓰세요. 다닌 곳 하나를 골라 견문과 감상을 넣으세요.","answer_guide":{"answer":"예: 성벽을 내려와 마을 골목으로 들어섰다. 돌담은 어른 허리쯤 오는 높이였고, 담 위로 붉은 넝쿨꽃이 피어 있었다. 낮은 담 너머로 마당이 훤히 보여서 이웃끼리 서로 반갑게 인사를 나눌 것 같았다.","scoring_points":["다닌 곳이 드러나는가","보고 들은 것을 넣었는가","느끼거나 생각한 것을 넣어 한 문단으로 이었는가"]},"explanation":["다닌 곳 하나를 골라요.","본 것과 느낀 것을 얹어요.","셋을 한 문단으로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L07_challenge#10','kor',5,1,'u2','L07','g5_1_kor_u2_L07_challenge','lesson_challenge','K5-1-u2-C36',4,'essay','teacher','기행문의 「두 가지 몫」이 무엇인지 쓰고, 「돌담을 따라 걸은 하루」에서 각각의 몫을 하는 문장을 하나씩 찾아 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C36","difficulty":4,"kind":"essay","stem":"기행문의 「두 가지 몫」이 무엇인지 쓰고, 「돌담을 따라 걸은 하루」에서 각각의 몫을 하는 문장을 하나씩 찾아 쓰세요.","answer_guide":{"answer":"예: 첫째 몫은 그때의 느낌을 오래 새겨 두는 것이다 — 「크고 높은 것만 오래 남는 것은 아니라는 생각이 들었다.」 둘째 몫은 가 보지 않은 사람에게 그곳의 정보를 전하는 것이다 — 「흙담과 돌담이 함께 남아 있는 곳은 드물다고 했다.」","scoring_points":["두 몫을 바르게 썼는가","느낌을 새기는 문장을 찾았는가","정보를 전하는 문장을 찾았는가"]},"explanation":["마음을 담는 몫이 있어요.","알려 주는 몫도 있어요.","문장을 하나씩 짝지어요."],"asset":{"type":"passage","lines":["오월의 첫 주말, 나는 가족과 함께 순천 낙안읍성으로 향했다.","사회 시간에 옛 마을의 모습을 배운 뒤부터 직접 보고 싶었기 때문이다.","버스에서 내리자 낮고 긴 성벽이 눈앞에 펼쳐졌다.","우리는 먼저 동문으로 들어가 성벽 위를 걸었다.","안내판을 보니 이 성은 흙으로 쌓았다가 나중에 돌로 다시 쌓은 것이라고 한다.","흙담과 돌담이 함께 남아 있는 곳은 드물다고 했다."],"title":"「돌담을 따라 걸은 하루」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#1','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C37',1,'mc','auto','「책이 사는 마을에서」의 처음 부분에 나타난 내용이 아닌 것은 어느 것인가요?',ARRAY['K5-1-u2-X36']::text[],false,'{"seq":1,"concept":"K5-1-u2-C37","difficulty":1,"kind":"mc","stem":"「책이 사는 마을에서」의 처음 부분에 나타난 내용이 아닌 것은 어느 것인가요?","options":[{"t":"여행에서 배운 것","correct":true},{"t":"여행지 이름과 함께 간 사람","mis":"K5-1-u2-X36"},{"t":"여행을 떠난 까닭","mis":"K5-1-u2-X36"},{"t":"출발할 때의 날씨","mis":"K5-1-u2-X36"}],"explanation":["「아버지와 함께 파주 출판도시로」가 있어요.","「늘 궁금했기 때문이다」가 있어요.","배운 것은 끝부분에 들어가요."],"asset":{"type":"passage","lines":["가을 방학을 맞아 아버지와 함께 파주 출판도시로 기차와 버스를 갈아타며 다녀왔다.","책이 어떻게 만들어지는지 늘 궁금했기 때문이다.","떠나는 날 아침, 하늘이 높고 바람이 서늘해 걷기에 알맞은 날씨였다.","버스에서 내리자 네모반듯한 건물들이 줄지어 서 있었다.","책의 모양을 닮은 건물도 있어서, 이름값을 하는 도시라는 생각이 들었다."],"title":"「책이 사는 마을에서」 처음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#2','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C38',1,'mc','auto','「책이 사는 마을에서」 가운데 부분에서 글쓴이가 가장 먼저 찾은 곳은 어디인가요?',ARRAY['K5-1-u2-X37']::text[],false,'{"seq":2,"concept":"K5-1-u2-C38","difficulty":1,"kind":"mc","stem":"「책이 사는 마을에서」 가운데 부분에서 글쓴이가 가장 먼저 찾은 곳은 어디인가요?","options":[{"t":"활판 인쇄 박물관","correct":true},{"t":"종이 공장 전시관","mis":"K5-1-u2-X37"},{"t":"언덕 위 서점","mis":"K5-1-u2-X37"},{"t":"기차역","mis":"K5-1-u2-X37"}],"explanation":["「다음으로」 들른 곳이에요.","「마지막으로」 오른 곳이에요.","「먼저」 찾은 곳이에요."],"asset":{"type":"passage","lines":["우리는 먼저 활판 인쇄 박물관을 찾았다.","손톱만 한 쇠 활자가 서랍마다 빼곡히 꽂혀 있었다.","한 면을 짜려면 활자를 하나하나 골라 뒤집어 심어야 한다고 한다.","다음으로 종이 공장 전시관에 들렀다.","나무가 잘게 부서져 죽처럼 되었다가 얇게 펴져 종이가 되는 과정을 영상으로 보았다.","마지막으로 언덕 위 서점에 올랐다. 오래된 책 냄새가 방 안에 가득했다.","여기 있는 책들이 모두 누군가의 오랜 시간이라는 생각에 함부로 넘길 수 없었다."],"title":"「책이 사는 마을에서」 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#3','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C39',1,'mc','auto','기행문의 끝부분에 들어갈 내용으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X36']::text[],false,'{"seq":3,"concept":"K5-1-u2-C39","difficulty":1,"kind":"mc","stem":"기행문의 끝부분에 들어갈 내용으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞으로의 계획이나 각오","correct":true},{"t":"출발할 때의 날씨와 기분","mis":"K5-1-u2-X36"},{"t":"함께 가는 사람과 교통편","mis":"K5-1-u2-X36"},{"t":"여행을 떠난 까닭","mis":"K5-1-u2-X36"}],"explanation":["처음에 들어가요.","처음에 들어가요.","끝에는 계획이나 각오가 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#4','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C40',1,'mc','auto','기행문의 제목은 어떻게 붙이는 것이 좋은가요?',ARRAY['K5-1-u2-X39']::text[],false,'{"seq":4,"concept":"K5-1-u2-C40","difficulty":1,"kind":"mc","stem":"기행문의 제목은 어떻게 붙이는 것이 좋은가요?","options":[{"t":"여행지와 느낌이 함께 드러나게 붙인다","correct":true},{"t":"여행지 이름만 쓴다","mis":"K5-1-u2-X39"},{"t":"「즐거운 하루」처럼 느낌만 쓴다","mis":"K5-1-u2-X39"},{"t":"여행한 날짜만 쓴다","mis":"K5-1-u2-X39"}],"explanation":["느낌이 빠졌어요.","어디인지 빠졌어요.","여행지와 느낌을 함께 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#5','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C38',2,'match','auto','가운데 부분의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u2-C38","difficulty":2,"kind":"match","stem":"가운데 부분의 문장과 요소를 이으세요.","pairs":[{"l":"다음으로 종이 공장 전시관에 들렀다","r":"여정"},{"l":"한 면을 짜려면 활자를 하나하나 심어야 한다고 한다","r":"견문"},{"l":"책들이 모두 누군가의 오랜 시간이라는 생각이 들었다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["다닌 곳인가요?","보고 들은 것인가요?","느낀 것인가요?"],"asset":{"type":"passage","lines":["우리는 먼저 활판 인쇄 박물관을 찾았다.","손톱만 한 쇠 활자가 서랍마다 빼곡히 꽂혀 있었다.","한 면을 짜려면 활자를 하나하나 골라 뒤집어 심어야 한다고 한다.","다음으로 종이 공장 전시관에 들렀다.","나무가 잘게 부서져 죽처럼 되었다가 얇게 펴져 종이가 되는 과정을 영상으로 보았다.","마지막으로 언덕 위 서점에 올랐다. 오래된 책 냄새가 방 안에 가득했다.","여기 있는 책들이 모두 누군가의 오랜 시간이라는 생각에 함부로 넘길 수 없었다."],"title":"「책이 사는 마을에서」 가운데"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#6','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C39',2,'mc','auto','「책이 사는 마을에서」 끝부분에 나타나지 않은 내용은 어느 것인가요?',ARRAY['K5-1-u2-X38']::text[],false,'{"seq":6,"concept":"K5-1-u2-C39","difficulty":2,"kind":"mc","stem":"「책이 사는 마을에서」 끝부분에 나타나지 않은 내용은 어느 것인가요?","options":[{"t":"출발할 때의 날씨와 기분","correct":true},{"t":"여행하고 난 뒤 전체적인 느낌","mis":"K5-1-u2-X38"},{"t":"앞으로의 계획","mis":"K5-1-u2-X38"},{"t":"집에 와서 해 본 일","mis":"K5-1-u2-X38"}],"explanation":["「부지런히 … 느낌을 받았다」가 있어요.","「다시 오게 된다면」이 있어요.","날씨는 처음 부분에 있었어요."],"asset":{"type":"passage","lines":["돌아오는 버스에서 가방 속 책을 자꾸 만져 보았다.","이 도시는 조용했지만 어느 곳보다 부지런히 무언가를 만들고 있다는 느낌을 받았다.","집에 와서는 책 뒤쪽에 적힌 만든 사람들의 이름을 처음으로 찬찬히 읽어 보았다.","다음에 이곳에 다시 오게 된다면 책을 직접 만들어 보는 체험에 참여하고 싶다."],"title":"「책이 사는 마을에서」 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#7','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C37',2,'mc','auto','기행문의 처음 부분에 들어갈 내용으로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X36','K5-1-u2-X38']::text[],false,'{"seq":7,"concept":"K5-1-u2-C37","difficulty":2,"kind":"mc","stem":"기행문의 처음 부분에 들어갈 내용으로만 묶은 것은 어느 것인가요?","options":[{"t":"여행을 떠난 까닭 · 함께 가는 사람과 교통편 · 여행에 대한 기대","correct":true},{"t":"여행을 떠난 까닭 · 여행지에서 들은 설명 · 여행에 대한 기대","mis":"K5-1-u2-X36"},{"t":"함께 가는 사람 · 다음에 다시 오면 하고 싶은 일 · 교통편","mis":"K5-1-u2-X38"},{"t":"여행지에서 들은 설명 · 앞으로의 각오 · 배운 것","mis":"K5-1-u2-X36"}],"explanation":["들은 설명은 가운데예요.","다시 오면 할 일은 끝이에요.","떠나기 전이나 막 도착했을 때의 내용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#8','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C41',2,'blank','auto','빈칸에 알맞은 말을 고르세요. 「기행문을 쓰기 전에 처음 · 가운데 · 끝에 들어갈 내용을 (　　)(으)로 정리한다.」',ARRAY['K5-1-u2-X40']::text[],false,'{"seq":8,"concept":"K5-1-u2-C41","difficulty":2,"kind":"blank","stem":"빈칸에 알맞은 말을 고르세요. 「기행문을 쓰기 전에 처음 · 가운데 · 끝에 들어갈 내용을 (　　)(으)로 정리한다.」","options":[{"t":"개요","correct":true},{"t":"일기","mis":"K5-1-u2-X40"},{"t":"안내판","mis":"K5-1-u2-X40"},{"t":"영수증","mis":"K5-1-u2-X40"}],"explanation":["일기는 하루를 쓴 글이에요.","안내판은 정보만 있어요.","쓰기 전에 짜는 뼈대가 개요예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#9','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C38',2,'ox','auto','기행문의 가운데 부분에는 다닌 곳만 차례대로 적으면 돼요.',ARRAY['K5-1-u2-X37']::text[],false,'{"seq":9,"concept":"K5-1-u2-C38","difficulty":2,"kind":"ox","stem":"기행문의 가운데 부분에는 다닌 곳만 차례대로 적으면 돼요.","answer":"X","reason_options":[{"t":"다닌 곳마다 보고 들은 것과 느낀 것을 함께 써야 하기 때문에","correct":true},{"t":"다닌 곳의 차례가 기행문의 전부이기 때문에","mis":"K5-1-u2-X37"}],"mis":"K5-1-u2-X37","explanation":["그러면 일정표가 돼요.","견문과 감상이 빠졌어요.","다닌 곳마다 견문과 감상을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_basic#10','kor',5,1,'u2','L09','g5_1_kor_u2_L09_basic','lesson_basic','K5-1-u2-C41',3,'mc','auto','어떤 친구가 짠 개요에서 잘못 놓인 항목은 어느 것인가요?',ARRAY['K5-1-u2-X36','K5-1-u2-X37','K5-1-u2-X38']::text[],false,'{"seq":10,"concept":"K5-1-u2-C41","difficulty":3,"kind":"mc","stem":"어떤 친구가 짠 개요에서 잘못 놓인 항목은 어느 것인가요?","options":[{"t":"「다음에는 체험에 참여하고 싶음」","correct":true},{"t":"「가족과 기차로 다녀옴」","mis":"K5-1-u2-X36"},{"t":"「종이 만드는 과정을 들음」","mis":"K5-1-u2-X37"},{"t":"「부지런한 도시라는 느낌」","mis":"K5-1-u2-X38"}],"explanation":["처음에 알맞아요.","가운데에 알맞아요.","앞으로의 계획은 끝에 들어가요."],"asset":{"type":"passage","lines":["처음 　· 가족과 기차로 다녀옴 · 배운 것을 직접 보고 싶었음","　　　 · 다음에는 체험에 참여하고 싶음","가운데 · 박물관에서 활자를 봄 · 종이 만드는 과정을 들음","　　　 · 서점에서 책 냄새를 맡음","끝 　　· 부지런한 도시라는 느낌 · 만든 사람들의 이름을 찾아 읽음"],"title":"어떤 친구가 짠 기행문 개요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#1','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C37',2,'mc','auto','「떠나는 날 아침, 하늘이 높고 바람이 서늘해 걷기에 알맞은 날씨였다.」는 처음 부분의 어떤 내용인가요?',ARRAY['K5-1-u2-X36','K5-1-u2-X37','K5-1-u2-X38']::text[],false,'{"seq":1,"concept":"K5-1-u2-C37","difficulty":2,"kind":"mc","stem":"「떠나는 날 아침, 하늘이 높고 바람이 서늘해 걷기에 알맞은 날씨였다.」는 처음 부분의 어떤 내용인가요?","options":[{"t":"출발할 때의 날씨와 기분","correct":true},{"t":"여행을 떠난 까닭","mis":"K5-1-u2-X36"},{"t":"여행지에서 본 것","mis":"K5-1-u2-X37"},{"t":"앞으로의 계획","mis":"K5-1-u2-X38"}],"explanation":["까닭은 「궁금했기 때문이다」예요.","아직 여행지에 들어서지 않았어요.","떠나는 날의 날씨예요."],"asset":{"type":"passage","lines":["가을 방학을 맞아 아버지와 함께 파주 출판도시로 기차와 버스를 갈아타며 다녀왔다.","책이 어떻게 만들어지는지 늘 궁금했기 때문이다.","떠나는 날 아침, 하늘이 높고 바람이 서늘해 걷기에 알맞은 날씨였다.","버스에서 내리자 네모반듯한 건물들이 줄지어 서 있었다.","책의 모양을 닮은 건물도 있어서, 이름값을 하는 도시라는 생각이 들었다."],"title":"「책이 사는 마을에서」 처음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#2','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C42',2,'ox','auto','기행문을 다 쓰고 나면 쓰기 과정을 돌아볼 필요가 없어요.',ARRAY['K5-1-u2-X41']::text[],false,'{"seq":2,"concept":"K5-1-u2-C42","difficulty":2,"kind":"ox","stem":"기행문을 다 쓰고 나면 쓰기 과정을 돌아볼 필요가 없어요.","answer":"X","reason_options":[{"t":"계획하기 · 글쓰기 · 수정하기 가운데 아쉬웠던 단계를 짚어 두면 다음 글이 나아지기 때문에","correct":true},{"t":"다 쓴 글은 고칠 수 없기 때문에","mis":"K5-1-u2-X41"}],"mis":"K5-1-u2-X41","explanation":["돌아보는 것도 쓰기의 한 부분이에요.","아쉬운 단계를 짚어요.","다음 글이 나아져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#3','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C42',3,'mc','auto','「여정 · 견문 · 감상을 한 문단씩 따로 썼다」는 아쉬운 점을 고칠 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X33','K5-1-u2-X37','K5-1-u2-X32']::text[],false,'{"seq":3,"concept":"K5-1-u2-C42","difficulty":3,"kind":"mc","stem":"「여정 · 견문 · 감상을 한 문단씩 따로 썼다」는 아쉬운 점을 고칠 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"다닌 곳마다 견문과 감상이 어우러지도록 다시 묶는다","correct":true},{"t":"감상 문단을 모두 지운다","mis":"K5-1-u2-X33"},{"t":"여정 문단을 맨 끝으로 옮긴다","mis":"K5-1-u2-X37"},{"t":"문단을 더 잘게 나눈다","mis":"K5-1-u2-X32"}],"explanation":["감상이 없으면 기행문이 아니에요.","차례가 흐트러져요.","다닌 곳마다 셋을 함께 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#4','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C38',3,'mc','auto','기행문의 가운데 부분을 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X37','K5-1-u2-X32','K5-1-u2-X33']::text[],false,'{"seq":4,"concept":"K5-1-u2-C38","difficulty":3,"kind":"mc","stem":"기행문의 가운데 부분을 쓰는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다닌 곳의 차례를 따라가며 곳마다 본 것과 느낀 것을 함께 쓴다","correct":true},{"t":"기억에 남는 곳부터 차례 없이 쓴다","mis":"K5-1-u2-X37"},{"t":"본 것을 모두 모아 쓴 다음 느낀 것을 한꺼번에 쓴다","mis":"K5-1-u2-X32"},{"t":"다닌 곳 이름만 빠짐없이 쓴다","mis":"K5-1-u2-X33"}],"explanation":["차례가 흐트러져요.","셋을 따로 떼었어요.","공간의 이동을 따라 셋을 함께 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#5','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C41',3,'error','auto','기행문 개요를 짜는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X40','K5-1-u2-X32']::text[],false,'{"seq":5,"concept":"K5-1-u2-C41","difficulty":3,"kind":"error","stem":"기행문 개요를 짜는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여러 번 다녀온 여행을 한 글에 모두 섞어 쓰면 더 풍성해.」","correct":true,"mis_target":"K5-1-u2-X40"},{"t":"「여행 사진이나 일기를 보며 기억에 남는 장면을 떠올려.」","mis":"K5-1-u2-X40"},{"t":"「가운데는 다닌 곳별로 견문과 감상을 나란히 적어.」","mis":"K5-1-u2-X32"}],"explanation":["장면을 떠올리는 것은 좋은 방법이에요.","가운데는 곳별로 적어요.","쓸 여행 경험은 하나를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#6','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C40',3,'mc','auto','「책이 사는 마을에서」처럼 여행지와 느낌이 함께 드러나는 제목은 어느 것인가요?',ARRAY['K5-1-u2-X39']::text[],false,'{"seq":6,"concept":"K5-1-u2-C40","difficulty":3,"kind":"mc","stem":"「책이 사는 마을에서」처럼 여행지와 느낌이 함께 드러나는 제목은 어느 것인가요?","options":[{"t":"「부지런한 책의 도시, 파주」","correct":true},{"t":"「파주」","mis":"K5-1-u2-X39"},{"t":"「행복한 날」","mis":"K5-1-u2-X39"},{"t":"「가을 방학」","mis":"K5-1-u2-X39"}],"explanation":["여행지만 있어요.","느낌만 있어요.","여행지와 느낌이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#7','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C39',3,'mc','auto','끝부분에 들어가기에 알맞지 않은 문장은 어느 것인가요?',ARRAY['K5-1-u2-X38']::text[],false,'{"seq":7,"concept":"K5-1-u2-C39","difficulty":3,"kind":"mc","stem":"끝부분에 들어가기에 알맞지 않은 문장은 어느 것인가요?","options":[{"t":"「다음으로 언덕 위 서점에 올랐다.」","correct":true},{"t":"「책 뒤쪽에 적힌 만든 사람들의 이름을 찬찬히 읽어 보았다.」","mis":"K5-1-u2-X38"},{"t":"「다음에는 책을 직접 만들어 보는 체험에 참여하고 싶다.」","mis":"K5-1-u2-X38"},{"t":"「조용하지만 부지런한 도시라는 느낌을 받았다.」","mis":"K5-1-u2-X38"}],"explanation":["돌아와서 해 본 일이에요.","앞으로의 계획이에요.","새로 다닌 곳은 가운데에 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#8','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C37',4,'essay','teacher','가 본 곳 하나를 떠올려 기행문의 처음 부분을 써 보세요. 여행지 · 함께 간 사람 · 떠난 까닭 · 출발할 때의 날씨나 기분을 모두 넣으세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C37","difficulty":4,"kind":"essay","stem":"가 본 곳 하나를 떠올려 기행문의 처음 부분을 써 보세요. 여행지 · 함께 간 사람 · 떠난 까닭 · 출발할 때의 날씨나 기분을 모두 넣으세요.","answer_guide":{"answer":"예: 지난 여름 방학에 나는 사촌 언니와 함께 지하철을 타고 국립 과학관에 다녀왔다. 공룡 뼈를 직접 보고 싶었기 때문이다. 그날은 아침부터 햇볕이 쨍쨍했지만 공룡을 볼 생각에 발걸음이 가벼웠다.","scoring_points":["여행지와 함께 간 사람을 썼는가","떠난 까닭을 썼는가","출발할 때의 날씨나 기분을 썼는가"]},"explanation":["어디 · 누구와 · 왜.","그날 날씨와 기분도 떠올려요.","네 가지를 모두 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#9','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C42',4,'essay','teacher','「여정 · 견문 · 감상을 한 문단씩 따로 썼다」는 점검 결과를 받은 친구에게 고쳐 쓸 방법을 알려 주고, 그렇게 고치면 무엇이 좋아지는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C42","difficulty":4,"kind":"essay","stem":"「여정 · 견문 · 감상을 한 문단씩 따로 썼다」는 점검 결과를 받은 친구에게 고쳐 쓸 방법을 알려 주고, 그렇게 고치면 무엇이 좋아지는지 쓰세요.","answer_guide":{"answer":"예: 다닌 곳마다 문단을 나누고, 한 문단 안에 그곳에서 본 것과 그때 느낀 것을 함께 묶어 써 봐. 그러면 읽는 사람이 다닌 곳을 따라가며 그곳의 모습과 네 마음을 함께 느낄 수 있어서 글이 자연스러워져.","scoring_points":["다닌 곳마다 묶는 방법을 알려 주었는가","한 문단 안에서 견문과 감상을 이으라고 했는가","좋아지는 점을 썼는가"]},"explanation":["따로 떼면 흐름이 끊겨요.","다닌 곳을 기준으로 묶어요.","읽는 사람 쪽에서 좋아지는 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L09_challenge#10','kor',5,1,'u2','L09','g5_1_kor_u2_L09_challenge','lesson_challenge','K5-1-u2-C39',4,'essay','teacher','「책이 사는 마을에서」의 끝부분을 읽고, 글쓴이가 여행하고 난 뒤 달라진 점과 앞으로의 계획을 찾아 쓰세요. 그리고 끝부분에 이런 내용이 들어가는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C39","difficulty":4,"kind":"essay","stem":"「책이 사는 마을에서」의 끝부분을 읽고, 글쓴이가 여행하고 난 뒤 달라진 점과 앞으로의 계획을 찾아 쓰세요. 그리고 끝부분에 이런 내용이 들어가는 까닭을 쓰세요.","answer_guide":{"answer":"예: 달라진 점 — 집에 와서 책 뒤쪽에 적힌 만든 사람들의 이름을 처음으로 찬찬히 읽어 보았다. 앞으로의 계획 — 다시 오게 되면 책을 직접 만들어 보는 체험에 참여하고 싶다. 끝부분은 여행을 돌아보며 전체적인 느낌과 배운 것, 앞으로의 각오를 정리하는 곳이기 때문이다.","scoring_points":["달라진 점을 찾았는가","앞으로의 계획을 찾았는가","끝부분의 몫으로 까닭을 썼는가"]},"explanation":["끝부분을 다시 읽어요.","돌아와서 한 일과 바람을 찾아요.","끝부분의 몫을 떠올려요."],"asset":{"type":"passage","lines":["돌아오는 버스에서 가방 속 책을 자꾸 만져 보았다.","이 도시는 조용했지만 어느 곳보다 부지런히 무언가를 만들고 있다는 느낌을 받았다.","집에 와서는 책 뒤쪽에 적힌 만든 사람들의 이름을 처음으로 찬찬히 읽어 보았다.","다음에 이곳에 다시 오게 된다면 책을 직접 만들어 보는 체험에 참여하고 싶다."],"title":"「책이 사는 마을에서」 끝"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#1','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C43',1,'mc','auto','여행지 안내장에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u2-X42']::text[],false,'{"seq":1,"concept":"K5-1-u2-C43","difficulty":1,"kind":"mc","stem":"여행지 안내장에 들어갈 내용으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"우리 집 주소","correct":true},{"t":"갈 만한 곳","mis":"K5-1-u2-X42"},{"t":"먹을거리","mis":"K5-1-u2-X42"},{"t":"문화유산","mis":"K5-1-u2-X42"}],"explanation":["가려는 사람이 궁금해해요.","가려는 사람이 궁금해해요.","우리 집 주소는 여행지와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#2','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C44',1,'mc','auto','다닌 곳의 위치와 차례를 한눈에 보여 줄 때 알맞은 안내장 형태는 어느 것인가요?',ARRAY['K5-1-u2-X43']::text[],false,'{"seq":2,"concept":"K5-1-u2-C44","difficulty":1,"kind":"mc","stem":"다닌 곳의 위치와 차례를 한눈에 보여 줄 때 알맞은 안내장 형태는 어느 것인가요?","options":[{"t":"관광 지도","correct":true},{"t":"그림엽서","mis":"K5-1-u2-X43"},{"t":"소책자","mis":"K5-1-u2-X43"},{"t":"광고지","mis":"K5-1-u2-X43"}],"explanation":["한 장면의 인상을 전해요.","자세한 설명을 담아요.","위치와 차례는 지도로 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#3','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C45',1,'mc','auto','공공 누리집의 사진을 안내장에 쓸 때 지켜야 할 것은 어느 것인가요?',ARRAY['K5-1-u2-X44']::text[],false,'{"seq":3,"concept":"K5-1-u2-C45","difficulty":1,"kind":"mc","stem":"공공 누리집의 사진을 안내장에 쓸 때 지켜야 할 것은 어느 것인가요?","options":[{"t":"이용 조건을 확인하고 출처를 밝힌다","correct":true},{"t":"마음에 드는 것을 그냥 가져다 쓴다","mis":"K5-1-u2-X44"},{"t":"어디서 가져왔는지 숨긴다","mis":"K5-1-u2-X44"},{"t":"사진 속 글자를 지우고 쓴다","mis":"K5-1-u2-X44"}],"explanation":["남이 만든 자료예요.","출처는 밝혀요.","조건을 확인하고 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
