INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#5','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C44',2,'match','auto','안내장 형태와 어울리는 쓰임을 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K5-1-u2-C44","difficulty":2,"kind":"match","stem":"안내장 형태와 어울리는 쓰임을 이으세요.","pairs":[{"l":"관광 지도","r":"다닌 곳의 차례를 보일 때"},{"l":"그림엽서","r":"한 장면의 인상을 전할 때"},{"l":"소책자","r":"여러 곳을 자세히 설명할 때"}],"mis":"K5-1-u2-X43","explanation":["전할 내용의 양을 봐요.","전하는 방식을 봐요.","형태마다 쓰임이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#6','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C45',2,'ox','auto','누리집에 공개된 자료는 누구나 볼 수 있으니 출처를 밝히지 않아도 돼요.',ARRAY['K5-1-u2-X44']::text[],false,'{"seq":6,"concept":"K5-1-u2-C45","difficulty":2,"kind":"ox","stem":"누리집에 공개된 자료는 누구나 볼 수 있으니 출처를 밝히지 않아도 돼요.","answer":"X","reason_options":[{"t":"자료마다 쓸 수 있는 범위가 정해져 있어 이용 조건을 확인하고 출처를 밝혀야 하기 때문에","correct":true},{"t":"공개된 자료는 내가 만든 자료와 같기 때문에","mis":"K5-1-u2-X44"}],"mis":"K5-1-u2-X44","explanation":["공개되었다고 내 것이 아니에요.","쓸 수 있는 범위가 있어요.","조건 확인 · 출처 밝히기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_basic#7','kor',5,1,'u2','L12','g5_1_kor_u2_L12_basic','lesson_basic','K5-1-u2-C46',2,'mc','auto','안내장에 감상을 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X45','K5-1-u2-X30']::text[],false,'{"seq":7,"concept":"K5-1-u2-C46","difficulty":2,"kind":"mc","stem":"안내장에 감상을 넣는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"느낌이 있어야 읽는 사람이 가 보고 싶어지기 때문이다","correct":true},{"t":"정보를 적을 칸이 모자라기 때문이다","mis":"K5-1-u2-X45"},{"t":"감상이 있어야 안내판이 되기 때문이다","mis":"K5-1-u2-X45"},{"t":"감상은 정확한 정보이기 때문이다","mis":"K5-1-u2-X30"}],"explanation":["칸의 문제가 아니에요.","정보만 있으면 안내판이에요.","감상은 마음을 움직여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
