INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#2','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C46',2,'ox','auto','안내장에 「관람 시간은 오전 아홉 시부터입니다」 같은 정보만 있어도 사람들이 가 보고 싶어져요.',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":2,"concept":"K5-1-u2-C46","difficulty":2,"kind":"ox","stem":"안내장에 「관람 시간은 오전 아홉 시부터입니다」 같은 정보만 있어도 사람들이 가 보고 싶어져요.","answer":"X","reason_options":[{"t":"정보만 있으면 안내판이 되고, 느낌이 있어야 가 보고 싶어지기 때문에","correct":true},{"t":"정보가 많을수록 마음이 더 움직이기 때문에","mis":"K5-1-u2-X45"}],"mis":"K5-1-u2-X45","explanation":["정보도 필요하지만 그것만으론 부족해요.","느낌이 마음을 옮겨요.","항목마다 느낀 한 문장을 넣어요."],"asset":{"type":"passage","lines":["㉮ 해 질 무렵 돌담길은 걸음을 늦추게 합니다.","㉯ 성벽은 걸어서 한 바퀴 도는 데 한 시간쯤 걸립니다.","㉰ 관람 시간은 오전 아홉 시부터입니다."],"title":"안내장에 넣으려고 쓴 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#3','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C46',3,'mc','auto','안내장의 세 요소 가운데 감상을 담은 것은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30','K5-1-u2-X45']::text[],false,'{"seq":3,"concept":"K5-1-u2-C46","difficulty":3,"kind":"mc","stem":"안내장의 세 요소 가운데 감상을 담은 것은 어느 것인가요?","options":[{"t":"「담이 낮아 마을이 열려 보인다」","correct":true},{"t":"「동문 → 골목 → 대장간 → 남문」","mis":"K5-1-u2-X28"},{"t":"「흙담과 돌담이 함께 남은 성벽」","mis":"K5-1-u2-X30"},{"t":"「관람 시간은 오전 아홉 시부터」","mis":"K5-1-u2-X45"}],"explanation":["추천하는 길의 차례 — 여정이에요.","볼 것 — 견문이에요.","내가 느낀 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#4','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C45',3,'error','auto','안내장을 만드는 태도에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X44']::text[],false,'{"seq":4,"concept":"K5-1-u2-C45","difficulty":3,"kind":"error","stem":"안내장을 만드는 태도에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「누리집 사진은 출처를 지우고 쓰면 더 깔끔해.」","correct":true,"mis_target":"K5-1-u2-X44"},{"t":"「쓰기 전에 이용 조건을 확인해.」","mis":"K5-1-u2-X44"},{"t":"「가져온 자료 옆에 출처를 적어.」","mis":"K5-1-u2-X44"}],"explanation":["조건 확인은 맞아요.","출처를 적는 것은 맞아요.","출처는 지우지 않고 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#5','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C48',3,'mc','auto','친구의 안내장 발표를 듣고 한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X47','K5-1-u2-X27']::text[],false,'{"seq":5,"concept":"K5-1-u2-C48","difficulty":3,"kind":"mc","stem":"친구의 안내장 발표를 듣고 한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「〈해 질 무렵 돌담길은 걸음을 늦추게 합니다〉라는 문구에서 나도 가 보고 싶어졌어.」","correct":true},{"t":"「잘 만들었네.」","mis":"K5-1-u2-X47"},{"t":"「글씨가 커서 좋았어.」","mis":"K5-1-u2-X27"},{"t":"「종이가 예뻤어.」","mis":"K5-1-u2-X27"}],"explanation":["무엇이 좋았는지 빠졌어요.","마음이 든 문구를 짚지 않았어요.","어느 문구에서 가 보고 싶어졌는지 짚었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#6','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C47',3,'mc','auto','「우리 반에서 정할 수 있는 활동」으로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X46']::text[],false,'{"seq":6,"concept":"K5-1-u2-C47","difficulty":3,"kind":"mc","stem":"「우리 반에서 정할 수 있는 활동」으로 알맞은 것은 어느 것인가요?","options":[{"t":"모둠마다 과거 · 현재 · 미래를 맡아 이야기를 쓰고 이어 붙이는 시간 여행 이야기 꾸미기","correct":true},{"t":"안내장을 똑같이 베껴 쓰기","mis":"K5-1-u2-X46"},{"t":"여행 비용 계산하기","mis":"K5-1-u2-X46"},{"t":"가 본 곳 이름 외우기","mis":"K5-1-u2-X46"}],"explanation":["배운 것을 쓰는 활동이 아니에요.","이 단원과 관계없어요.","시간 표현을 살린 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#7','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C43',3,'mc','auto','안내장을 볼 사람이 가장 궁금해할 내용으로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X42']::text[],false,'{"seq":7,"concept":"K5-1-u2-C43","difficulty":3,"kind":"mc","stem":"안내장을 볼 사람이 가장 궁금해할 내용으로만 묶은 것은 어느 것인가요?","options":[{"t":"갈 만한 곳 · 즐길 거리 · 먹을거리","correct":true},{"t":"갈 만한 곳 · 내 시험 점수 · 먹을거리","mis":"K5-1-u2-X42"},{"t":"우리 집 주소 · 즐길 거리 · 문화유산","mis":"K5-1-u2-X42"},{"t":"내 생일 · 먹을거리 · 문화유산","mis":"K5-1-u2-X42"}],"explanation":["시험 점수는 관계없어요.","집 주소는 관계없어요.","가려는 사람이 궁금한 것만 골랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#8','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C46',4,'essay','teacher','안내 문구 ㉯ 「성벽은 걸어서 한 바퀴 도는 데 한 시간쯤 걸립니다.」에 감상을 한 문장 더해 고쳐 쓰고, 고친 문구가 읽는 사람에게 어떤 마음이 들게 하는지 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K5-1-u2-C46","difficulty":4,"kind":"essay","stem":"안내 문구 ㉯ 「성벽은 걸어서 한 바퀴 도는 데 한 시간쯤 걸립니다.」에 감상을 한 문장 더해 고쳐 쓰고, 고친 문구가 읽는 사람에게 어떤 마음이 들게 하는지 쓰세요.","answer_guide":{"answer":"예: 「성벽은 걸어서 한 바퀴 도는 데 한 시간쯤 걸립니다. 성벽 위에서 내려다보는 초가지붕들은 한 시간이 짧게 느껴질 만큼 정겹습니다.」 걸리는 시간만 알 때보다 성벽 위를 걸어 보고 싶은 마음이 들게 한다.","scoring_points":["정보를 살려 고쳐 썼는가","감상을 한 문장 더했는가","읽는 사람의 마음을 썼는가"]},"explanation":["정보는 그대로 둬요.","내가 느낀 것을 보태요.","가 보고 싶어지게 써요."],"asset":{"type":"passage","lines":["㉮ 해 질 무렵 돌담길은 걸음을 늦추게 합니다.","㉯ 성벽은 걸어서 한 바퀴 도는 데 한 시간쯤 걸립니다.","㉰ 관람 시간은 오전 아홉 시부터입니다."],"title":"안내장에 넣으려고 쓴 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#9','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C44',4,'essay','teacher','가 본 곳 하나를 골라 안내장을 만든다면 어떤 형태로 만들지 정하고, 그 형태를 고른 까닭을 전할 내용과 이어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K5-1-u2-C44","difficulty":4,"kind":"essay","stem":"가 본 곳 하나를 골라 안내장을 만든다면 어떤 형태로 만들지 정하고, 그 형태를 고른 까닭을 전할 내용과 이어 쓰세요.","answer_guide":{"answer":"예: 우리 동네 전통 시장을 관광 지도로 만들겠다. 떡집 · 생선 가게 · 국수 골목을 도는 차례를 한눈에 보여 주고 싶기 때문이다. 가게마다 작은 글로 내가 느낀 맛과 소리를 적어 넣겠다.","scoring_points":["형태를 하나 정했는가","전할 내용과 형태를 이었는가","감상을 어떻게 담을지 썼는가"]},"explanation":["무엇을 전하고 싶나요?","내용에 맞는 형태를 골라요.","감상을 넣을 곳도 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_L12_challenge#10','kor',5,1,'u2','L12','g5_1_kor_u2_L12_challenge','lesson_challenge','K5-1-u2-C45',4,'essay','teacher','공공 누리집에서 가져온 사진을 안내장에 넣을 때 해야 할 일을 두 가지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C45","difficulty":4,"kind":"essay","stem":"공공 누리집에서 가져온 사진을 안내장에 넣을 때 해야 할 일을 두 가지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 첫째, 사진을 쓰기 전에 이용 조건을 확인한다. 둘째, 사진 옆에 어느 누리집에서 가져왔는지 출처를 적는다. 누리집 자료는 남이 만든 것이고 자료마다 쓸 수 있는 범위가 정해져 있기 때문이다.","scoring_points":["이용 조건 확인을 썼는가","출처 밝히기를 썼는가","남이 만든 자료라는 까닭을 썼는가"]},"explanation":["가져다 쓰기 전에 할 일.","쓴 다음에 할 일.","남이 만든 자료임을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#1','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C50',1,'mc','auto','바르게 쓴 낱말은 어느 것인가요?',ARRAY['K5-1-u2-X49']::text[],false,'{"seq":1,"concept":"K5-1-u2-C50","difficulty":1,"kind":"mc","stem":"바르게 쓴 낱말은 어느 것인가요?","options":[{"t":"깨끗이","correct":true},{"t":"깨끗히","mis":"K5-1-u2-X49"},{"t":"틈틈히","mis":"K5-1-u2-X49"},{"t":"곰곰히","mis":"K5-1-u2-X49"}],"explanation":["「이」로 끝나는 무리예요.","「이」로 끝나는 무리예요.","「깨끗이」가 바른 표기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#2','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C6',1,'mc','auto','솔미의 글 ㉰ 「호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.」는 언제의 일인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X07']::text[],false,'{"seq":2,"concept":"K5-1-u2-C6","difficulty":1,"kind":"mc","stem":"솔미의 글 ㉰ 「호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.」는 언제의 일인가요?","options":[{"t":"이미 지나간 일","correct":true},{"t":"지금 일어나고 있는 일","mis":"K5-1-u2-X05"},{"t":"앞으로 일어날 일","mis":"K5-1-u2-X05"},{"t":"날마다 되풀이되는 일","mis":"K5-1-u2-X07"}],"explanation":["-ㄴ-이 없어요.","-ㄹ 것이 없어요.","「나왔다」의 -았-이 지난 일을 알려 줘요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#3','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C15',1,'mc','auto','채온이네 반의 계획에서 「모레」는 무슨 요일인가요?',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"mc","stem":"채온이네 반의 계획에서 「모레」는 무슨 요일인가요?","options":[{"t":"수요일","correct":true},{"t":"화요일","mis":"K5-1-u2-X13"},{"t":"목요일","mis":"K5-1-u2-X13"},{"t":"금요일","mis":"K5-1-u2-X13"}],"explanation":["화요일은 내일이에요.","목요일은 글피예요.","오늘이 월요일이니 이틀 뒤 수요일이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#4','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C16',1,'mc','auto','「다음 주 월요일부터 닷새 동안」은 며칠 동안인가요?',ARRAY['K5-1-u2-X14']::text[],false,'{"seq":4,"concept":"K5-1-u2-C16","difficulty":1,"kind":"mc","stem":"「다음 주 월요일부터 닷새 동안」은 며칠 동안인가요?","options":[{"t":"오 일 동안","correct":true},{"t":"사 일 동안","mis":"K5-1-u2-X14"},{"t":"육 일 동안","mis":"K5-1-u2-X14"},{"t":"칠 일 동안","mis":"K5-1-u2-X14"}],"explanation":["사 일은 나흘이에요.","육 일은 엿새예요.","닷새는 오 일이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#5','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C29',1,'mc','auto','가비의 기행문에서 여정이 드러난 문장은 어느 것인가요?',ARRAY['K5-1-u2-X28']::text[],false,'{"seq":5,"concept":"K5-1-u2-C29","difficulty":1,"kind":"mc","stem":"가비의 기행문에서 여정이 드러난 문장은 어느 것인가요?","options":[{"t":"「다음으로 개울을 건너 떡방앗간에 들렀다.」","correct":true},{"t":"「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」","mis":"K5-1-u2-X28"},{"t":"「마을이 나를 배웅하는 것 같았다.」","mis":"K5-1-u2-X28"},{"t":"「둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.」","mis":"K5-1-u2-X28"}],"explanation":["본 모습이에요.","느낀 마음이에요.","어디로 갔는지가 드러나요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#6','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C37',1,'mc','auto','가비의 기행문 처음 부분에서 찾을 수 있는 내용은 어느 것인가요?',ARRAY['K5-1-u2-X36']::text[],false,'{"seq":6,"concept":"K5-1-u2-C37","difficulty":1,"kind":"mc","stem":"가비의 기행문 처음 부분에서 찾을 수 있는 내용은 어느 것인가요?","options":[{"t":"함께 간 사람과 교통편","correct":true},{"t":"다음에 다시 가면 하고 싶은 일","mis":"K5-1-u2-X36"},{"t":"방앗간에서 들은 설명","mis":"K5-1-u2-X36"},{"t":"돌아오는 길에 든 느낌","mis":"K5-1-u2-X36"}],"explanation":["끝부분의 내용이에요.","가운데의 내용이에요.","「우리 가족은 자동차를 타고」가 있어요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#7','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C34',1,'mc','auto','여정 · 견문 · 감상 가운데 감상만 있는 글은 무엇에 가까운가요?',ARRAY['K5-1-u2-X33','K5-1-u2-X43']::text[],false,'{"seq":7,"concept":"K5-1-u2-C34","difficulty":1,"kind":"mc","stem":"여정 · 견문 · 감상 가운데 감상만 있는 글은 무엇에 가까운가요?","options":[{"t":"일기","correct":true},{"t":"일정표","mis":"K5-1-u2-X33"},{"t":"기행문","mis":"K5-1-u2-X33"},{"t":"관광 지도","mis":"K5-1-u2-X43"}],"explanation":["일정표는 여정만 있어요.","셋이 함께 있어야 기행문이에요.","감상만 있으면 일기에 가까워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#8','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C43',1,'mc','auto','외갓집 마을 안내장에 넣기에 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u2-X42']::text[],false,'{"seq":8,"concept":"K5-1-u2-C43","difficulty":1,"kind":"mc","stem":"외갓집 마을 안내장에 넣기에 알맞지 않은 것은 어느 것인가요?","options":[{"t":"내 시험 점수","correct":true},{"t":"떡방앗간의 갓 찐 떡","mis":"K5-1-u2-X42"},{"t":"느티나무 쉼터","mis":"K5-1-u2-X42"},{"t":"저수지 둑길 산책","mis":"K5-1-u2-X42"}],"explanation":["먹을거리예요.","갈 만한 곳이에요.","여행지와 관계없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#9','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C12',2,'mc','auto','솔미의 글에서 때를 나타내는 말과 말끝이 어색하게 쓰인 문장은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X11']::text[],false,'{"seq":9,"concept":"K5-1-u2-C12","difficulty":2,"kind":"mc","stem":"솔미의 글에서 때를 나타내는 말과 말끝이 어색하게 쓰인 문장은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"K5-1-u2-X10"},{"t":"㉰","mis":"K5-1-u2-X10"},{"t":"㉲","mis":"K5-1-u2-X11"}],"explanation":["「봄에 … 있었다」는 어울려요.","지난 일을 지난 말끝으로 썼어요.","「지난 금요일」인데 「캔다」라서 어색해요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#10','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C29',2,'match','auto','가비의 기행문 ①의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C29","difficulty":2,"kind":"match","stem":"가비의 기행문 ①의 문장과 요소를 이으세요.","pairs":[{"l":"우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다","r":"여정"},{"l":"이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다","r":"견문"},{"l":"마을 사람들을 오래 지켜 온 할아버지 같았다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["어디로 갔나요?","들은 것인가요?","느낀 것인가요?"],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#11','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C51',2,'blank','auto','㉮의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":11,"concept":"K5-1-u2-C51","difficulty":2,"kind":"blank","stem":"㉮의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"조용히","correct":true},{"t":"조용이","mis":"K5-1-u2-X50"},{"t":"조용하게히","mis":"K5-1-u2-X50"},{"t":"조용니","mis":"K5-1-u2-X50"}],"explanation":["「히」로 끝나는 무리예요.","그런 낱말은 없어요.","「조용히」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#12','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C17',2,'mc','auto','채온이네 반이 학급 문고를 정리하는 날은 모두 며칠인가요?',ARRAY['K5-1-u2-X15','K5-1-u2-X16']::text[],false,'{"seq":12,"concept":"K5-1-u2-C17","difficulty":2,"kind":"mc","stem":"채온이네 반이 학급 문고를 정리하는 날은 모두 며칠인가요?","options":[{"t":"사흘","correct":true},{"t":"이틀","mis":"K5-1-u2-X15"},{"t":"나흘","mis":"K5-1-u2-X16"},{"t":"닷새","mis":"K5-1-u2-X15"}],"explanation":["수요일만 세지 마세요.","수 · 목 · 금을 세어 보세요.","수요일부터 금요일까지 사흘이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#13','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C13',2,'mc','auto','고치지 않아도 되는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X10']::text[],false,'{"seq":13,"concept":"K5-1-u2-C13","difficulty":2,"kind":"mc","stem":"고치지 않아도 되는 문장은 어느 것인가요?","options":[{"t":"「나 내일 외갓집에 간다.」","correct":true},{"t":"「나 어제 외갓집에 갈 것이다.」","mis":"K5-1-u2-X10"},{"t":"「나 아까 외갓집에 가겠다.」","mis":"K5-1-u2-X10"},{"t":"「나 그저께 외갓집에 갈 거야.」","mis":"K5-1-u2-X10"}],"explanation":["지난 날과 앞일의 말끝이 어색해요.","조금 전과 앞일의 말끝이 어색해요.","가까운 앞일을 「간다」로 말해도 어색하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#14','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C32',2,'mc','auto','「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」가 견문인 까닭은 무엇인가요?',ARRAY['K5-1-u2-X31','K5-1-u2-X30','K5-1-u2-X28']::text[],false,'{"seq":14,"concept":"K5-1-u2-C32","difficulty":2,"kind":"mc","stem":"「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」가 견문인 까닭은 무엇인가요?","options":[{"t":"그곳에 있던 사람이라면 누구나 똑같이 확인할 수 있기 때문이다","correct":true},{"t":"문장이 길기 때문이다","mis":"K5-1-u2-X31"},{"t":"가비의 마음이 드러나기 때문이다","mis":"K5-1-u2-X30"},{"t":"다닌 곳이 드러나기 때문이다","mis":"K5-1-u2-X28"}],"explanation":["길이로 가르지 않아요.","마음이 드러나면 감상이에요.","누구나 확인할 수 있으면 견문이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#15','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C35',2,'mc','auto','가비의 기행문은 어떤 경험을 글감으로 삼았나요?',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":15,"concept":"K5-1-u2-C35","difficulty":2,"kind":"mc","stem":"가비의 기행문은 어떤 경험을 글감으로 삼았나요?","options":[{"t":"명절에 간 친척 집 마을","correct":true},{"t":"먼 나라로 떠난 여행","mis":"K5-1-u2-X34"},{"t":"이름난 관광지","mis":"K5-1-u2-X34"},{"t":"상상 속의 여행","mis":"K5-1-u2-X34"}],"explanation":["멀리 가지 않았어요.","외갓집 마을이에요.","명절에 간 친척 집도 글감이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#16','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C46',2,'mc','auto','해솜이와 율하의 안내장 문구 가운데 감상이 드러난 것은 누구의 것인가요?',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":16,"concept":"K5-1-u2-C46","difficulty":2,"kind":"mc","stem":"해솜이와 율하의 안내장 문구 가운데 감상이 드러난 것은 누구의 것인가요?","options":[{"t":"율하","correct":true},{"t":"해솜","mis":"K5-1-u2-X45"},{"t":"둘 다","mis":"K5-1-u2-X45"},{"t":"둘 다 아니다","mis":"K5-1-u2-X45"}],"explanation":["해솜이는 위치와 그늘만 알렸어요.","한 사람만 느낌을 담았어요.","「하루가 천천히 흘러갑니다」에 느낌이 있어요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#17','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C49',3,'mc','auto','기행문을 쓸 때 시간 표현이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X48','K5-1-u2-X33']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"mc","stem":"기행문을 쓸 때 시간 표현이 중요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"기행문은 시간과 공간을 따라 움직이는 글이라 시간 표현이 흔들리면 다닌 길도 흐트러지기 때문이다","correct":true},{"t":"기행문에는 시간 표현을 쓰지 않기 때문이다","mis":"K5-1-u2-X48"},{"t":"시간 표현은 일기에만 쓰기 때문이다","mis":"K5-1-u2-X48"},{"t":"다닌 곳만 쓰면 시간은 필요 없기 때문이다","mis":"K5-1-u2-X33"}],"explanation":["기행문에도 시간 표현이 있어요.","두 소단원은 이어져 있어요.","시간 표현이 기행문의 뼈대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#18','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C27',3,'mc','auto','솔미가 초안을 스스로 확인할 때 가장 먼저 고쳐야 할 것은 어느 것인가요?',ARRAY['K5-1-u2-X26','K5-1-u2-X11']::text[],false,'{"seq":18,"concept":"K5-1-u2-C27","difficulty":3,"kind":"mc","stem":"솔미가 초안을 스스로 확인할 때 가장 먼저 고쳐야 할 것은 어느 것인가요?","options":[{"t":"때를 나타내는 말과 말끝이 어색한 ㉮와 ㉳","correct":true},{"t":"글씨를 더 크게 쓰기","mis":"K5-1-u2-X26"},{"t":"문장을 모두 짧게 줄이기","mis":"K5-1-u2-X26"},{"t":"㉲의 「지금」을 지우기","mis":"K5-1-u2-X11"}],"explanation":["글씨는 기준이 아니에요.","길이를 줄이는 것이 아니에요.","시간 표현이 어색한 문장을 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#19','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C38',3,'mc','auto','가비의 기행문 가운데 부분은 무엇을 따라 쓰였나요?',ARRAY['K5-1-u2-X37']::text[],false,'{"seq":19,"concept":"K5-1-u2-C38","difficulty":3,"kind":"mc","stem":"가비의 기행문 가운데 부분은 무엇을 따라 쓰였나요?","options":[{"t":"마을 안에서 다닌 곳의 차례","correct":true},{"t":"떡을 만드는 순서","mis":"K5-1-u2-X37"},{"t":"외할머니의 말씀 순서","mis":"K5-1-u2-X37"},{"t":"하루의 날씨 변화","mis":"K5-1-u2-X37"}],"explanation":["떡 이야기는 한 곳에서 나와요.","말씀은 견문의 하나예요.","느티나무 → 방앗간 → 둑길을 따라가요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#20','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C29',3,'match','auto','「모래벌판을 지나」의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":20,"concept":"K5-1-u2-C29","difficulty":3,"kind":"match","stem":"「모래벌판을 지나」의 문장과 요소를 이으세요.","pairs":[{"l":"언덕 너머 습지에 이르렀다","r":"여정"},{"l":"바람이 수천 년 동안 모래를 실어 나르며 만들어졌다고 한다","r":"견문"},{"l":"바람이 이렇게 오래 일한다는 사실이 놀라웠다","r":"감상"}],"mis":"K5-1-u2-X28","explanation":["다닌 곳이에요.","들은 설명이에요.","놀란 마음이에요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#21','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C20',3,'mc','auto','「금방」이 조금 전의 때를 가리키는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X18']::text[],false,'{"seq":21,"concept":"K5-1-u2-C20","difficulty":3,"kind":"mc","stem":"「금방」이 조금 전의 때를 가리키는 문장은 어느 것인가요?","options":[{"t":"「외할머니께서 금방 떡을 쪄 오셨다.」","correct":true},{"t":"「떡이 금방 다 쪄질 거야.」","mis":"K5-1-u2-X18"},{"t":"「소문이 금세 온 마을에 퍼졌다.」","mis":"K5-1-u2-X18"},{"t":"「금방 출발할 테니 기다려.」","mis":"K5-1-u2-X18"}],"explanation":["곧을 가리켜요.","빠르기를 말해요.","「쪄 오셨다」와 함께 조금 전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#22','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C41',3,'mc','auto','가비가 기행문을 쓰기 전에 했을 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X40','K5-1-u2-X33']::text[],false,'{"seq":22,"concept":"K5-1-u2-C41","difficulty":3,"kind":"mc","stem":"가비가 기행문을 쓰기 전에 했을 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"외갓집 마을에서 찍은 사진을 보며 기억에 남는 장면을 떠올리고 개요를 짠다","correct":true},{"t":"여러 해의 명절 이야기를 한 글에 모두 섞기로 한다","mis":"K5-1-u2-X40"},{"t":"개요 없이 떠오르는 대로 바로 쓴다","mis":"K5-1-u2-X40"},{"t":"다닌 곳 이름만 적고 쓰기를 끝낸다","mis":"K5-1-u2-X33"}],"explanation":["경험 하나를 골라요.","개요를 먼저 짜요.","장면을 떠올려 개요로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#23','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C23',4,'essay','teacher','솔미의 글에서 시간 표현이 어색한 문장 두 개를 찾아 바르게 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C23","difficulty":4,"kind":"essay","stem":"솔미의 글에서 시간 표현이 어색한 문장 두 개를 찾아 바르게 고쳐 쓰고, 왜 그렇게 고쳤는지 쓰세요.","answer_guide":{"answer":"예: ㉮ 「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」 — 「지난 금요일」은 이미 지난 때라 지난 일의 말끝으로 고쳤다. ㉳ 「다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹을 것이다.」 — 「다음 주」는 앞으로의 때라 앞일의 말끝으로 고쳤다.","scoring_points":["어색한 두 문장을 찾았는가","때의 말에 맞게 말끝을 고쳤는가","고친 까닭을 썼는가"]},"explanation":["때를 나타내는 말부터 봐요.","말끝이 어울리는지 소리 내어 읽어요.","때에 맞게 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#24','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C38',4,'essay','teacher','가 본 곳 하나를 떠올려 기행문의 가운데 부분을 한 문단으로 쓰세요. 다닌 곳 · 보고 들은 것 · 느낀 것을 모두 넣고, 지난 일을 나타내는 말끝을 바르게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C38","difficulty":4,"kind":"essay","stem":"가 본 곳 하나를 떠올려 기행문의 가운데 부분을 한 문단으로 쓰세요. 다닌 곳 · 보고 들은 것 · 느낀 것을 모두 넣고, 지난 일을 나타내는 말끝을 바르게 쓰세요.","answer_guide":{"answer":"예: 다음으로 시장 안 국수 골목에 들어섰다. 커다란 솥에서 김이 모락모락 피어올랐고, 할머니께서 국수를 사십 년 동안 삶아 오셨다고 말씀하셨다. 한 그릇의 국수에 할머니의 긴 시간이 담겨 있는 것 같아 국물까지 남김없이 마셨다.","scoring_points":["다닌 곳을 밝혔는가","보고 들은 것을 썼는가","느낀 것을 넣고 지난 일의 말끝을 바르게 썼는가"]},"explanation":["다닌 곳 하나를 골라요.","본 것과 들은 것을 써요.","느낀 것으로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_a#25','kor',5,1,'u2','','g5_1_kor_u2_review_a','unit_review','K5-1-u2-C49',4,'essay','teacher','이 단원에서 배운 「시간 표현을 활용해 글 쓰기」와 「기행문 쓰기」가 서로 어떻게 이어지는지 쓰고, 가비의 기행문에서 시간 표현이 쓰인 곳을 예로 드세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C49","difficulty":4,"kind":"essay","stem":"이 단원에서 배운 「시간 표현을 활용해 글 쓰기」와 「기행문 쓰기」가 서로 어떻게 이어지는지 쓰고, 가비의 기행문에서 시간 표현이 쓰인 곳을 예로 드세요.","answer_guide":{"answer":"예: 기행문은 시간과 공간을 따라 움직이는 글이라, 시간 표현이 흔들리면 다닌 길도 흐트러진다. 그래서 시간 표현이 기행문의 뼈대를 세운다. 가비의 기행문에서는 「추석 연휴에」 · 「먼저」 · 「다음으로」 · 「마지막으로」 · 「돌아오는 길」과 지난 일의 말끝 「갔다 · 들렀다 · 걸었다」가 다닌 차례를 또렷하게 해 준다.","scoring_points":["두 공부가 이어지는 까닭을 썼는가","시간 표현이 뼈대라는 점을 썼는가","가비의 기행문에서 예를 들었는가"]},"explanation":["기행문은 움직이는 글이에요.","시간 표현이 하는 일을 떠올려요.","예를 찾아 써요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#1','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C51',1,'mc','auto','「히」로 끝나는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":1,"concept":"K5-1-u2-C51","difficulty":1,"kind":"mc","stem":"「히」로 끝나는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"조용히","correct":true},{"t":"솔직이","mis":"K5-1-u2-X50"},{"t":"분명이","mis":"K5-1-u2-X50"},{"t":"특별이","mis":"K5-1-u2-X50"}],"explanation":["「솔직히」로 써요.","「분명히」로 써요.","「조용히」가 바른 표기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#2','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C7',1,'mc','auto','솔미의 글에서 지금의 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05']::text[],false,'{"seq":2,"concept":"K5-1-u2-C7","difficulty":1,"kind":"mc","stem":"솔미의 글에서 지금의 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"㉲","correct":true},{"t":"㉯","mis":"K5-1-u2-X05"},{"t":"㉰","mis":"K5-1-u2-X05"},{"t":"㉱","mis":"K5-1-u2-X05"}],"explanation":["「뻗어 있었다」 — 지난 일이에요.","「나왔다」 — 지난 일이에요.","「지금 … 떠오른다」가 지금을 알려 줘요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#3','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C15',1,'mc','auto','오늘에서 사흘 전을 가리키는 말은 어느 것인가요?',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"mc","stem":"오늘에서 사흘 전을 가리키는 말은 어느 것인가요?","options":[{"t":"그끄저께","correct":true},{"t":"그저께","mis":"K5-1-u2-X13"},{"t":"글피","mis":"K5-1-u2-X13"},{"t":"어제","mis":"K5-1-u2-X13"}],"explanation":["그저께는 이틀 전이에요.","글피는 사흘 뒤예요.","그저께보다 하루 더 앞이 그끄저께예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#4','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C18',1,'mc','auto','방앗간 아주머니께서 떡을 찐다고 하신 「사흘 동안」은 며칠 동안인가요?',ARRAY['K5-1-u2-X16','K5-1-u2-X14']::text[],false,'{"seq":4,"concept":"K5-1-u2-C18","difficulty":1,"kind":"mc","stem":"방앗간 아주머니께서 떡을 찐다고 하신 「사흘 동안」은 며칠 동안인가요?","options":[{"t":"삼 일 동안","correct":true},{"t":"사 일 동안","mis":"K5-1-u2-X16"},{"t":"이 일 동안","mis":"K5-1-u2-X14"},{"t":"오 일 동안","mis":"K5-1-u2-X14"}],"explanation":["「사」 소리에 속지 마세요.","이 일은 이틀이에요.","사흘은 삼 일이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#5','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C30',1,'mc','auto','가비의 기행문에서 들은 것을 쓴 견문은 어느 것인가요?',ARRAY['K5-1-u2-X29','K5-1-u2-X30']::text[],false,'{"seq":5,"concept":"K5-1-u2-C30","difficulty":1,"kind":"mc","stem":"가비의 기행문에서 들은 것을 쓴 견문은 어느 것인가요?","options":[{"t":"「외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.」","correct":true},{"t":"「우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.」","mis":"K5-1-u2-X29"},{"t":"「마을 사람들을 오래 지켜 온 할아버지 같았다.」","mis":"K5-1-u2-X30"},{"t":"「아침부터 마음이 들떴다.」","mis":"K5-1-u2-X29"}],"explanation":["다닌 곳이에요.","느낀 마음이에요.","들은 설명도 견문이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#6','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C39',1,'mc','auto','가비의 기행문 끝에서 앞으로의 계획을 쓴 문장은 어느 것인가요?',ARRAY['K5-1-u2-X38','K5-1-u2-X36']::text[],false,'{"seq":6,"concept":"K5-1-u2-C39","difficulty":1,"kind":"mc","stem":"가비의 기행문 끝에서 앞으로의 계획을 쓴 문장은 어느 것인가요?","options":[{"t":"「설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다.」","correct":true},{"t":"「마지막으로 저수지 둑길을 걸었다.」","mis":"K5-1-u2-X38"},{"t":"「김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.」","mis":"K5-1-u2-X38"},{"t":"「추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.」","mis":"K5-1-u2-X36"}],"explanation":["다닌 곳이에요.","본 모습이에요.","「다시 가면 … 보고 싶다」가 계획이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#7','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C4',1,'mc','auto','다음 가운데 기행문은 어느 것인가요?',ARRAY['K5-1-u2-X04','K5-1-u2-X33']::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":1,"kind":"mc","stem":"다음 가운데 기행문은 어느 것인가요?","options":[{"t":"다닌 곳마다 본 것과 느낀 것을 함께 적은 글","correct":true},{"t":"다닌 곳의 시각만 적은 일정표","mis":"K5-1-u2-X04"},{"t":"여행에 쓴 돈을 적은 목록","mis":"K5-1-u2-X04"},{"t":"여행지 사진만 모은 묶음","mis":"K5-1-u2-X33"}],"explanation":["보고 느낀 것이 없어요.","목록일 뿐이에요.","여정 · 견문 · 감상이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#8','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C44',1,'mc','auto','한 장면과 짧은 글로 그곳의 인상을 전하는 안내장 형태는 어느 것인가요?',ARRAY['K5-1-u2-X43']::text[],false,'{"seq":8,"concept":"K5-1-u2-C44","difficulty":1,"kind":"mc","stem":"한 장면과 짧은 글로 그곳의 인상을 전하는 안내장 형태는 어느 것인가요?","options":[{"t":"그림엽서","correct":true},{"t":"소책자","mis":"K5-1-u2-X43"},{"t":"관광 지도","mis":"K5-1-u2-X43"},{"t":"광고지","mis":"K5-1-u2-X43"}],"explanation":["여러 쪽에 자세히 담아요.","위치와 차례를 보여요.","한 장면 · 짧은 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#9','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C23',2,'mc','auto','솔미의 글 ㉳를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-1-u2-X21','K5-1-u2-X10']::text[],false,'{"seq":9,"concept":"K5-1-u2-C23","difficulty":2,"kind":"mc","stem":"솔미의 글 ㉳를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹을 것이다.」","correct":true},{"t":"「지난주에는 캔 고구마를 쪄서 다 같이 나누어 먹을 것이다.」","mis":"K5-1-u2-X21"},{"t":"「다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었었다.」","mis":"K5-1-u2-X10"},{"t":"「다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹는다고 했었다.」","mis":"K5-1-u2-X10"}],"explanation":["때의 말을 바꾸면 뜻이 달라져요.","지난 일의 말끝이 그대로예요.","「다음 주」에 맞게 앞일의 말끝으로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#10','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C30',2,'match','auto','가비의 기행문 ②의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C30","difficulty":2,"kind":"match","stem":"가비의 기행문 ②의 문장과 요소를 이으세요.","pairs":[{"l":"마지막으로 저수지 둑길을 걸었다","r":"여정"},{"l":"둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다","r":"견문"},{"l":"마을이 나를 배웅하는 것 같았다","r":"감상"}],"mis":"K5-1-u2-X29","explanation":["다닌 곳이에요.","본 모습이에요.","마음이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#11','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C50',2,'blank','auto','㉯의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X49']::text[],false,'{"seq":11,"concept":"K5-1-u2-C50","difficulty":2,"kind":"blank","stem":"㉯의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"틈틈이","correct":true},{"t":"틈틈히","mis":"K5-1-u2-X49"},{"t":"틈틈희","mis":"K5-1-u2-X49"},{"t":"틈틈니","mis":"K5-1-u2-X49"}],"explanation":["「이」로 끝나는 무리예요.","그런 낱말은 없어요.","「틈틈이」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#12','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C21',2,'mc','auto','채온이네 반의 계획을 날짜 말과 날수 말로 바르게 줄인 것은 어느 것인가요?',ARRAY['K5-1-u2-X15','K5-1-u2-X19']::text[],false,'{"seq":12,"concept":"K5-1-u2-C21","difficulty":2,"kind":"mc","stem":"채온이네 반의 계획을 날짜 말과 날수 말로 바르게 줄인 것은 어느 것인가요?","options":[{"t":"「모레부터 사흘 동안 학급 문고를 정리한다.」","correct":true},{"t":"「모레 동안 학급 문고를 정리한다.」","mis":"K5-1-u2-X15"},{"t":"「사흘에 학급 문고를 정리한다.」","mis":"K5-1-u2-X15"},{"t":"「언젠가 학급 문고를 정리한다.」","mis":"K5-1-u2-X19"}],"explanation":["「모레」는 며칠 동안이 아니에요.","「사흘」은 어느 날이 아니에요.","시작하는 날과 며칠 동안을 함께 말했어요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#13','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C10',2,'ox','auto','「소는 풀을 먹는다.」의 「먹는다」는 바로 이 순간에만 먹고 있다는 뜻이에요.',ARRAY['K5-1-u2-X07']::text[],false,'{"seq":13,"concept":"K5-1-u2-C10","difficulty":2,"kind":"ox","stem":"「소는 풀을 먹는다.」의 「먹는다」는 바로 이 순간에만 먹고 있다는 뜻이에요.","answer":"X","reason_options":[{"t":"-는-은 늘 되풀이되는 일에도 쓰이기 때문에","correct":true},{"t":"-는-은 언제나 지금 이 순간만 나타내기 때문에","mis":"K5-1-u2-X07"}],"mis":"K5-1-u2-X07","explanation":["-는-이 늘 지금만은 아니에요.","소는 늘 풀을 먹어요.","되풀이되는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#14','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C32',2,'ox','auto','「굵은 줄기가 할아버지 같았다」는 가비와 함께 있던 사람이라면 누구나 똑같이 느낄 수 있으니 견문이에요.',ARRAY['K5-1-u2-X31']::text[],false,'{"seq":14,"concept":"K5-1-u2-C32","difficulty":2,"kind":"ox","stem":"「굵은 줄기가 할아버지 같았다」는 가비와 함께 있던 사람이라면 누구나 똑같이 느낄 수 있으니 견문이에요.","answer":"X","reason_options":[{"t":"같은 나무를 보아도 사람마다 다르게 느낄 수 있는 마음이므로 감상이기 때문에","correct":true},{"t":"나무를 직접 보았으니 견문이기 때문에","mis":"K5-1-u2-X31"}],"mis":"K5-1-u2-X31","explanation":["본 것과 느낀 것은 달라요.","사람마다 다를 수 있어요.","마음속에서 일어난 감상이에요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#15','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C35',2,'ox','auto','가비처럼 명절에 외갓집에 다녀온 경험은 여행이 아니라서 기행문으로 쓸 수 없어요.',ARRAY['K5-1-u2-X34']::text[],false,'{"seq":15,"concept":"K5-1-u2-C35","difficulty":2,"kind":"ox","stem":"가비처럼 명절에 외갓집에 다녀온 경험은 여행이 아니라서 기행문으로 쓸 수 없어요.","answer":"X","reason_options":[{"t":"다닌 곳이 있고 보고 느낀 것이 있으면 가까운 곳이나 친척 집도 기행문의 글감이기 때문에","correct":true},{"t":"기행문은 이름난 관광지에 다녀와야만 쓸 수 있기 때문에","mis":"K5-1-u2-X34"}],"mis":"K5-1-u2-X34","explanation":["멀리 가야 하는 것이 아니에요.","다닌 곳 · 본 것 · 느낀 것이 있어요.","친척 집도 글감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#16','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C46',2,'ox','auto','해솜이의 문구처럼 사실만 적어도 읽는 사람이 꼭 가 보고 싶어져요.',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":16,"concept":"K5-1-u2-C46","difficulty":2,"kind":"ox","stem":"해솜이의 문구처럼 사실만 적어도 읽는 사람이 꼭 가 보고 싶어져요.","answer":"X","reason_options":[{"t":"정보만 있으면 안내판이 되고 느낌이 있어야 가 보고 싶어지기 때문에","correct":true},{"t":"사실이 많을수록 마음이 움직이기 때문에","mis":"K5-1-u2-X45"}],"mis":"K5-1-u2-X45","explanation":["정보도 필요해요.","그것만으로는 마음이 덜 움직여요.","느낌을 한 문장 더해요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#17','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C49',3,'ox','auto','시간 표현을 활용해 글 쓰기와 기행문 쓰기는 서로 관계없는 공부예요.',ARRAY['K5-1-u2-X48']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"ox","stem":"시간 표현을 활용해 글 쓰기와 기행문 쓰기는 서로 관계없는 공부예요.","answer":"X","reason_options":[{"t":"기행문은 시간과 공간을 따라 움직여 시간 표현이 뼈대를 세우기 때문에","correct":true},{"t":"기행문은 시간과 상관없이 느낌만 쓰는 글이기 때문에","mis":"K5-1-u2-X48"}],"mis":"K5-1-u2-X48","explanation":["두 소단원은 이어져 있어요.","느낌만 쓰지 않아요.","시간 표현이 기행문을 받쳐 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#18','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C25',3,'mc','auto','솔미의 글에 처음 부분을 더한다면 들어갈 내용으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X23']::text[],false,'{"seq":18,"concept":"K5-1-u2-C25","difficulty":3,"kind":"mc","stem":"솔미의 글에 처음 부분을 더한다면 들어갈 내용으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"고구마를 캐게 된 까닭이나 그날의 상황","correct":true},{"t":"다음에 또 하고 싶은 다짐","mis":"K5-1-u2-X23"},{"t":"고구마를 캐며 있었던 일","mis":"K5-1-u2-X23"},{"t":"고구마를 먹은 뒤의 전체 느낌","mis":"K5-1-u2-X23"}],"explanation":["끝에 들어가요.","가운데에 들어가요.","처음에는 상황이나 까닭이 들어가요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#19','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C33',3,'mc','auto','가비의 기행문에서 여정 · 견문 · 감상이 한 대목 안에 함께 어우러진 곳은 어디인가요?',ARRAY['K5-1-u2-X32']::text[],false,'{"seq":19,"concept":"K5-1-u2-C33","difficulty":3,"kind":"mc","stem":"가비의 기행문에서 여정 · 견문 · 감상이 한 대목 안에 함께 어우러진 곳은 어디인가요?","options":[{"t":"느티나무 대목","correct":true},{"t":"기행문 맨 첫 문장","mis":"K5-1-u2-X32"},{"t":"설에 다시 가고 싶다는 문장","mis":"K5-1-u2-X32"},{"t":"기행문에는 어우러진 대목이 없다","mis":"K5-1-u2-X32"}],"explanation":["첫 문장은 여정만 있어요.","끝의 바람이에요.","갔다 → 말씀하셨다 → 할아버지 같았다가 이어져요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#20','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C31',3,'mc','auto','「발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다.」가 감상인 까닭은 무엇인가요?',ARRAY['K5-1-u2-X30','K5-1-u2-X28','K5-1-u2-X31']::text[],false,'{"seq":20,"concept":"K5-1-u2-C31","difficulty":3,"kind":"mc","stem":"「발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다.」가 감상인 까닭은 무엇인가요?","options":[{"t":"모래를 보고 글쓴이가 마음속으로 느낀 것이라 사람마다 다를 수 있기 때문이다","correct":true},{"t":"신발 속에 모래가 있었다는 사실이기 때문이다","mis":"K5-1-u2-X30"},{"t":"다닌 곳이 드러나기 때문이다","mis":"K5-1-u2-X28"},{"t":"문장에 꾸미는 말이 많기 때문이다","mis":"K5-1-u2-X31"}],"explanation":["모래가 있었던 것은 사실이지만 문장의 중심은 마음이에요.","다닌 곳이 아니에요.","꾸미는 말로 가르지 않아요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#21','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C14',3,'mc','auto','「올해」를 앞으로의 일에 쓴 문장은 어느 것인가요?',ARRAY['K5-1-u2-X12']::text[],false,'{"seq":21,"concept":"K5-1-u2-C14","difficulty":3,"kind":"mc","stem":"「올해」를 앞으로의 일에 쓴 문장은 어느 것인가요?","options":[{"t":"「올해 안에 외갓집에 한 번 더 갈 것이다.」","correct":true},{"t":"「올해 봄에 외갓집에 갔다.」","mis":"K5-1-u2-X12"},{"t":"「올해는 벼가 잘 익는다.」","mis":"K5-1-u2-X12"},{"t":"「올해 설에 떡을 빚었다.」","mis":"K5-1-u2-X12"}],"explanation":["지난 일이에요.","지금의 일이에요.","「올해」는 세 때에 두루 쓰여요. 말끝을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#22','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C42',3,'mc','auto','가비가 쓰기 과정을 점검하며 적은 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X41','K5-1-u2-X26','K5-1-u2-X27']::text[],false,'{"seq":22,"concept":"K5-1-u2-C42","difficulty":3,"kind":"mc","stem":"가비가 쓰기 과정을 점검하며 적은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「방앗간 대목에 감상이 적어서, 다음에는 그곳에서 느낀 마음을 더 써야겠다.」","correct":true},{"t":"「다 썼으니 돌아볼 것이 없다.」","mis":"K5-1-u2-X41"},{"t":"「글씨가 예쁘지 않았다.」","mis":"K5-1-u2-X26"},{"t":"「글이 길어서 잘 썼다.」","mis":"K5-1-u2-X27"}],"explanation":["돌아보는 것도 쓰기예요.","글씨는 기준이 아니에요.","아쉬운 점과 고칠 방법을 적었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#23','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C33',4,'essay','teacher','가비의 기행문 ②에서 한 곳을 골라 여정 · 견문 · 감상이 한 문단 안에서 어떻게 이어지는지 문장을 들어 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C33","difficulty":4,"kind":"essay","stem":"가비의 기행문 ②에서 한 곳을 골라 여정 · 견문 · 감상이 한 문단 안에서 어떻게 이어지는지 문장을 들어 설명하세요.","answer_guide":{"answer":"예: 방앗간 대목 — 「다음으로 개울을 건너 떡방앗간에 들렀다」(여정)에서 방앗간에 간 것을 밝히고, 「시루에서 갓 찐 떡을 꺼내고 있었다」 · 「사흘 동안은 새벽부터 떡을 찐다고 하셨다」(견문)로 본 것과 들은 것을 쓴 뒤, 끝에서 「설에 다시 가면 떡을 빚어 보고 싶다」(감상)로 마음을 이었다. 셋이 따로 떨어지지 않고 그곳을 중심으로 이어진다.","scoring_points":["한 곳을 골랐는가","여정 · 견문 · 감상 문장을 찾았는가","어떻게 이어지는지 설명했는가"]},"explanation":["다닌 곳 하나를 골라요.","세 요소의 문장을 찾아요.","이어지는 모습을 설명해요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#24','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C39',4,'essay','teacher','가비의 기행문 끝부분에 전체적인 느낌이나 배운 것을 한두 문장 더 써 보고, 끝부분에 그런 내용이 들어가는 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C39","difficulty":4,"kind":"essay","stem":"가비의 기행문 끝부분에 전체적인 느낌이나 배운 것을 한두 문장 더 써 보고, 끝부분에 그런 내용이 들어가는 까닭을 쓰세요.","answer_guide":{"answer":"예: 「외갓집 마을은 작지만, 오래된 나무와 새벽부터 떡을 찌는 방앗간처럼 저마다 제 몫을 하는 것들로 가득했다. 이번 여행으로 외할머니가 사는 마을을 조금 더 알게 되었다.」 끝부분은 여행을 돌아보며 전체적인 느낌과 배운 것, 앞으로의 계획을 정리하는 곳이기 때문이다.","scoring_points":["전체적인 느낌이나 배운 것을 썼는가","가비의 기행문 내용과 이어지는가","끝부분의 몫으로 까닭을 썼는가"]},"explanation":["여행 전체를 돌아봐요.","배운 것을 떠올려요.","끝부분의 몫을 써요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_b#25','kor',5,1,'u2','','g5_1_kor_u2_review_b','unit_review','K5-1-u2-C32',4,'essay','teacher','견문과 감상을 가르는 물음이 무엇인지 쓰고, 「모래벌판을 지나」에서 견문과 감상을 하나씩 찾아 그 물음으로 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C32","difficulty":4,"kind":"essay","stem":"견문과 감상을 가르는 물음이 무엇인지 쓰고, 「모래벌판을 지나」에서 견문과 감상을 하나씩 찾아 그 물음으로 설명하세요.","answer_guide":{"answer":"예: 그곳에 함께 있던 다른 사람도 똑같이 확인할 수 있는지 묻는다. 「마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다」는 누구나 똑같이 볼 수 있으니 견문이다. 「바람이 이렇게 오래 일한다는 사실이 놀라웠다」는 같은 것을 보아도 사람마다 다르게 느낄 수 있으니 감상이다.","scoring_points":["가르는 물음을 썼는가","견문과 감상을 하나씩 찾았는가","물음으로 설명했는가"]},"explanation":["누구나 확인할 수 있나요?","사람마다 다를 수 있나요?","하나씩 찾아 설명해요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#1','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C50',1,'mc','auto','「이」로 끝나는 낱말로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":1,"concept":"K5-1-u2-C50","difficulty":1,"kind":"mc","stem":"「이」로 끝나는 낱말로만 묶은 것은 어느 것인가요?","options":[{"t":"틈틈이 · 곰곰이 · 가까이","correct":true},{"t":"틈틈이 · 조용히 · 가까이","mis":"K5-1-u2-X50"},{"t":"다행히 · 곰곰이 · 특별히","mis":"K5-1-u2-X50"},{"t":"도저히 · 솔직히 · 분명히","mis":"K5-1-u2-X50"}],"explanation":["「조용히」는 「히」예요.","「다행히」 · 「특별히」는 「히」예요.","모두 「이」로 끝나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#2','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C8',1,'mc','auto','앞으로의 일을 나타낸 문장은 어느 것인가요?',ARRAY['K5-1-u2-X05','K5-1-u2-X09']::text[],false,'{"seq":2,"concept":"K5-1-u2-C8","difficulty":1,"kind":"mc","stem":"앞으로의 일을 나타낸 문장은 어느 것인가요?","options":[{"t":"「다음 주에 고구마를 쪄서 나누어 먹을 것이다.」","correct":true},{"t":"「어제 고구마를 쪄서 나누어 먹었다.」","mis":"K5-1-u2-X05"},{"t":"「지금 고구마를 쪄서 나누어 먹는다.」","mis":"K5-1-u2-X05"},{"t":"「아까 고구마를 쪄서 나누어 먹었다.」","mis":"K5-1-u2-X09"}],"explanation":["지난 일이에요.","지금의 일이에요.","-ㄹ 것이 앞으로를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#3','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C15',1,'match','auto','오늘을 가운데에 두고 날짜를 가리키는 말을 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"match","stem":"오늘을 가운데에 두고 날짜를 가리키는 말을 이으세요.","pairs":[{"l":"어제","r":"하루 전"},{"l":"모레","r":"이틀 뒤"},{"l":"글피","r":"사흘 뒤"}],"mis":"K5-1-u2-X13","explanation":["오늘에서 세어요.","앞뒤를 나누어요.","어제 · 모레 · 글피를 차례로 세어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#4','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C16',1,'mc','auto','칠 일을 세는 우리말은 어느 것인가요?',ARRAY['K5-1-u2-X14']::text[],false,'{"seq":4,"concept":"K5-1-u2-C16","difficulty":1,"kind":"mc","stem":"칠 일을 세는 우리말은 어느 것인가요?","options":[{"t":"이레","correct":true},{"t":"엿새","mis":"K5-1-u2-X14"},{"t":"여드레","mis":"K5-1-u2-X14"},{"t":"열흘","mis":"K5-1-u2-X14"}],"explanation":["엿새는 육 일이에요.","여드레는 팔 일이에요.","칠 일은 이레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#5','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C31',1,'mc','auto','가비의 기행문에서 감상에 해당하는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30']::text[],false,'{"seq":5,"concept":"K5-1-u2-C31","difficulty":1,"kind":"mc","stem":"가비의 기행문에서 감상에 해당하는 문장은 어느 것인가요?","options":[{"t":"「굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다.」","correct":true},{"t":"「우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.」","mis":"K5-1-u2-X28"},{"t":"「외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.」","mis":"K5-1-u2-X30"},{"t":"「추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.」","mis":"K5-1-u2-X28"}],"explanation":["다닌 곳이에요.","들은 것이에요.","「~같았다」에 마음이 드러나요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#6','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C37',1,'mc','auto','기행문의 처음 부분에 쓰기에 가장 알맞은 문장은 어느 것인가요?',ARRAY['K5-1-u2-X36','K5-1-u2-X38','K5-1-u2-X37']::text[],false,'{"seq":6,"concept":"K5-1-u2-C37","difficulty":1,"kind":"mc","stem":"기행문의 처음 부분에 쓰기에 가장 알맞은 문장은 어느 것인가요?","options":[{"t":"「외할머니께서 마을을 구경시켜 주신다고 해서 아침부터 마음이 들떴다.」","correct":true},{"t":"「다음에는 떡을 빚어 보고 싶다.」","mis":"K5-1-u2-X36"},{"t":"「마을이 나를 배웅하는 것 같았다.」","mis":"K5-1-u2-X38"},{"t":"「둑 아래로 벼가 펼쳐져 있었다.」","mis":"K5-1-u2-X37"}],"explanation":["끝에 어울려요.","끝에 어울려요.","떠나기 전의 기대와 기분이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#7','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C34',1,'ox','auto','다닌 곳만 차례대로 적은 글은 일정표에 가까워요.',ARRAY['K5-1-u2-X33']::text[],false,'{"seq":7,"concept":"K5-1-u2-C34","difficulty":1,"kind":"ox","stem":"다닌 곳만 차례대로 적은 글은 일정표에 가까워요.","answer":"O","reason_options":[{"t":"여정만 있고 견문과 감상이 없기 때문에","correct":true},{"t":"다닌 곳이 많을수록 기행문이 되기 때문에","mis":"K5-1-u2-X33"}],"mis":"K5-1-u2-X33","explanation":["맞는 말이에요.","곳의 수로 정해지지 않아요.","여정만 있으면 일정표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#8','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C45',1,'mc','auto','안내장에 공공 누리집의 사진을 넣을 때 사진 옆에 꼭 적어야 하는 것은 어느 것인가요?',ARRAY['K5-1-u2-X44']::text[],false,'{"seq":8,"concept":"K5-1-u2-C45","difficulty":1,"kind":"mc","stem":"안내장에 공공 누리집의 사진을 넣을 때 사진 옆에 꼭 적어야 하는 것은 어느 것인가요?","options":[{"t":"어디에서 가져왔는지 밝힌 출처","correct":true},{"t":"사진을 찍은 날의 내 기분","mis":"K5-1-u2-X44"},{"t":"내 이름만","mis":"K5-1-u2-X44"},{"t":"아무것도 적지 않는다","mis":"K5-1-u2-X44"}],"explanation":["출처가 아니에요.","내가 만든 사진이 아니에요.","가져온 곳을 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#9','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C12',2,'mc','auto','솔미의 글 ㉮를 바르게 고친 것은 어느 것인가요?',ARRAY['K5-1-u2-X10','K5-1-u2-X21']::text[],false,'{"seq":9,"concept":"K5-1-u2-C12","difficulty":2,"kind":"mc","stem":"솔미의 글 ㉮를 바르게 고친 것은 어느 것인가요?","options":[{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」","correct":true},{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캘 것이다.」","mis":"K5-1-u2-X10"},{"t":"「다음 금요일에 우리 반은 학교 텃밭에서 고구마를 캤다.」","mis":"K5-1-u2-X21"},{"t":"「지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캐겠다.」","mis":"K5-1-u2-X10"}],"explanation":["지난 일인데 앞일의 말끝이에요.","때의 말과 말끝이 어긋나요.","「지난 금요일」에 맞게 「캤다」로 고쳐요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#10','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C31',2,'match','auto','방앗간 대목의 문장과 요소를 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K5-1-u2-C31","difficulty":2,"kind":"match","stem":"방앗간 대목의 문장과 요소를 이으세요.","pairs":[{"l":"개울을 건너 떡방앗간에 들렀다","r":"여정"},{"l":"명절 전 사흘 동안은 새벽부터 떡을 찐다고 하셨다","r":"견문"},{"l":"설에 다시 가면 떡을 빚어 보고 싶다","r":"감상"}],"mis":"K5-1-u2-X30","explanation":["다닌 곳이에요.","들은 설명이에요.","바람과 마음이에요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#11','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C50',2,'blank','auto','㉰의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X49']::text[],false,'{"seq":11,"concept":"K5-1-u2-C50","difficulty":2,"kind":"blank","stem":"㉰의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"샅샅이","correct":true},{"t":"샅샅히","mis":"K5-1-u2-X49"},{"t":"삳삳이","mis":"K5-1-u2-X49"},{"t":"샅샅희","mis":"K5-1-u2-X49"}],"explanation":["「이」로 끝나는 무리예요.","받침을 확인해요.","「샅샅이」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#12','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C17',2,'ox','auto','채온이네 계획의 「닷새 동안」은 행사를 여는 날짜를 가리키는 말이에요.',ARRAY['K5-1-u2-X15']::text[],false,'{"seq":12,"concept":"K5-1-u2-C17","difficulty":2,"kind":"ox","stem":"채온이네 계획의 「닷새 동안」은 행사를 여는 날짜를 가리키는 말이에요.","answer":"X","reason_options":[{"t":"「닷새」는 어느 날인지가 아니라 며칠 동안인지를 세는 말이기 때문에","correct":true},{"t":"「닷새」는 다섯째 날을 가리키는 날짜 말이기 때문에","mis":"K5-1-u2-X15"}],"mis":"K5-1-u2-X15","explanation":["날짜는 「월요일부터」예요.","「닷새」는 날의 개수예요.","며칠 동안인지를 세는 말이에요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#13','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C10',2,'mc','auto','-는- / -ㄴ-이 없어도 지금을 나타내는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X08']::text[],false,'{"seq":13,"concept":"K5-1-u2-C10","difficulty":2,"kind":"mc","stem":"-는- / -ㄴ-이 없어도 지금을 나타내는 문장은 어느 것인가요?","options":[{"t":"「외갓집 마을은 참 조용하다.」","correct":true},{"t":"「외갓집 마을은 참 조용했다.」","mis":"K5-1-u2-X08"},{"t":"「외갓집 마을은 참 조용하겠다.」","mis":"K5-1-u2-X08"},{"t":"「외갓집 마을은 참 조용할 것이다.」","mis":"K5-1-u2-X08"}],"explanation":["-었-이 있어 지난 일이에요.","-겠-이 있어요.","말끝 없이도 지금을 나타내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#14','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C30',2,'mc','auto','견문으로만 묶은 것은 어느 것인가요?',ARRAY['K5-1-u2-X30','K5-1-u2-X28']::text[],false,'{"seq":14,"concept":"K5-1-u2-C30","difficulty":2,"kind":"mc","stem":"견문으로만 묶은 것은 어느 것인가요?","options":[{"t":"「시루에서 떡을 꺼내고 있었다」 · 「새벽부터 떡을 찐다고 하셨다」","correct":true},{"t":"「시루에서 떡을 꺼내고 있었다」 · 「마을이 배웅하는 것 같았다」","mis":"K5-1-u2-X30"},{"t":"「개울을 건너 떡방앗간에 들렀다」 · 「새벽부터 떡을 찐다고 하셨다」","mis":"K5-1-u2-X28"},{"t":"「할아버지 같았다」 · 「마을이 배웅하는 것 같았다」","mis":"K5-1-u2-X30"}],"explanation":["감상이 섞였어요.","여정이 섞였어요.","본 것과 들은 것만 골랐어요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#15','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C36',2,'mc','auto','가비의 기행문에서 가 보지 않은 사람에게 정보를 전하는 몫을 하는 문장은 어느 것인가요?',ARRAY['K5-1-u2-X35']::text[],false,'{"seq":15,"concept":"K5-1-u2-C36","difficulty":2,"kind":"mc","stem":"가비의 기행문에서 가 보지 않은 사람에게 정보를 전하는 몫을 하는 문장은 어느 것인가요?","options":[{"t":"「이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.」","correct":true},{"t":"「마을이 나를 배웅하는 것 같았다.」","mis":"K5-1-u2-X35"},{"t":"「아침부터 마음이 들떴다.」","mis":"K5-1-u2-X35"},{"t":"「할아버지 같았다.」","mis":"K5-1-u2-X35"}],"explanation":["마음을 담은 몫이에요.","마음을 담은 몫이에요.","그곳에 대해 알려 주는 정보예요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#16','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C46',2,'mc','auto','해솜이의 문구에 더할 감상으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X45']::text[],false,'{"seq":16,"concept":"K5-1-u2-C46","difficulty":2,"kind":"mc","stem":"해솜이의 문구에 더할 감상으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그늘 아래 앉으면 마을을 오래 지켜 온 나무의 품에 안긴 것 같습니다.」","correct":true},{"t":"「나무의 높이는 아주 높습니다.」","mis":"K5-1-u2-X45"},{"t":"「쉼터는 마을 입구에 있습니다.」","mis":"K5-1-u2-X45"},{"t":"「쉼터는 아침부터 엽니다.」","mis":"K5-1-u2-X45"}],"explanation":["사실 정보예요.","이미 있는 정보예요.","내가 느낀 것을 보탰어요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#17','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C49',3,'mc','auto','「먼저 동문으로 들어갔다. 해 질 무렵 남문을 나섰다.」에서 시간 표현이 하는 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X30','K5-1-u2-X48']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"mc","stem":"「먼저 동문으로 들어갔다. 해 질 무렵 남문을 나섰다.」에서 시간 표현이 하는 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다닌 차례와 시간의 흐름을 함께 알려 준다","correct":true},{"t":"글쓴이의 느낌을 알려 준다","mis":"K5-1-u2-X30"},{"t":"보고 들은 사실을 알려 준다","mis":"K5-1-u2-X48"},{"t":"아무 일도 하지 않는다","mis":"K5-1-u2-X48"}],"explanation":["느낌이 아니에요.","본 것이 아니에요.","「먼저 · 해 질 무렵」이 흐름을 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#18','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C26',3,'mc','auto','솔미의 글 제목을 있었던 일이 더 잘 드러나게 고친 것은 어느 것인가요?',ARRAY['K5-1-u2-X25']::text[],false,'{"seq":18,"concept":"K5-1-u2-C26","difficulty":3,"kind":"mc","stem":"솔미의 글 제목을 있었던 일이 더 잘 드러나게 고친 것은 어느 것인가요?","options":[{"t":"「줄줄이 딸려 나온 붉은 고구마」","correct":true},{"t":"「금요일」","mis":"K5-1-u2-X25"},{"t":"「우리 반」","mis":"K5-1-u2-X25"},{"t":"「재미있었다」","mis":"K5-1-u2-X25"}],"explanation":["때만 있어요.","누구만 있어요.","무슨 일이 있었는지 드러나요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#19','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C40',3,'mc','auto','가비의 기행문 제목을 여행지와 느낌이 함께 드러나게 바꾼다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X39']::text[],false,'{"seq":19,"concept":"K5-1-u2-C40","difficulty":3,"kind":"mc","stem":"가비의 기행문 제목을 여행지와 느낌이 함께 드러나게 바꾼다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「나를 배웅해 준 외갓집 마을」","correct":true},{"t":"「외갓집」","mis":"K5-1-u2-X39"},{"t":"「즐거운 추석」","mis":"K5-1-u2-X39"},{"t":"「추석 연휴」","mis":"K5-1-u2-X39"}],"explanation":["여행지만 있어요.","느낌만 있어요.","여행지와 느낌이 함께 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#20','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C39',3,'mc','auto','「모래벌판을 지나」의 끝에서 앞으로의 계획을 쓴 부분은 어느 것인가요?',ARRAY['K5-1-u2-X38','K5-1-u2-X36']::text[],false,'{"seq":20,"concept":"K5-1-u2-C39","difficulty":3,"kind":"mc","stem":"「모래벌판을 지나」의 끝에서 앞으로의 계획을 쓴 부분은 어느 것인가요?","options":[{"t":"「다음에는 바람이 센 계절에 다시 와 보고 싶다」","correct":true},{"t":"「돌아오는 길에 신발 속 모래를 털어 냈다」","mis":"K5-1-u2-X38"},{"t":"「다음으로 언덕 너머 습지에 이르렀다」","mis":"K5-1-u2-X38"},{"t":"「바닷가 모래 언덕이 궁금했기 때문이다」","mis":"K5-1-u2-X36"}],"explanation":["돌아오는 길의 일이에요.","가운데의 여정이에요.","「다음에는 … 싶다」가 계획이에요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#21','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C14',3,'ox','auto','「이듬해」는 지난 일을 말할 때만 쓰는 말이에요.',ARRAY['K5-1-u2-X12']::text[],false,'{"seq":21,"concept":"K5-1-u2-C14","difficulty":3,"kind":"ox","stem":"「이듬해」는 지난 일을 말할 때만 쓰는 말이에요.","answer":"X","reason_options":[{"t":"「이듬해」는 어떤 해의 바로 다음 해라서 지난 일과 앞으로의 일에 모두 쓰이기 때문에","correct":true},{"t":"「이듬해」는 언제나 작년을 뜻하기 때문에","mis":"K5-1-u2-X12"}],"mis":"K5-1-u2-X12","explanation":["기준이 되는 해에 따라 달라요.","언제나 작년은 아니에요.","과거와 미래 양쪽에 쓰여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#22','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C42',3,'error','auto','쓰기 과정을 점검하는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X32','K5-1-u2-X41']::text[],false,'{"seq":22,"concept":"K5-1-u2-C42","difficulty":3,"kind":"error","stem":"쓰기 과정을 점검하는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「여정 · 견문 · 감상을 한 문단씩 따로 썼다면 그대로 두는 게 좋아.」","correct":true,"mis_target":"K5-1-u2-X32"},{"t":"「계획하기 · 글쓰기 · 수정하기 가운데 아쉬운 단계를 짚어.」","mis":"K5-1-u2-X41"},{"t":"「보완할 점과 수정할 방법을 함께 적어.」","mis":"K5-1-u2-X41"}],"explanation":["단계를 짚는 것은 맞아요.","방법을 적는 것도 맞아요.","따로 썼다면 다닌 곳마다 어우러지게 묶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#23','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C21',4,'essay','teacher','채온이네 반의 계획을 날짜 말과 날수 말을 넣어 친구에게 알리는 쪽지로 써 보세요. 어느 말이 날짜이고 어느 말이 날수인지 밝히세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C21","difficulty":4,"kind":"essay","stem":"채온이네 반의 계획을 날짜 말과 날수 말을 넣어 친구에게 알리는 쪽지로 써 보세요. 어느 말이 날짜이고 어느 말이 날수인지 밝히세요.","answer_guide":{"answer":"예: 「얘들아, 우리 반은 모레부터 사흘 동안 학급 문고를 정리하고, 다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 열어. 읽고 싶은 책을 한 권씩 챙겨 와!」 — 「모레」 · 「다음 주 월요일」은 날짜를 가리키는 말이고, 「사흘」 · 「닷새」는 날수를 세는 말이다.","scoring_points":["계획을 빠짐없이 담았는가","날짜 말과 날수 말을 바르게 썼는가","두 말을 구별해 밝혔는가"]},"explanation":["오늘은 월요일이에요.","시작하는 날과 며칠 동안을 나누어요.","쪽지 말투로 알려요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#24','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C35',4,'essay','teacher','「멀리 여행을 가 본 적이 없어서 기행문을 못 쓰겠다」는 친구에게, 가비의 기행문을 예로 들어 기행문의 글감을 찾는 방법을 알려 주세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C35","difficulty":4,"kind":"essay","stem":"「멀리 여행을 가 본 적이 없어서 기행문을 못 쓰겠다」는 친구에게, 가비의 기행문을 예로 들어 기행문의 글감을 찾는 방법을 알려 주세요.","answer_guide":{"answer":"예: 멀리 가지 않아도 기행문을 쓸 수 있어. 가비는 추석에 외갓집 마을을 한 바퀴 돈 일을 기행문으로 썼어. 너도 우리 동네 시장이나 명절에 간 친척 집, 현장 체험 학습처럼 다닌 곳이 있고 보고 느낀 것이 있는 경험을 떠올려 봐.","scoring_points":["멀리 가지 않아도 된다고 알려 주었는가","가비의 기행문을 예로 들었는가","가까운 글감을 두 가지 이상 들었는가"]},"explanation":["가비는 어디에 다녀왔나요?","가까운 곳을 떠올려요.","다닌 곳 · 본 것 · 느낀 것이 있으면 글감이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_c#25','kor',5,1,'u2','','g5_1_kor_u2_review_c','unit_review','K5-1-u2-C13',4,'essay','teacher','「시간을 나타내는 말과 말끝은 대개 어울린다」와 「어긋나 보여도 틀린 말이 아닌 때가 있다」를 함께 생각하여, 문장의 시간 표현을 고칠지 판단하는 방법을 예와 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C13","difficulty":4,"kind":"essay","stem":"「시간을 나타내는 말과 말끝은 대개 어울린다」와 「어긋나 보여도 틀린 말이 아닌 때가 있다」를 함께 생각하여, 문장의 시간 표현을 고칠지 판단하는 방법을 예와 함께 쓰세요.","answer_guide":{"answer":"예: 먼저 때를 나타내는 말과 말끝이 어울리는지 보고, 소리 내어 읽어 어색한지 판단한다. 「나는 아까 우유를 마실 것이다」는 읽어 보면 어색하므로 「마셨다」로 고친다. 그러나 「드디어 내일 소풍 간다」는 겉보기에 어긋나 보여도 어색하지 않으므로 고치지 않는다.","scoring_points":["어울림을 먼저 본다고 썼는가","소리 내어 읽어 판단하는 기준을 썼는가","고칠 예와 고치지 않을 예를 들었는가"]},"explanation":["두 말을 함께 봐요.","판단 기준을 떠올려요.","예를 하나씩 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#1','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C51',1,'mc','auto','밑줄 친 낱말을 바르게 쓴 문장은 어느 것인가요? (밑줄 낱말 — 「특별히」 · 「깨끗히」 · 「곰곰히」 · 「솔직이」)',ARRAY['K5-1-u2-X49','K5-1-u2-X50']::text[],false,'{"seq":1,"concept":"K5-1-u2-C51","difficulty":1,"kind":"mc","stem":"밑줄 친 낱말을 바르게 쓴 문장은 어느 것인가요? (밑줄 낱말 — 「특별히」 · 「깨끗히」 · 「곰곰히」 · 「솔직이」)","options":[{"t":"「오늘 저녁은 특별히 내가 좋아하는 음식을 먹기로 했다.」","correct":true},{"t":"「손을 깨끗히 씻었다.」","mis":"K5-1-u2-X49"},{"t":"「곰곰히 생각해 보았다.」","mis":"K5-1-u2-X49"},{"t":"「솔직이 말해 줘.」","mis":"K5-1-u2-X50"}],"explanation":["「깨끗이」로 써요.","「곰곰이」로 써요.","「특별히」가 바르게 쓰였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#2','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C9',1,'mc','auto','「캤다」에서 지난 일을 알려 주는 부분은 어느 것인가요?',ARRAY['K5-1-u2-X06']::text[],false,'{"seq":2,"concept":"K5-1-u2-C9","difficulty":1,"kind":"mc","stem":"「캤다」에서 지난 일을 알려 주는 부분은 어느 것인가요?","options":[{"t":"-았-","correct":true},{"t":"캐-","mis":"K5-1-u2-X06"},{"t":"-다","mis":"K5-1-u2-X06"},{"t":"캤-","mis":"K5-1-u2-X06"}],"explanation":["낱말의 뿌리예요.","끝맺는 부분이에요.","「캐-」에 「-았-」이 붙었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#3','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C15',1,'blank','auto','빈칸에 알맞은 말을 고르세요. 「오늘이 금요일이니 (　　)는 일요일이다.」',ARRAY['K5-1-u2-X13']::text[],false,'{"seq":3,"concept":"K5-1-u2-C15","difficulty":1,"kind":"blank","stem":"빈칸에 알맞은 말을 고르세요. 「오늘이 금요일이니 (　　)는 일요일이다.」","options":[{"t":"모레","correct":true},{"t":"그저께","mis":"K5-1-u2-X13"},{"t":"글피","mis":"K5-1-u2-X13"},{"t":"내일","mis":"K5-1-u2-X13"}],"explanation":["그저께는 수요일이에요.","글피는 월요일이에요.","금요일에서 이틀 뒤가 일요일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#4','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C19',1,'ox','auto','「사흘」을 「3흘」로 쓰는 것은 틀린 표기예요.',ARRAY['K5-1-u2-X17']::text[],false,'{"seq":4,"concept":"K5-1-u2-C19","difficulty":1,"kind":"ox","stem":"「사흘」을 「3흘」로 쓰는 것은 틀린 표기예요.","answer":"O","reason_options":[{"t":"사흘은 숫자에서 온 말이 아니라 본디부터 있던 우리말이기 때문에","correct":true},{"t":"「3흘」이 더 빨리 쓸 수 있는 바른 표기이기 때문에","mis":"K5-1-u2-X17"}],"mis":"K5-1-u2-X17","explanation":["맞는 말이에요.","빨리 쓴다고 바른 표기가 아니에요.","본디부터 있던 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#5','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C29',1,'mc','auto','가비가 외갓집 마을에서 다닌 곳의 차례로 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X37']::text[],false,'{"seq":5,"concept":"K5-1-u2-C29","difficulty":1,"kind":"mc","stem":"가비가 외갓집 마을에서 다닌 곳의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"느티나무 → 떡방앗간 → 저수지 둑길","correct":true},{"t":"떡방앗간 → 느티나무 → 저수지 둑길","mis":"K5-1-u2-X37"},{"t":"저수지 둑길 → 떡방앗간 → 느티나무","mis":"K5-1-u2-X37"},{"t":"느티나무 → 저수지 둑길 → 떡방앗간","mis":"K5-1-u2-X37"}],"explanation":["「먼저」 간 곳을 찾아요.","「마지막으로」 간 곳을 찾아요.","먼저 → 다음으로 → 마지막으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#6','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C39',1,'mc','auto','기행문의 끝부분에 들어가지 않는 내용은 어느 것인가요?',ARRAY['K5-1-u2-X38']::text[],false,'{"seq":6,"concept":"K5-1-u2-C39","difficulty":1,"kind":"mc","stem":"기행문의 끝부분에 들어가지 않는 내용은 어느 것인가요?","options":[{"t":"함께 가는 사람과 교통편","correct":true},{"t":"전체적인 느낌","mis":"K5-1-u2-X38"},{"t":"배운 것이나 더 알고 싶은 것","mis":"K5-1-u2-X38"},{"t":"앞으로의 각오","mis":"K5-1-u2-X38"}],"explanation":["끝에 들어가요.","끝에 들어가요.","교통편은 처음에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#7','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C4',1,'sa','auto','여행하며 다닌 곳, 보고 들은 것, 느낀 것을 함께 쓴 글을 무엇이라고 하나요?','{}'::text[],false,'{"seq":7,"concept":"K5-1-u2-C4","difficulty":1,"kind":"sa","stem":"여행하며 다닌 곳, 보고 들은 것, 느낀 것을 함께 쓴 글을 무엇이라고 하나요?","answer":["기행문"],"explanation":["여행 글이에요.","여정 · 견문 · 감상이 담겨요.","「기행문」이에요."],"mis":"K5-1-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#8','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C44',1,'mc','auto','한 면에 눈에 띄게 정리해 알리는 안내장 형태는 어느 것인가요?',ARRAY['K5-1-u2-X43','K5-1-u2-X04']::text[],false,'{"seq":8,"concept":"K5-1-u2-C44","difficulty":1,"kind":"mc","stem":"한 면에 눈에 띄게 정리해 알리는 안내장 형태는 어느 것인가요?","options":[{"t":"광고지","correct":true},{"t":"소책자","mis":"K5-1-u2-X43"},{"t":"그림엽서","mis":"K5-1-u2-X43"},{"t":"일정표","mis":"K5-1-u2-X04"}],"explanation":["여러 쪽이에요.","한 장면의 인상이에요.","한 면에 눈에 띄게 — 광고지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#9','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C12',2,'error','auto','솔미의 글을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X11','K5-1-u2-X10']::text[],false,'{"seq":9,"concept":"K5-1-u2-C12","difficulty":2,"kind":"error","stem":"솔미의 글을 읽고 친구들이 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「㉲도 〈지금〉과 〈떠오른다〉가 어색하니 고쳐야 해.」","correct":true,"mis_target":"K5-1-u2-X11"},{"t":"「㉮는 〈지난 금요일〉과 〈캔다〉가 어색해.」","mis":"K5-1-u2-X10"},{"t":"「㉳는 〈다음 주〉와 〈먹었다〉가 어색해.」","mis":"K5-1-u2-X10"}],"explanation":["㉮는 어색한 것이 맞아요.","㉳도 어색한 것이 맞아요.","㉲는 지금의 일을 지금의 말끝으로 썼어요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#10','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C31',2,'mc','auto','「돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.」에서 감상이 드러난 부분은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30']::text[],false,'{"seq":10,"concept":"K5-1-u2-C31","difficulty":2,"kind":"mc","stem":"「돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.」에서 감상이 드러난 부분은 어느 것인가요?","options":[{"t":"「마을이 나를 배웅하는 것 같았다」","correct":true},{"t":"「돌아오는 길」","mis":"K5-1-u2-X28"},{"t":"「차창 밖으로 멀어지는 느티나무를 보며」","mis":"K5-1-u2-X30"},{"t":"「차창 밖으로」","mis":"K5-1-u2-X28"}],"explanation":["때와 길을 알려 줘요.","본 모습이에요.","「~것 같았다」가 마음을 드러내요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#11','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C51',2,'blank','auto','㉱의 빈칸에 알맞은 낱말을 고르세요.',ARRAY['K5-1-u2-X50']::text[],false,'{"seq":11,"concept":"K5-1-u2-C51","difficulty":2,"kind":"blank","stem":"㉱의 빈칸에 알맞은 낱말을 고르세요.","options":[{"t":"다행히","correct":true},{"t":"다행희","mis":"K5-1-u2-X50"},{"t":"다행니","mis":"K5-1-u2-X50"},{"t":"다행케","mis":"K5-1-u2-X50"}],"explanation":["그런 낱말은 없어요.","그런 낱말은 없어요.","「다행히」로 써요."],"asset":{"type":"passage","lines":["㉮ 동생이 잠든 방 앞을 (　　) 지나갔다.","㉯ 쉬는 시간마다 (　　) 여행 일기를 적었다.","㉰ 방 안을 (　　) 뒤졌지만 열쇠는 보이지 않았다.","㉱ 넘어졌는데 (　　) 크게 다치지는 않았다."],"title":"빈칸에 들어갈 낱말"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#12','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C21',2,'mc','auto','「다음 주 월요일부터 닷새 동안」에서 행사의 마지막 날은 무슨 요일인가요?',ARRAY['K5-1-u2-X14']::text[],false,'{"seq":12,"concept":"K5-1-u2-C21","difficulty":2,"kind":"mc","stem":"「다음 주 월요일부터 닷새 동안」에서 행사의 마지막 날은 무슨 요일인가요?","options":[{"t":"금요일","correct":true},{"t":"목요일","mis":"K5-1-u2-X14"},{"t":"토요일","mis":"K5-1-u2-X14"},{"t":"수요일","mis":"K5-1-u2-X14"}],"explanation":["나흘째 날이에요.","엿새째 날이에요.","월 · 화 · 수 · 목 · 금 — 닷새예요."],"asset":{"type":"passage","lines":["오늘은 월요일이다.","우리 반은 모레인 수요일부터 금요일까지 학급 문고 정리를 한다.","정리가 끝나면 그다음 주 월요일부터 닷새 동안 책 바꿔 읽기 행사를 연다."],"title":"채온이네 반의 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#13','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C13',2,'error','auto','시간 표현에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X11','K5-1-u2-X10']::text[],false,'{"seq":13,"concept":"K5-1-u2-C13","difficulty":2,"kind":"error","stem":"시간 표현에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「〈지금 숙제 다 했어〉는 틀린 문장이니 꼭 고쳐야 해.」","correct":true,"mis_target":"K5-1-u2-X11"},{"t":"「〈아까 우유를 마실 것이다〉는 어색해.」","mis":"K5-1-u2-X10"},{"t":"「소리 내어 읽어 보고 어색하지 않으면 그대로 둬.」","mis":"K5-1-u2-X11"}],"explanation":["어색한 것이 맞아요.","판단 기준이 맞아요.","어색하지 않으니 고치지 않아도 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#14','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C32',2,'mc','auto','견문과 감상을 바르게 가른 친구는 누구인가요?',ARRAY['K5-1-u2-X31']::text[],false,'{"seq":14,"concept":"K5-1-u2-C32","difficulty":2,"kind":"mc","stem":"견문과 감상을 바르게 가른 친구는 누구인가요?","options":[{"t":"「누렇게 익은 벼는 누구나 볼 수 있으니 견문이고, 배웅하는 것 같다는 건 가비의 마음이니 감상이야.」","correct":true},{"t":"「문장이 짧으면 견문이고 길면 감상이야.」","mis":"K5-1-u2-X31"},{"t":"「꾸미는 말이 많으면 감상이야.」","mis":"K5-1-u2-X31"},{"t":"「글 앞쪽은 견문이고 뒤쪽은 감상이야.」","mis":"K5-1-u2-X31"}],"explanation":["길이로 가르지 않아요.","꾸미는 말로 가르지 않아요.","누구나 확인할 수 있는지로 갈랐어요."],"asset":{"type":"passage","lines":["다음으로 개울을 건너 떡방앗간에 들렀다.","김이 피어오르는 시루에서 갓 찐 떡을 꺼내고 있었다.","방앗간 아주머니께서는 명절 전 사흘 동안은 새벽부터 쉬지 않고 떡을 찐다고 하셨다.","마지막으로 저수지 둑길을 걸었다. 둑 아래로 누렇게 익은 벼가 끝없이 펼쳐져 있었다.","돌아오는 길, 차창 밖으로 멀어지는 느티나무를 보며 마을이 나를 배웅하는 것 같았다.","설에 다시 가면 외할머니와 함께 떡을 빚어 보고 싶다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#15','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C36',2,'mc','auto','기행문을 남기는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['K5-1-u2-X35']::text[],false,'{"seq":15,"concept":"K5-1-u2-C36","difficulty":2,"kind":"mc","stem":"기행문을 남기는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"「기행문은 꼭 공책에 글로만 남겨야 한다」","correct":true},{"t":"「여행 그림에 짧은 글을 곁들인다」","mis":"K5-1-u2-X35"},{"t":"「엽서에 여행한 이야기를 적어 보낸다」","mis":"K5-1-u2-X35"},{"t":"「다닌 곳을 찍은 동영상에 느낌을 말로 담는다」","mis":"K5-1-u2-X35"}],"explanation":["그림으로도 남겨요.","엽서도 형식이에요.","여러 형식으로 남길 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#16','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C48',2,'mc','auto','율하의 문구를 듣고 한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K5-1-u2-X47','K5-1-u2-X27']::text[],false,'{"seq":16,"concept":"K5-1-u2-C48","difficulty":2,"kind":"mc","stem":"율하의 문구를 듣고 한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「〈하루가 천천히 흘러갑니다〉라는 말에서 쉼터에 가 보고 싶어졌어.」","correct":true},{"t":"「잘했어.」","mis":"K5-1-u2-X47"},{"t":"「글자가 많네.」","mis":"K5-1-u2-X27"},{"t":"「종이가 예뻐.」","mis":"K5-1-u2-X27"}],"explanation":["무엇이 좋았는지 빠졌어요.","문구를 짚지 않았어요.","어느 문구에서 가 보고 싶어졌는지 짚었어요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#17','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C49',3,'error','auto','단원을 정리하며 한 말이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X48','K5-1-u2-X37','K5-1-u2-X32']::text[],false,'{"seq":17,"concept":"K5-1-u2-C49","difficulty":3,"kind":"error","stem":"단원을 정리하며 한 말이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「기행문에서는 지난 일과 지금의 일을 마구 섞어 써도 괜찮아.」","correct":true,"mis_target":"K5-1-u2-X48"},{"t":"「다닌 곳의 차례는 시간의 흐름과 함께 움직여.」","mis":"K5-1-u2-X37"},{"t":"「여정 · 견문 · 감상을 한 문단 안에서 이어도 돼.」","mis":"K5-1-u2-X32"}],"explanation":["차례와 시간은 함께 가요.","셋을 이어도 돼요.","시간 표현이 흔들리면 다닌 길도 흐트러져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#18','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C27',3,'error','auto','솔미의 초안을 고쳐 쓰는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X26','K5-1-u2-X21','K5-1-u2-X10']::text[],false,'{"seq":18,"concept":"K5-1-u2-C27","difficulty":3,"kind":"error","stem":"솔미의 초안을 고쳐 쓰는 방법에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「맞춤법만 다시 보면 고쳐 쓰기는 끝이야.」","correct":true,"mis_target":"K5-1-u2-X26"},{"t":"「〈지난 금요일〉에 맞게 〈캤다〉로 고쳐.」","mis":"K5-1-u2-X21"},{"t":"「㉳는 〈다음 주〉에 맞게 앞일의 말끝으로 고쳐.」","mis":"K5-1-u2-X10"}],"explanation":["시간 표현을 고치는 것은 맞아요.","㉳를 고치는 것도 맞아요.","고쳐 쓰기의 기준은 여럿이에요."],"asset":{"type":"passage","lines":["㉮ 지난 금요일에 우리 반은 학교 텃밭에서 고구마를 캔다.","㉯ 봄에 심은 고구마 줄기가 땅을 덮을 만큼 길게 뻗어 있었다.","㉰ 호미로 흙을 살살 걷어 내자 붉은 고구마가 줄줄이 딸려 나왔다.","㉱ 생각보다 커서 친구들과 함께 소리를 질렀다.","㉲ 지금 나는 고구마를 볼 때마다 그날 흙 냄새가 떠오른다.","㉳ 다음 주에는 캔 고구마를 쪄서 다 같이 나누어 먹었다."],"title":"솔미의 글 초안 「고구마를 캔 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#19','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C37',3,'ox','auto','가비의 기행문 처음 부분에는 떠난 까닭이나 기대가 드러나 있어요.',ARRAY['K5-1-u2-X36']::text[],false,'{"seq":19,"concept":"K5-1-u2-C37","difficulty":3,"kind":"ox","stem":"가비의 기행문 처음 부분에는 떠난 까닭이나 기대가 드러나 있어요.","answer":"O","reason_options":[{"t":"「마을을 구경시켜 주신다고 해서 아침부터 마음이 들떴다」에 기대와 기분이 드러나기 때문에","correct":true},{"t":"처음 부분에는 견문과 감상만 있기 때문에","mis":"K5-1-u2-X36"}],"mis":"K5-1-u2-X36","explanation":["맞는 말이에요.","처음에 견문만 있지 않아요.","떠나기 전의 기대가 드러나요."],"asset":{"type":"passage","lines":["추석 연휴에 우리 가족은 자동차를 타고 외갓집에 다녀왔다.","외할머니께서 마을을 한 바퀴 구경시켜 주신다고 해서 아침부터 마음이 들떴다.","우리는 먼저 마을 입구의 커다란 느티나무 아래로 갔다.","외할머니께서는 이 나무가 마을이 생길 때 심은 나무라고 말씀하셨다.","굵은 줄기를 두 팔로 안아 보니, 마을 사람들을 오래 지켜 온 할아버지 같았다."],"title":"가비의 기행문 「외갓집 마을을 한 바퀴」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#20','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C30',3,'mc','auto','「모래벌판을 지나」에서 들은 것을 쓴 견문은 어느 것인가요?',ARRAY['K5-1-u2-X28','K5-1-u2-X30']::text[],false,'{"seq":20,"concept":"K5-1-u2-C30","difficulty":3,"kind":"mc","stem":"「모래벌판을 지나」에서 들은 것을 쓴 견문은 어느 것인가요?","options":[{"t":"「바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다」","correct":true},{"t":"「우리는 먼저 해안 사구 탐방로에 들어섰다」","mis":"K5-1-u2-X28"},{"t":"「바람이 이렇게 오래 일한다는 사실이 놀라웠다」","mis":"K5-1-u2-X30"},{"t":"「다음에는 바람이 센 계절에 다시 와 보고 싶다」","mis":"K5-1-u2-X30"}],"explanation":["다닌 곳이에요.","놀란 마음이에요.","「~라고 한다」는 들은 설명이에요."],"asset":{"type":"passage","lines":["지난 봄, 우리 가족은 태안 신두리로 여행을 떠났다. 바닷가 모래 언덕이 궁금했기 때문이다.","우리는 먼저 해안 사구 탐방로에 들어섰다. 발밑에서 모래가 자꾸 무너졌다.","이곳의 모래 언덕은 바람이 수천 년 동안 모래를 실어 나르며 만들어진 것이라고 한다.","바람이 이렇게 오래 일한다는 사실이 놀라웠다.","다음으로 언덕 너머 습지에 이르렀다. 마른 모래땅 바로 옆에 물이 고여 풀이 자라고 있었다.","돌아오는 길에 신발 속 모래를 털어 냈다.","발끝에 남은 모래가 여행을 조금 더 데리고 온 것 같았다. 다음에는 바람이 센 계절에 다시 와 보고 싶다."],"title":"「모래벌판을 지나」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#21','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C20',3,'error','auto','「금방」과 「금세」에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?',ARRAY['K5-1-u2-X18']::text[],false,'{"seq":21,"concept":"K5-1-u2-C20","difficulty":3,"kind":"error","stem":"「금방」과 「금세」에 대해 말한 것이에요. 알맞지 않은 말은 어느 것인가요?","options":[{"t":"「〈금방〉은 언제나 조금 전만 뜻해.」","correct":true,"mis_target":"K5-1-u2-X18"},{"t":"「〈비가 금방 그칠 거야〉에서는 곧을 뜻해.」","mis":"K5-1-u2-X18"},{"t":"「〈금세 퍼졌다〉에서는 아주 빠르게를 뜻해.」","mis":"K5-1-u2-X18"}],"explanation":["곧을 뜻하는 것이 맞아요.","빠르기를 뜻하는 것이 맞아요.","앞뒤 문장에 따라 때가 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#22','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C41',3,'mc','auto','기행문 개요의 가운데 칸을 바르게 짠 것은 어느 것인가요?',ARRAY['K5-1-u2-X32','K5-1-u2-X36','K5-1-u2-X37']::text[],false,'{"seq":22,"concept":"K5-1-u2-C41","difficulty":3,"kind":"mc","stem":"기행문 개요의 가운데 칸을 바르게 짠 것은 어느 것인가요?","options":[{"t":"느티나무 — 마을이 생길 때 심었다 · 할아버지 같다 / 방앗간 — 갓 찐 떡 · 다시 와서 빚고 싶다","correct":true},{"t":"느티나무 · 방앗간 · 둑길 / 본 것 모음 / 느낀 것 모음","mis":"K5-1-u2-X32"},{"t":"설에 다시 가고 싶다 / 추석에 출발 / 자동차","mis":"K5-1-u2-X36"},{"t":"느티나무 / 방앗간 / 둑길","mis":"K5-1-u2-X37"}],"explanation":["셋을 따로 떼었어요.","처음과 끝의 내용이에요.","다닌 곳별로 견문과 감상을 나란히 적었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#23','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C46',4,'essay','teacher','해솜이의 안내장 문구를 감상이 드러나게 고쳐 쓰고, 율하의 문구와 견주어 안내장에 감상을 넣으면 무엇이 좋은지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K5-1-u2-C46","difficulty":4,"kind":"essay","stem":"해솜이의 안내장 문구를 감상이 드러나게 고쳐 쓰고, 율하의 문구와 견주어 안내장에 감상을 넣으면 무엇이 좋은지 쓰세요.","answer_guide":{"answer":"예: 「느티나무 쉼터: 마을 입구에 있습니다. 넓은 그늘에 앉으면 마을을 오래 지켜 온 나무가 나를 감싸 주는 것 같습니다.」 율하의 문구처럼 느낌이 담기면 위치만 알려 줄 때보다 읽는 사람이 그곳에 가 보고 싶어진다. 정보만 있으면 안내판이 되기 때문이다.","scoring_points":["해솜이의 정보를 살려 고쳐 썼는가","감상을 넣었는가","감상을 넣으면 좋은 점을 썼는가"]},"explanation":["정보는 살려요.","느낌을 한 문장 더해요.","율하의 문구와 견주어요."],"asset":{"type":"passage","lines":["해솜 — 「느티나무 쉼터: 마을 입구에 있습니다. 그늘이 넓습니다.」","율하 — 「느티나무 쉼터: 두 팔로 안아도 다 안기지 않는 나무 아래에서","　　　 바람 소리를 들으면 하루가 천천히 흘러갑니다.」"],"title":"두 친구가 쓴 안내장 문구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#24','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C22',4,'essay','teacher','「손끝으로 고친 책들」 뒷부분처럼 「예전 → 요즘 → 앞으로」의 흐름이 드러나게, 내가 달라진 일 하나를 세 문장으로 쓰세요. 문장마다 알맞은 말끝을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K5-1-u2-C22","difficulty":4,"kind":"essay","stem":"「손끝으로 고친 책들」 뒷부분처럼 「예전 → 요즘 → 앞으로」의 흐름이 드러나게, 내가 달라진 일 하나를 세 문장으로 쓰세요. 문장마다 알맞은 말끝을 쓰세요.","answer_guide":{"answer":"예: 예전에는 채소를 먹기 싫어서 늘 접시 한쪽으로 밀어 두었다. 요즘 나는 텃밭에서 기른 상추를 고기에 싸서 맛있게 먹는다. 앞으로는 다른 채소도 하나씩 길러 먹어 볼 것이다.","scoring_points":["예전 · 요즘 · 앞으로의 흐름이 드러나는가","문장마다 알맞은 말끝을 썼는가","하나의 달라진 일로 이어지는가"]},"explanation":["달라진 일 하나를 골라요.","세 때로 나누어요.","말끝을 때에 맞춰요."],"asset":{"type":"passage","lines":["두 시간쯤 지나자 상자에 남은 책이 절반으로 줄었다.","내 손을 거친 책이 다시 읽힌다는 것이 뿌듯했다.","예전에는 책이 낡으면 그냥 버리는 줄 알았다.","하지만 직접 해 보니 조금만 손보면 오래 쓸 수 있는 책이 많았다.","요즘 나는 책을 볼 때 모서리를 접지 않고 조심해서 넘긴다.","다음 달에도 봉사 활동에 참여할 것이다.","그때는 표지를 다시 씌우는 일까지 배워 보고 싶다."],"title":"「손끝으로 고친 책들」 뒷부분"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_1_kor_u2_review_d#25','kor',5,1,'u2','','g5_1_kor_u2_review_d','unit_review','K5-1-u2-C36',4,'essay','teacher','여행지 안내장과 기행문은 무엇이 같고 무엇이 다른지 쓰고, 안내장에도 감상을 넣어야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K5-1-u2-C36","difficulty":4,"kind":"essay","stem":"여행지 안내장과 기행문은 무엇이 같고 무엇이 다른지 쓰고, 안내장에도 감상을 넣어야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 둘 다 여정 · 견문 · 감상을 담는다. 기행문은 내가 다녀온 여행을 돌아보며 쓴 글이고, 안내장은 그곳에 가려는 사람에게 갈 만한 곳 · 먹을거리 · 즐길 거리를 권하는 글이다. 안내장에 정보만 있으면 안내판이 되고 느낌이 담겨야 읽는 사람이 가 보고 싶어지므로 감상을 넣어야 한다.","scoring_points":["같은 점을 썼는가","다른 점을 썼는가","감상을 넣는 까닭을 썼는가"]},"explanation":["세 요소를 떠올려요.","누구에게 쓰는 글인가요?","안내판과 견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
